{"id":1,"name":"Sweet And Spicy Shrimp With Garlic","filipino_name":"Gambas","category":"Appetizers","prep_time_text":"10 minutes","cook_time_text":"10 minutes","yield_type":"serves","yield_text":"4","ingredients":[{"source_text":"3 tablespoons vegetable oil or olive oil","source_pdf_page":18,"section":null,"position":1,"match_options":["vegetable oil","olive oil"],"match_rule":"any_of","role":"main","required_for_matching":true,"quantity_prefix_text":"3 tablespoons","related_recipe_id":null},{"source_text":"8 garlic cloves, coarsely chopped","source_pdf_page":18,"section":null,"position":2,"match_options":["garlic"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"8","related_recipe_id":null},{"source_text":"1 teaspoon red pepper flakes","source_pdf_page":18,"section":null,"position":3,"match_options":["red pepper flake"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 teaspoon","related_recipe_id":null},{"source_text":"1 pound large whole shrimp","source_pdf_page":18,"section":null,"position":4,"match_options":["shrimp"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 pound","related_recipe_id":null},{"source_text":"3 tablespoons rice wine (see tip)","source_pdf_page":18,"section":null,"position":5,"match_options":["rice wine"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3 tablespoons","related_recipe_id":null},{"source_text":"2 tablespoons tomato sauce","source_pdf_page":18,"section":null,"position":6,"match_options":["tomato sauce"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 tablespoons","related_recipe_id":null},{"source_text":"2 tablespoons ketchup","source_pdf_page":18,"section":null,"position":7,"match_options":["ketchup"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 tablespoons","related_recipe_id":null},{"source_text":"1 tablespoon brown sugar","source_pdf_page":18,"section":null,"position":8,"match_options":["brown sugar"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 tablespoon","related_recipe_id":null},{"source_text":"1/2 teaspoon smoked paprika","source_pdf_page":18,"section":null,"position":9,"match_options":["smoked paprika"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2 teaspoon","related_recipe_id":null},{"source_text":"Pinch sea salt","source_pdf_page":18,"section":null,"position":10,"match_options":["salt"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"Pinch","related_recipe_id":null},{"source_text":"Pinch freshly ground black pepper","source_pdf_page":18,"section":null,"position":11,"match_options":["black pepper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"Pinch","related_recipe_id":null},{"source_text":"1/4 cup chopped fresh parsley","source_pdf_page":18,"section":null,"position":12,"match_options":["parsley"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/4 cup","related_recipe_id":null},{"source_text":"Calamansi or lemon, halved, for serving","source_pdf_page":18,"section":null,"position":13,"match_options":["calamansi","lemon"],"match_rule":"any_of","role":"serving","required_for_matching":false,"quantity_prefix_text":null,"related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"In a wok or large frying pan, heat the vegetable oil over medium heat. Add the garlic and red pepper flakes and cook for about 30 seconds, stirring constantly, until the garlic is fragrant."},{"step":2,"source_step":2,"section":null,"text":"Adjust the heat to high, add the shrimp and rice wine, and cook for about 1 minute, stirring constantly, until the wine is simmering."},{"step":3,"source_step":3,"section":null,"text":"Add the tomato sauce, ketchup, brown sugar, and paprika and cook for 3 to 6 minutes, until the shrimp turns opaque and is cooked through. Season with salt and pepper."},{"step":4,"source_step":4,"section":null,"text":"Transfer to a serving platter and garnish with parsley and calamansi halves. Squeeze the juice on the shrimp before enjoying."}],"source_tips":["SUBSTITUTION TIP: White wine can be used to replace the rice wine."],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[18],"printed_pages":[10]},"review_flags":[],"prep_minutes":10,"cook_minutes":10,"additional_time_text":null,"default_image":null,"slug":"sweet-and-spicy-shrimp-with-garlic"},
{"id":2,"name":"Tuna Kilawin","filipino_name":"Kilawin Na Tuna","category":"Appetizers","prep_time_text":"15 minutes, plus 1 hour to marinate","cook_time_text":null,"yield_type":"serves","yield_text":"4 to 6","ingredients":[{"source_text":"1 red onion, finely chopped","source_pdf_page":19,"section":null,"position":1,"match_options":["red onion"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"1 cup vinegar","source_pdf_page":19,"section":null,"position":2,"match_options":["vinegar"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 cup","related_recipe_id":null},{"source_text":"5 scallions, finely chopped, both green and white parts, divided","source_pdf_page":19,"section":null,"position":3,"match_options":["scallion"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"5","related_recipe_id":null},{"source_text":"3 labuyo chiles or 1 jalapeño, chopped (seeds included)","source_pdf_page":19,"section":null,"position":4,"match_options":["labuyo chili","jalapeno"],"match_rule":"any_of","role":"main","required_for_matching":true,"quantity_prefix_text":"3","quantity_note":"Display source_text to preserve compound quantities and/or alternative amounts; quantity_prefix_text is only the leading amount.","related_recipe_id":null},{"source_text":"1 tablespoon finely chopped garlic","source_pdf_page":19,"section":null,"position":5,"match_options":["garlic"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 tablespoon","related_recipe_id":null},{"source_text":"1 tablespoon finely chopped ginger","source_pdf_page":19,"section":null,"position":6,"match_options":["ginger"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 tablespoon","related_recipe_id":null},{"source_text":"1 tablespoon salt","source_pdf_page":19,"section":null,"position":7,"match_options":["salt"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 tablespoon","related_recipe_id":null},{"source_text":"Pinch freshly ground black pepper","source_pdf_page":19,"section":null,"position":8,"match_options":["black pepper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"Pinch","related_recipe_id":null},{"source_text":"2 pounds fresh tuna, cut into 1/2-inch cubes","source_pdf_page":19,"section":null,"position":9,"match_options":["tuna"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 pounds","related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"In a medium bowl, toss the onion, vinegar, 4 tablespoons of the scallions, chiles, garlic, ginger, salt, and pepper."},{"step":2,"source_step":2,"section":null,"text":"Using a spatula, stir the tuna into the mixture."},{"step":3,"source_step":3,"section":null,"text":"Cover with plastic wrap and refrigerate for 1 hour before serving."},{"step":4,"source_step":4,"section":null,"text":"Sprinkle the reserved tablespoon of scallions for garnish and serve cold."}],"source_tips":["VARIATION TIP: There are many variations of kilawin, but one of my favorites is made by adding about 2 cups of coconut milk in step 1 to add a little sweetness."],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[19],"printed_pages":[11]},"review_flags":["Additional waiting time is retained as text; do not display prep + cook as total elapsed time."],"prep_minutes":15,"cook_minutes":null,"additional_time_text":"1 hour to marinate","default_image":null,"slug":"tuna-kilawin"},
{"id":3,"name":"Crackling Pork","filipino_name":"Chicharon","category":"Appetizers","prep_time_text":"25 minutes, plus 1 hour to chill","cook_time_text":"1 hour 20 minutes","yield_type":"serves","yield_text":"4 to 6","ingredients":[{"source_text":"2 pounds pork skin","source_pdf_page":20,"section":null,"position":1,"match_options":["pork skin"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 pounds","related_recipe_id":null},{"source_text":"1 onion, peeled and halved","source_pdf_page":20,"section":null,"position":2,"match_options":["onion"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"8 whole black peppercorns","source_pdf_page":20,"section":null,"position":3,"match_options":["black peppercorn"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"8","related_recipe_id":null},{"source_text":"2 bay leaves","source_pdf_page":20,"section":null,"position":4,"match_options":["bay leaf"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2","related_recipe_id":null},{"source_text":"Vegetable oil, for frying","source_pdf_page":20,"section":null,"position":5,"match_options":["vegetable oil"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":null,"related_recipe_id":null},{"source_text":"Salt","source_pdf_page":20,"section":null,"position":6,"match_options":["salt"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":null,"related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"Wash the pork skin thoroughly and cut it into 3-inch squares, leaving minimal fat and meat on it."},{"step":2,"source_step":2,"section":null,"text":"Place the pork skin in a deep pot and cover it with a few inches of water. Add the onion, peppercorns, and bay leaves and boil over high heat for 1 hour, skimming the foam off the surface as it cooks. Boil until the skin is tender but not mushy."},{"step":3,"source_step":3,"section":null,"text":"When tender, use tongs to remove the pork skin from the pot and transfer it to a colander to drain. Cool to room temperature, and then freeze for 1 hour."},{"step":4,"source_step":4,"section":null,"text":"In a deep fryer or large deep pot, heat 3 inches of oil over medium-high heat to 350°F, or until shimmering and the end of a wooden spoon dipped into the oil produces bubbles."},{"step":5,"source_step":5,"section":null,"text":"Fry the skin in batches, and avoid overcrowding the pot. When the skin floats and is lightly browned, it is ready, about 8 minutes per batch."},{"step":6,"source_step":6,"section":null,"text":"Using tongs, transfer the skin to a paper-towel-lined plate and season with salt. Let cool for a few minutes before serving."}],"source_tips":["VARIATION TIP: Add 2 cups of vinegar to the water before boiling for salt-and-vinegar-flavored chicharon."],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[20,21],"printed_pages":[12,13]},"review_flags":["Additional waiting time is retained as text; do not display prep + cook as total elapsed time.","Instructions mention water outside the ingredient list; source list retained. Review cooking/soaking water handling in the app."],"prep_minutes":25,"cook_minutes":80,"additional_time_text":"1 hour to chill","default_image":null,"slug":"crackling-pork"},
{"id":4,"name":"Crispy Pork Belly With Sweet Vinegar Dipping Sauce","filipino_name":"Lechon Kawali","category":"Appetizers","prep_time_text":"10 minutes","cook_time_text":"1 hour 45 minutes","yield_type":"serves","yield_text":"4 to 6","ingredients":[{"source_text":"2 pounds pork belly, cut into 4-inch-by-5-inch pieces","source_pdf_page":22,"section":"FOR THE PORK BELLY","position":1,"match_options":["pork"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 pounds","related_recipe_id":null},{"source_text":"1 onion, halved","source_pdf_page":22,"section":"FOR THE PORK BELLY","position":2,"match_options":["onion"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"1/2 cup salt","source_pdf_page":22,"section":"FOR THE PORK BELLY","position":3,"match_options":["salt"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2 cup","related_recipe_id":null},{"source_text":"2 bay leaves","source_pdf_page":22,"section":"FOR THE PORK BELLY","position":4,"match_options":["bay leaf"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2","related_recipe_id":null},{"source_text":"1/2 teaspoon black peppercorns","source_pdf_page":22,"section":"FOR THE PORK BELLY","position":5,"match_options":["black peppercorn"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2 teaspoon","related_recipe_id":null},{"source_text":"Vegetable oil, for frying","source_pdf_page":22,"section":"FOR THE PORK BELLY","position":6,"match_options":["vegetable oil"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":null,"related_recipe_id":null},{"source_text":"1/2 cup vinegar","source_pdf_page":22,"section":"FOR THE DIPPING SAUCE","position":7,"match_options":["vinegar"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2 cup","related_recipe_id":null},{"source_text":"1/2 cup sugar","source_pdf_page":22,"section":"FOR THE DIPPING SAUCE","position":8,"match_options":["sugar"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2 cup","related_recipe_id":null},{"source_text":"1 tablespoon finely diced shallots","source_pdf_page":22,"section":"FOR THE DIPPING SAUCE","position":9,"match_options":["shallot"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 tablespoon","related_recipe_id":null},{"source_text":"1 tablespoon finely chopped garlic","source_pdf_page":22,"section":"FOR THE DIPPING SAUCE","position":10,"match_options":["garlic"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 tablespoon","related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":"TO MAKE THE PORK BELLY","text":"Score the pork diagonally, then turn the meat 90 degrees and again score diagonally to create a crosshatching pattern. Place the pork belly in a deep pot and cover with water by a few inches."},{"step":2,"source_step":2,"section":"TO MAKE THE PORK BELLY","text":"Add the onion, salt, bay leaves, and peppercorns and boil over high heat for 1 hour, until the meat is tender. Add extra water during cooking to keep the meat covered, if needed."},{"step":3,"source_step":3,"section":"TO MAKE THE PORK BELLY","text":"Using long tongs, remove the pork belly from the pot and drain in a colander."},{"step":4,"source_step":4,"section":"TO MAKE THE PORK BELLY","text":"Fry immediately, or to ensure that the skin is crispy, cool to room temperature, wrap with plastic wrap, and chill in the freezer for 1 hour."},{"step":5,"source_step":5,"section":"TO MAKE THE PORK BELLY","text":"In a large deep pot, heat 4 inches of vegetable oil over medium-high heat until the oil reaches 350°F or it is shimmering, and the end of a wooden spoon dipped into it produces bubbles."},{"step":6,"source_step":6,"section":"TO MAKE THE PORK BELLY","text":"Using long tongs, carefully and slowly lower the pork belly in the pot and fry for 30 to 45 minutes, or until golden brown and the sizzling and crackling slows down."},{"step":7,"source_step":7,"section":"TO MAKE THE PORK BELLY","text":"Turn off the heat and, using the tongs, transfer the pork belly to a paper-towel-lined plate. Season with salt. Cut into 1/2-inch pieces and serve with the dipping sauce."},{"step":8,"source_step":null,"section":"TO MAKE THE DIPPING SAUCE","text":"In a bowl, combine the vinegar, sugar, shallots, and garlic and mix well."}],"source_tips":["COOKING TIP: To cook in an oven, score the skin as in step 1, or if you’re running low on time, use the tip of a paring knife to poke 10 to 15 holes in the skin before cooking. Preheat the oven to 350°F and place the pork belly on a sheet pan. Cook for 1 1/2 hours, then turn the heat up to 450°F and cook for 30 minutes more.","PREP TIP: The initial boiling step can be completed in an electric pressure cooker. Place the pork belly, onion, salt, bay leaves, peppercorns, and 1 cup of water in the pressure cooker. Cover and cook on high pressure for 20 minutes. When cooking is complete, allow the pressure to release naturally for 10 minutes before quick releasing any remaining pressure. Drain and continue with step 4, then complete the recipe as directed."],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[22,23],"printed_pages":[14,15]},"review_flags":["Multi-component recipe: preserve ingredient sections and instruction sections.","Instructions mention water outside the ingredient list; source list retained. Review cooking/soaking water handling in the app."],"prep_minutes":10,"cook_minutes":105,"additional_time_text":null,"default_image":null,"slug":"crispy-pork-belly-with-sweet-vinegar-dipping-sauce"},
{"id":5,"name":"Pork Sisig","filipino_name":"Sisig Baboy","category":"Appetizers","prep_time_text":"5 minutes","cook_time_text":"1 hour 30 minutes","yield_type":"serves","yield_text":"4 to 6","ingredients":[{"source_text":"2 pounds pork belly, cut into 4-inch-by-5-inch pieces","source_pdf_page":24,"section":null,"position":1,"match_options":["pork"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 pounds","related_recipe_id":null},{"source_text":"1 yellow onion, quartered","source_pdf_page":24,"section":null,"position":2,"match_options":["yellow onion"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"2 bay leaves","source_pdf_page":24,"section":null,"position":3,"match_options":["bay leaf"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2","related_recipe_id":null},{"source_text":"Vegetable oil, for frying","source_pdf_page":24,"section":null,"position":4,"match_options":["vegetable oil"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":null,"related_recipe_id":null},{"source_text":"1/2 cup, plus 1 tablespoon finely chopped scallions, divided","source_pdf_page":24,"section":null,"position":5,"match_options":["scallion"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2 cup","quantity_note":"Display source_text to preserve compound quantities and/or alternative amounts; quantity_prefix_text is only the leading amount.","related_recipe_id":null},{"source_text":"1/2 cup freshly squeezed calamansi or lemon juice","source_pdf_page":24,"section":null,"position":6,"match_options":["calamansi","lemon"],"match_rule":"any_of","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2 cup","quantity_note":"Display source_text to preserve compound quantities and/or alternative amounts; quantity_prefix_text is only the leading amount.","related_recipe_id":null},{"source_text":"1 tablespoon salt","source_pdf_page":24,"section":null,"position":7,"match_options":["salt"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 tablespoon","related_recipe_id":null},{"source_text":"1/4 teaspoon freshly ground black pepper","source_pdf_page":24,"section":null,"position":8,"match_options":["black pepper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/4 teaspoon","related_recipe_id":null},{"source_text":"1 calamansi or lemon, cut into quarters","source_pdf_page":24,"section":null,"position":9,"match_options":["calamansi","lemon"],"match_rule":"any_of","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"In a deep pot, place the pork belly pieces and cover with cold water by several inches. Add the onion and bay leaves and cook over high heat for 1 hour or until the pork is tender."},{"step":2,"source_step":2,"section":null,"text":"Using long tongs, transfer the pork belly to a colander to drain."},{"step":3,"source_step":3,"section":null,"text":"In a large deep pot, heat 4 inches of vegetable oil on high heat until the oil is hot, between 350°F and 375°F, or until shimmering and the end of a wooden spoon dipped into the oil produces bubbles."},{"step":4,"source_step":4,"section":null,"text":"Using long tongs, slowly and carefully lower the boiled pork belly into the oil and fry until golden brown, 20 to 30 minutes."},{"step":5,"source_step":5,"section":null,"text":"Transfer the pork belly to a paper-towel-lined bowl to remove excess oil."},{"step":6,"source_step":6,"section":null,"text":"Chop the pork belly roughly into a small dice and transfer to a medium bowl. Add all but 2 tablespoons of the scallions, calamansi juice, salt, and pepper."},{"step":7,"source_step":7,"section":null,"text":"Transfer to a platter and garnish with calamansi wedges and remaining 2 tablespoons scallions."}],"source_tips":["INGREDIENT TIP: Pork belly is a fatty cut of meat from the underside of the pig and is commonly used to make bacon. It has three distinct layers—the skin, ribbons of fat, and a layer of reddish meat. Buy fresh pork belly at a butcher or Asian market."],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[24,25],"printed_pages":[16,17]},"review_flags":["Instructions mention water outside the ingredient list; source list retained. Review cooking/soaking water handling in the app."],"prep_minutes":5,"cook_minutes":90,"additional_time_text":null,"default_image":null,"slug":"pork-sisig"},
{"id":6,"name":"Crispy Pork Hock","filipino_name":"Crispy Pata","category":"Appetizers","prep_time_text":"5 minutes","cook_time_text":"1 hour 30 minutes","yield_type":"serves","yield_text":"2 to 4","ingredients":[{"source_text":"1 pork hock","source_pdf_page":26,"section":null,"position":1,"match_options":["pork hock"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"1 onion, peeled and halved","source_pdf_page":26,"section":null,"position":2,"match_options":["onion"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"2 bay leaves","source_pdf_page":26,"section":null,"position":3,"match_options":["bay leaf"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2","related_recipe_id":null},{"source_text":"2 tablespoons plus 1 teaspoon salt, divided","source_pdf_page":26,"section":null,"position":4,"match_options":["salt"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 tablespoons","quantity_note":"Display source_text to preserve compound quantities and/or alternative amounts; quantity_prefix_text is only the leading amount.","related_recipe_id":null},{"source_text":"1 tablespoon whole black peppercorns","source_pdf_page":26,"section":null,"position":5,"match_options":["black peppercorn"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 tablespoon","related_recipe_id":null},{"source_text":"12 cups water","source_pdf_page":26,"section":null,"position":6,"match_options":["water"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"12 cups","related_recipe_id":null},{"source_text":"1 teaspoon garlic powder","source_pdf_page":26,"section":null,"position":7,"match_options":["garlic powder"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 teaspoon","related_recipe_id":null},{"source_text":"Pinch freshly ground black pepper","source_pdf_page":26,"section":null,"position":8,"match_options":["black pepper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"Pinch","related_recipe_id":null},{"source_text":"Canola oil, for frying","source_pdf_page":26,"section":null,"position":9,"match_options":["canola oil"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":null,"related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"In a large pot, place the pork, onion, bay leaves, 2 tablespoons of salt, and peppercorns. Cover with the water and bring to a boil over medium-high heat, skimming the foam off the surface as it cooks. Reduce the heat to medium-low and simmer for 1 hour."},{"step":2,"source_step":2,"section":null,"text":"Turn off the heat and, using tongs, transfer the pork to a colander to drain. Let it sit until it is cool to the touch. Discard the water and aromatics."},{"step":3,"source_step":3,"section":null,"text":"Rub the pork hock with the remaining 1 teaspoon of salt and the garlic powder, and a pinch of ground black pepper."},{"step":4,"source_step":4,"section":null,"text":"In a large deep pot, heat 5 to 6 inches of canola oil (or enough to completely cover the pork hock) over medium heat to 350°F, or until shimmering and the end of a wooden spoon dipped into the oil produces bubbles."},{"step":5,"source_step":5,"section":null,"text":"Using long tongs, slowly and carefully lower the hock into the oil. Fry for 30 minutes, until the sizzling slows down and the skin becomes crispy."},{"step":6,"source_step":6,"section":null,"text":"Remove the pork from the oil and transfer it to a paper-towel-lined plate to cool."}],"source_tips":["COOKING TIP: Step 1 can be completed in an electric pressure cooker. Cook for 20 minutes on high pressure and let the pressure release naturally for 15 minutes, before quick releasing any remaining pressure and continuing with the recipe as written."],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[26,27],"printed_pages":[18,19]},"review_flags":[],"prep_minutes":5,"cook_minutes":90,"additional_time_text":null,"default_image":null,"slug":"crispy-pork-hock"},
{"id":7,"name":"Fried Lumpia","filipino_name":"Lumpiang Shanghai","category":"Appetizers","prep_time_text":"15 minutes","cook_time_text":"20 minutes","yield_type":"serves","yield_text":"4","ingredients":[{"source_text":"1 pound ground pork","source_pdf_page":28,"section":null,"position":1,"match_options":["ground pork"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 pound","related_recipe_id":null},{"source_text":"1 cup finely chopped yellow onion","source_pdf_page":28,"section":null,"position":2,"match_options":["yellow onion"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 cup","related_recipe_id":null},{"source_text":"1/2 cup finely chopped carrots","source_pdf_page":28,"section":null,"position":3,"match_options":["carrot"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2 cup","related_recipe_id":null},{"source_text":"1/2 cup finely chopped celery","source_pdf_page":28,"section":null,"position":4,"match_options":["celery"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2 cup","related_recipe_id":null},{"source_text":"1/2 cup finely chopped water chestnuts (optional)","source_pdf_page":28,"section":null,"position":5,"match_options":["water chestnut"],"match_rule":"single","role":"optional","required_for_matching":false,"quantity_prefix_text":"1/2 cup","related_recipe_id":null},{"source_text":"2 garlic cloves, finely chopped","source_pdf_page":28,"section":null,"position":6,"match_options":["garlic"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2","related_recipe_id":null},{"source_text":"1 teaspoon salt","source_pdf_page":28,"section":null,"position":7,"match_options":["salt"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 teaspoon","related_recipe_id":null},{"source_text":"1/4 teaspoon freshly ground black pepper","source_pdf_page":28,"section":null,"position":8,"match_options":["black pepper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/4 teaspoon","related_recipe_id":null},{"source_text":"1 large egg","source_pdf_page":28,"section":null,"position":9,"match_options":["egg"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"25 lumpia or spring roll wrappers (see tip)","source_pdf_page":28,"section":null,"position":10,"match_options":["lumpia wrapper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"25","quantity_note":"Display source_text to preserve compound quantities and/or alternative amounts; quantity_prefix_text is only the leading amount.","related_recipe_id":null},{"source_text":"Vegetable oil, for frying","source_pdf_page":28,"section":null,"position":11,"match_options":["vegetable oil"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":null,"related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"In a large mixing bowl, combine the pork, onion, carrots, celery, water chestnuts (if using), garlic, salt, and pepper. Mix well."},{"step":2,"source_step":2,"section":null,"text":"In a small bowl, beat the egg and set aside."},{"step":3,"source_step":3,"section":null,"text":"Separate the lumpia sheets and arrange them on a large, clean work surface. Cover the wrappers with a damp cloth to prevent drying as you work."},{"step":4,"source_step":4,"section":null,"text":"Place a wrapper diagonally in front of you so it looks like a diamond. Scoop a tablespoon of the pork filling on the lower corner or the wrapper, leaving about a 1 1/2-inch space on both ends, and then fold or tuck in both sides like an envelope and roll the lumpia tightly into a log."},{"step":5,"source_step":5,"section":null,"text":"Using a pastry brush, spread the egg mixture on about 1 inch of the edge of the wrapper and close to seal."},{"step":6,"source_step":6,"section":null,"text":"In a deep fryer or large frying pan, heat 3 inches of oil over medium-high heat until 350°F or until shimmering and the end of a wooden spoon dipped in the oil produces bubbles."},{"step":7,"source_step":7,"section":null,"text":"Fry the lumpia for 5 minutes until golden brown and crispy. Using tongs, remove the lumpia from the oil and transfer them to a paper-towel-lined plate."},{"step":8,"source_step":8,"section":null,"text":"Taste test and then adjust the seasoning of the filling according to your preference. Roll the remaining lumpia and fry."}],"source_tips":["INGREDIENT TIP: Look for lumpia or spring roll wrappers at Asian markets or in the Asian section of your local grocery store."],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[28,29],"printed_pages":[20,21]},"review_flags":["Instructions mention water outside the ingredient list; source list retained. Review cooking/soaking water handling in the app."],"prep_minutes":15,"cook_minutes":20,"additional_time_text":null,"default_image":null,"slug":"fried-lumpia"},
{"id":8,"name":"Fried Tofu And Pig Ears With Sweet Chile Sauce","filipino_name":"Tokwa’T Baboy","category":"Appetizers","prep_time_text":"15 minutes","cook_time_text":"1 hour 10 minutes","yield_type":"serves","yield_text":"4 to 6","ingredients":[{"source_text":"2 pounds pig ears (see tip)","source_pdf_page":30,"section":"FOR THE PIG EARS AND TOFU","position":1,"match_options":["pig ear"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 pounds","related_recipe_id":null},{"source_text":"1 yellow onion, quartered","source_pdf_page":30,"section":"FOR THE PIG EARS AND TOFU","position":2,"match_options":["yellow onion"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"2 tablespoons salt","source_pdf_page":30,"section":"FOR THE PIG EARS AND TOFU","position":3,"match_options":["salt"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 tablespoons","related_recipe_id":null},{"source_text":"6 whole black peppercorns","source_pdf_page":30,"section":"FOR THE PIG EARS AND TOFU","position":4,"match_options":["black peppercorn"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"6","related_recipe_id":null},{"source_text":"1/4 cup vegetable oil","source_pdf_page":30,"section":"FOR THE PIG EARS AND TOFU","position":5,"match_options":["vegetable oil"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/4 cup","related_recipe_id":null},{"source_text":"1 pound extra-firm tofu, cut into 1/4-inch cubes","source_pdf_page":30,"section":"FOR THE PIG EARS AND TOFU","position":6,"match_options":["tofu"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 pound","related_recipe_id":null},{"source_text":"1 cup sugar","source_pdf_page":30,"section":"FOR THE DIPPING SAUCE","position":7,"match_options":["sugar"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 cup","related_recipe_id":null},{"source_text":"1/2 cup vinegar","source_pdf_page":30,"section":"FOR THE DIPPING SAUCE","position":8,"match_options":["vinegar"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2 cup","related_recipe_id":null},{"source_text":"1/2 cup soy sauce","source_pdf_page":30,"section":"FOR THE DIPPING SAUCE","position":9,"match_options":["soy sauce"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2 cup","related_recipe_id":null},{"source_text":"3 labuyo chiles or 1 jalapeño pepper, sliced into small pieces","source_pdf_page":30,"section":"FOR THE DIPPING SAUCE","position":10,"match_options":["labuyo chili","jalapeno"],"match_rule":"any_of","role":"main","required_for_matching":true,"quantity_prefix_text":"3","quantity_note":"Display source_text to preserve compound quantities and/or alternative amounts; quantity_prefix_text is only the leading amount.","related_recipe_id":null},{"source_text":"1 tablespoon finely chopped shallots","source_pdf_page":30,"section":"FOR THE DIPPING SAUCE","position":11,"match_options":["shallot"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 tablespoon","related_recipe_id":null},{"source_text":"1 tablespoon roughly chopped garlic","source_pdf_page":30,"section":"FOR THE DIPPING SAUCE","position":12,"match_options":["garlic"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 tablespoon","related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":"TO MAKE THE PIG EARS AND TOFU","text":"In a deep pot, place the washed pig ears and cover with water by several inches. Add the onion, salt, and peppercorns and bring to a boil over high heat. Boil for 1 hour, until the meat is tender. Add extra water during cooking to keep the pig ears covered, if needed."},{"step":2,"source_step":2,"section":"TO MAKE THE PIG EARS AND TOFU","text":"Using long tongs, remove the pig ears and drain in a colander."},{"step":3,"source_step":3,"section":"TO MAKE THE PIG EARS AND TOFU","text":"When cool enough to handle, cut into medium dice and transfer to a serving bowl."},{"step":4,"source_step":4,"section":"TO MAKE THE PIG EARS AND TOFU","text":"Heat a wok or large skillet over medium-high heat. When the pan is hot, but not smoking, pour in the vegetable oil and lower the heat to medium. Fry the tofu, working in batches so the pan is not overcrowded, for about 1 minute per side, until browned."},{"step":5,"source_step":5,"section":"TO MAKE THE PIG EARS AND TOFU","text":"Remove the tofu from the pan and transfer to a paper-towel-lined plate to drain the excess oil before adding to the serving bowl with the prepared pig ears."},{"step":6,"source_step":1,"section":"TO MAKE THE DIPPING SAUCE","text":"In a small bowl, mix the sugar, vinegar, soy sauce, chiles, shallots, and garlic."},{"step":7,"source_step":2,"section":"TO MAKE THE DIPPING SAUCE","text":"Pour the sauce over the pig ears and tofu, and mix well."},{"step":8,"source_step":3,"section":"TO MAKE THE DIPPING SAUCE","text":"Serve warm or at room temperature."}],"source_tips":["INGREDIENT TIP: Look for pig ears at Asian markets or buy them direct from a butcher."],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[30,31],"printed_pages":[22,23]},"review_flags":["Multi-component recipe: preserve ingredient sections and instruction sections.","Instructions mention water outside the ingredient list; source list retained. Review cooking/soaking water handling in the app."],"prep_minutes":15,"cook_minutes":70,"additional_time_text":null,"default_image":null,"slug":"fried-tofu-and-pig-ears-with-sweet-chile-sauce"},
{"id":9,"name":"Chicken And Rice Porridge With Ginger And Saffron","filipino_name":"Arroz Caldo","category":"Rice and Noodles","prep_time_text":"15 minutes","cook_time_text":"30 minutes","yield_type":"serves","yield_text":"4 to 6","ingredients":[{"source_text":"4 tablespoons canola oil","source_pdf_page":34,"section":null,"position":1,"match_options":["canola oil"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"4 tablespoons","related_recipe_id":null},{"source_text":"1/2 onion, finely chopped","source_pdf_page":34,"section":null,"position":2,"match_options":["onion"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2","related_recipe_id":null},{"source_text":"1/2 cup finely chopped peeled ginger","source_pdf_page":34,"section":null,"position":3,"match_options":["ginger"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2 cup","related_recipe_id":null},{"source_text":"1 tablespoon crushed garlic","source_pdf_page":34,"section":null,"position":4,"match_options":["garlic"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 tablespoon","related_recipe_id":null},{"source_text":"1 pound boneless chicken thighs, cut into 1/2-inch cubes","source_pdf_page":34,"section":null,"position":5,"match_options":["chicken"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 pound","related_recipe_id":null},{"source_text":"1 cup rice (jasmine, sweet rice, or arborio)","source_pdf_page":34,"section":null,"position":6,"match_options":["rice"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 cup","related_recipe_id":null},{"source_text":"8 cups chicken stock or water","source_pdf_page":34,"section":null,"position":7,"match_options":["chicken stock","water"],"match_rule":"any_of","role":"main","required_for_matching":true,"quantity_prefix_text":"8 cups","related_recipe_id":null},{"source_text":"1/8 teaspoon saffron","source_pdf_page":34,"section":null,"position":8,"match_options":["saffron"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/8 teaspoon","related_recipe_id":null},{"source_text":"Salt","source_pdf_page":34,"section":null,"position":9,"match_options":["salt"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":null,"related_recipe_id":null},{"source_text":"Freshly ground black pepper","source_pdf_page":34,"section":null,"position":10,"match_options":["black pepper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":null,"related_recipe_id":null},{"source_text":"1/2 cup finely chopped scallions, green parts only, for garnish","source_pdf_page":34,"section":null,"position":11,"match_options":["scallion"],"match_rule":"single","role":"garnish","required_for_matching":false,"quantity_prefix_text":"1/2 cup","related_recipe_id":null},{"source_text":"4 hardboiled eggs, halved, for garnish (see tip)","source_pdf_page":34,"section":null,"position":12,"match_options":["hardboiled egg"],"match_rule":"single","role":"garnish","required_for_matching":false,"quantity_prefix_text":"4","related_recipe_id":null},{"source_text":"Calamansi wedges, for garnish","source_pdf_page":34,"section":null,"position":13,"match_options":["calamansi"],"match_rule":"single","role":"garnish","required_for_matching":false,"quantity_prefix_text":null,"related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"In a large pot, heat the oil over medium-high heat. Sauté the onion, ginger, and garlic for 2 minutes, or until they start to soften."},{"step":2,"source_step":2,"section":null,"text":"Stir in the chicken and cook until just browned, 3 to 5 minutes."},{"step":3,"source_step":3,"section":null,"text":"Add the rice and stir until well-incorporated, about 1 minute."},{"step":4,"source_step":4,"section":null,"text":"Pour in the chicken stock and let it boil, removing any froth that accumulates on top of the porridge."},{"step":5,"source_step":5,"section":null,"text":"Reduce the heat to medium-low, add the saffron, and simmer for about 20 minutes, stirring occasionally, until the rice is soft, the chicken is tender, and the rice has the consistency of porridge. Season with salt and pepper."},{"step":6,"source_step":6,"section":null,"text":"Transfer to serving bowls. Garnish with scallions, hardboiled eggs, and calamansi wedges."}],"source_tips":["SUBSTITUTION TIP: Replace the hardboiled egg with eggs poached in or stirred into the porridge. For poached eggs: After step 5, make 4 wells in the porridge and crack an egg into each well. Cover the pot, and cook until the egg whites are thoroughly cooked and the yolks reach your desired level of doneness, 5 to 8 minutes. Alternatively, at the end of step 5, you can crack all four eggs into the porridge and stir until the eggs are fully cooked, about 5 minutes."],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[34,35],"printed_pages":[26,27]},"review_flags":[],"prep_minutes":15,"cook_minutes":30,"additional_time_text":null,"default_image":null,"slug":"chicken-and-rice-porridge-with-ginger-and-saffron"},
{"id":10,"name":"Party Paella","filipino_name":null,"category":"Rice and Noodles","prep_time_text":"20 minutes","cook_time_text":"55 minutes","yield_type":"serves","yield_text":"20","ingredients":[{"source_text":"2 cups boiling water","source_pdf_page":36,"section":null,"position":1,"match_options":["water"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 cups","related_recipe_id":null},{"source_text":"2 teaspoons saffron","source_pdf_page":36,"section":null,"position":2,"match_options":["saffron"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 teaspoons","related_recipe_id":null},{"source_text":"1 chorizo sausage, cut into 1/4-inch rounds","source_pdf_page":36,"section":null,"position":3,"match_options":["chorizo"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"2 cups olive oil","source_pdf_page":36,"section":null,"position":4,"match_options":["olive oil"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 cups","related_recipe_id":null},{"source_text":"8 pieces whole chicken legs, cut into drumsticks and thighs","source_pdf_page":36,"section":null,"position":5,"match_options":["chicken"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"8 pieces","related_recipe_id":null},{"source_text":"2 onions, minced","source_pdf_page":36,"section":null,"position":6,"match_options":["onion"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2","related_recipe_id":null},{"source_text":"10 garlic cloves, minced","source_pdf_page":36,"section":null,"position":7,"match_options":["garlic"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"10","related_recipe_id":null},{"source_text":"20 tomatoes, cut into 1/4-inch cubes","source_pdf_page":36,"section":null,"position":8,"match_options":["tomato"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"20","related_recipe_id":null},{"source_text":"24 whole shrimp","source_pdf_page":36,"section":null,"position":9,"match_options":["shrimp"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"24","related_recipe_id":null},{"source_text":"1 pound clams, washed and soaked in water","source_pdf_page":36,"section":null,"position":10,"match_options":["clam"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 pound","related_recipe_id":null},{"source_text":"1 pound mussels, washed and soaked in water","source_pdf_page":36,"section":null,"position":11,"match_options":["mussel"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 pound","related_recipe_id":null},{"source_text":"1 pound squid, cut into rings","source_pdf_page":36,"section":null,"position":12,"match_options":["squid"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 pound","related_recipe_id":null},{"source_text":"4 cups jasmine or arborio rice, cooked to package directions","source_pdf_page":36,"section":null,"position":13,"match_options":["rice"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"4 cups","related_recipe_id":null},{"source_text":"2 tablespoons paprika","source_pdf_page":36,"section":null,"position":14,"match_options":["paprika"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 tablespoons","related_recipe_id":null},{"source_text":"Salt","source_pdf_page":36,"section":null,"position":15,"match_options":["salt"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":null,"related_recipe_id":null},{"source_text":"Freshly ground black pepper","source_pdf_page":36,"section":null,"position":16,"match_options":["black pepper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":null,"related_recipe_id":null},{"source_text":"4 cups frozen green peas","source_pdf_page":36,"section":null,"position":17,"match_options":["green pea"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"4 cups","related_recipe_id":null},{"source_text":"2 red bell peppers, thinly sliced","source_pdf_page":36,"section":null,"position":18,"match_options":["red bell pepper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2","related_recipe_id":null},{"source_text":"Calamansi or lemon wedges, for serving","source_pdf_page":36,"section":null,"position":19,"match_options":["calamansi","lemon"],"match_rule":"any_of","role":"serving","required_for_matching":false,"quantity_prefix_text":null,"related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"In a small bowl, pour the boiling water over the saffron. Set aside."},{"step":2,"source_step":2,"section":null,"text":"In a wok or large pot, brown the chorizo over medium-low heat, about 5 minutes. Remove the chorizo from the pan and set aside."},{"step":3,"source_step":3,"section":null,"text":"In the same wok, heat the oil over medium-high heat and fry the chicken, turning every 2 minutes until golden brown, about 12 minutes. Remove the chicken from the wok and transfer to a paper-towel-lined plate."},{"step":4,"source_step":4,"section":null,"text":"In the same wok, sauté the onion and garlic for 3 to 5 minutes, or until translucent and fragrant. Add the tomatoes and sauté for 3 minutes, or until just soft."},{"step":5,"source_step":5,"section":null,"text":"Add the shrimp, clams, mussels, and squid and cook until the mussels and clams open and the shrimp turns pink, about 5 to 10 minutes. Discard any shellfish that have not opened after 10 minutes of cooking time."},{"step":6,"source_step":6,"section":null,"text":"Stir in the cooked rice, paprika, and the saffron water. Continue to stir until the saffron water is fully incorporated into the rice, 10 to 15 minutes. Season with salt and pepper."},{"step":7,"source_step":7,"section":null,"text":"Add the chorizo and chicken and stir to distribute evenly throughout the rice. Stir in the peas and peppers and cook for 3 minutes."},{"step":8,"source_step":8,"section":null,"text":"Serve on a platter, and garnish with the calamansi wedges."}],"source_tips":[],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[36,37],"printed_pages":[28,29]},"review_flags":[],"prep_minutes":20,"cook_minutes":55,"additional_time_text":null,"default_image":null,"slug":"party-paella"},
{"id":11,"name":"Garlic Fried Rice","filipino_name":"Sinangag","category":"Rice and Noodles","prep_time_text":"5 minutes","cook_time_text":"15 minutes","yield_type":"serves","yield_text":"4 to 6","ingredients":[{"source_text":"3 tablespoons vegetable oil","source_pdf_page":38,"section":null,"position":1,"match_options":["vegetable oil"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3 tablespoons","related_recipe_id":null},{"source_text":"2 tablespoons finely chopped garlic","source_pdf_page":38,"section":null,"position":2,"match_options":["garlic"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 tablespoons","related_recipe_id":null},{"source_text":"5 cups cooked, cold long-grain rice","source_pdf_page":38,"section":null,"position":3,"match_options":["cooked rice"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"5 cups","related_recipe_id":null},{"source_text":"1 teaspoon salt","source_pdf_page":38,"section":null,"position":4,"match_options":["salt"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 teaspoon","related_recipe_id":null},{"source_text":"3 tablespoons water","source_pdf_page":38,"section":null,"position":5,"match_options":["water"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3 tablespoons","related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"In a large skillet, heat the oil over medium heat until hot, about 2 minutes."},{"step":2,"source_step":2,"section":null,"text":"Add the garlic and cook for about 1 minute, stirring constantly, until fragrant. Be careful not to burn the garlic, which will give it an acrid flavor."},{"step":3,"source_step":3,"section":null,"text":"Add the rice and salt and continue to cook, stirring constantly. Sprinkle the water over the rice and stir to help soften the rice. Continue to cook for about 10 minutes, until the rice is softened, then serve."}],"source_tips":["SUBSTITUTION TIP: You can substitute butter for the vegetable oil for richer flavor."],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[38],"printed_pages":[30]},"review_flags":[],"prep_minutes":5,"cook_minutes":15,"additional_time_text":null,"default_image":null,"slug":"garlic-fried-rice"},
{"id":12,"name":"Manila-Style Chicken Noodle Soup","filipino_name":"Pancit Mami","category":"Rice and Noodles","prep_time_text":"15 minutes","cook_time_text":"10 minutes","yield_type":"serves","yield_text":"4 to 6","ingredients":[{"source_text":"1/4 cup coarsely chopped garlic","source_pdf_page":39,"section":null,"position":1,"match_options":["garlic"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/4 cup","related_recipe_id":null},{"source_text":"1 pound fresh egg noodles (see tip)","source_pdf_page":39,"section":null,"position":2,"match_options":["egg noodle"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 pound","related_recipe_id":null},{"source_text":"1 tablespoon salt","source_pdf_page":39,"section":null,"position":3,"match_options":["salt"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 tablespoon","related_recipe_id":null},{"source_text":"1 pound cooked chicken breast, shredded","source_pdf_page":39,"section":null,"position":4,"match_options":["cooked chicken"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 pound","related_recipe_id":null},{"source_text":"1 medium carrot, peeled and julienned","source_pdf_page":39,"section":null,"position":5,"match_options":["carrot"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"1/2 napa cabbage, shredded","source_pdf_page":39,"section":null,"position":6,"match_options":["napa cabbage"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2","related_recipe_id":null},{"source_text":"4 hardboiled eggs, quartered","source_pdf_page":39,"section":null,"position":7,"match_options":["hardboiled egg"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"4","related_recipe_id":null},{"source_text":"1/2 cup finely chopped scallions, green parts only","source_pdf_page":39,"section":null,"position":8,"match_options":["scallion"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2 cup","related_recipe_id":null},{"source_text":"6 cups chicken broth","source_pdf_page":39,"section":null,"position":9,"match_options":["chicken stock"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"6 cups","related_recipe_id":null},{"source_text":"Freshly ground black pepper","source_pdf_page":39,"section":null,"position":10,"match_options":["black pepper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":null,"related_recipe_id":null},{"source_text":"3 calamansi or lemons, halved","source_pdf_page":39,"section":null,"position":11,"match_options":["calamansi","lemon"],"match_rule":"any_of","role":"main","required_for_matching":true,"quantity_prefix_text":"3","related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"In a medium-size dry skillet, toast the garlic over medium-low heat, stirring constantly, for 2 to 3 minutes, or until lightly browned."},{"step":2,"source_step":2,"section":null,"text":"Fill a medium pot with water and bring the water to a boil over medium-high heat. Add the egg noodles and salt and cook for about 3 minutes, or until tender. Drain and divide into serving bowls."},{"step":3,"source_step":3,"section":null,"text":"Divide the chicken, carrot, cabbage, eggs, scallions, and toasted garlic on top of the cooked noodles."},{"step":4,"source_step":4,"section":null,"text":"In the same pot, bring the chicken broth to a boil over medium-high heat. Season with salt and pepper. Taste and adjust the seasoning as desired."},{"step":5,"source_step":5,"section":null,"text":"Spoon the broth over the bowls and serve immediately with calamansi halves on the side."}],"source_tips":["SUBSTITUTION TIP: Look for fresh egg noodles at an Asian market. There are generally several thicknesses, ranging from very thin wonton noodles to the thicker lo mein noodles. Any variety will work in this recipe."],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[39],"printed_pages":[31]},"review_flags":["Instructions mention water outside the ingredient list; source list retained. Review cooking/soaking water handling in the app."],"prep_minutes":15,"cook_minutes":10,"additional_time_text":null,"default_image":null,"slug":"manila-style-chicken-noodle-soup"},
{"id":13,"name":"Chicken And Rice Noodles With Snow Peas","filipino_name":"Pancit Guisado","category":"Rice and Noodles","prep_time_text":"10 minutes","cook_time_text":"20 minutes","yield_type":"serves","yield_text":"4 to 6","ingredients":[{"source_text":"8 ounces rice noodles (see tip)","source_pdf_page":40,"section":null,"position":1,"match_options":["rice noodle"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"8 ounces","related_recipe_id":null},{"source_text":"3 tablespoons canola oil","source_pdf_page":40,"section":null,"position":2,"match_options":["canola oil"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3 tablespoons","related_recipe_id":null},{"source_text":"1/4 cup thinly sliced onion","source_pdf_page":40,"section":null,"position":3,"match_options":["onion"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/4 cup","related_recipe_id":null},{"source_text":"1 1/2 teaspoons crushed or minced garlic","source_pdf_page":40,"section":null,"position":4,"match_options":["garlic"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 1/2 teaspoons","quantity_note":"Display source_text to preserve compound quantities and/or alternative amounts; quantity_prefix_text is only the leading amount.","related_recipe_id":null},{"source_text":"1 cup boneless chicken thighs, cut into 1-inch cubes","source_pdf_page":40,"section":null,"position":5,"match_options":["chicken"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 cup","related_recipe_id":null},{"source_text":"1 cup carrots, sliced on the bias","source_pdf_page":40,"section":null,"position":6,"match_options":["carrot"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 cup","related_recipe_id":null},{"source_text":"1 cup celery, sliced on the bias","source_pdf_page":40,"section":null,"position":7,"match_options":["celery"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 cup","related_recipe_id":null},{"source_text":"1 cup chicken stock","source_pdf_page":40,"section":null,"position":8,"match_options":["chicken stock"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 cup","related_recipe_id":null},{"source_text":"1/4 cup soy sauce","source_pdf_page":40,"section":null,"position":9,"match_options":["soy sauce"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/4 cup","related_recipe_id":null},{"source_text":"1 tablespoon oyster sauce","source_pdf_page":40,"section":null,"position":10,"match_options":["oyster sauce"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 tablespoon","related_recipe_id":null},{"source_text":"1/4 teaspoon freshly ground black pepper","source_pdf_page":40,"section":null,"position":11,"match_options":["black pepper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/4 teaspoon","related_recipe_id":null},{"source_text":"1 cup snow peas or cut green beans","source_pdf_page":40,"section":null,"position":12,"match_options":["snow pea","green bean"],"match_rule":"any_of","role":"main","required_for_matching":true,"quantity_prefix_text":"1 cup","related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"Add the rice noodles to a bowl of warm water and let soak while you prepare the rest of the ingredients, for at least 15 minutes."},{"step":2,"source_step":2,"section":null,"text":"In a wok or large sauté pan, heat the oil over medium-high heat. Add the onion and garlic and sauté for about 3 minutes, or until softened."},{"step":3,"source_step":3,"section":null,"text":"Add the chicken and stir for 5 minutes, or until the chicken is no longer pink. Add the carrots and cook for 3 minutes. Then add the celery and cook for 1 minute."},{"step":4,"source_step":4,"section":null,"text":"Add the chicken stock and continue to cook for about 5 minutes, or until the vegetables are tender. Add the soy sauce, oyster sauce, and pepper and stir to combine."},{"step":5,"source_step":5,"section":null,"text":"Drain the noodles and add them to the pan. Stir until the noodles absorb the liquid, adding a little more stock or water, if needed."},{"step":6,"source_step":6,"section":null,"text":"Add the snow peas and stir about a minute more, or until the peas are heated through. Remove from the heat and serve."}],"source_tips":["SUBSTITUTION TIP: If rice noodles are unavailable, Canton noodles can be used in their place and require no presoaking before adding to the wok in step 6."],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[40,41],"printed_pages":[32,33]},"review_flags":["Instructions mention water outside the ingredient list; source list retained. Review cooking/soaking water handling in the app."],"prep_minutes":10,"cook_minutes":20,"additional_time_text":null,"default_image":null,"slug":"chicken-and-rice-noodles-with-snow-peas"},
{"id":14,"name":"Chinese-Style Shrimp And Pork Noodles","filipino_name":"Pancit Canton","category":"Rice and Noodles","prep_time_text":"15 minutes","cook_time_text":"25 minutes","yield_type":"serves","yield_text":"6","ingredients":[{"source_text":"5 tablespoons canola oil","source_pdf_page":42,"section":null,"position":1,"match_options":["canola oil"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"5 tablespoons","related_recipe_id":null},{"source_text":"1/4 cup sliced onion","source_pdf_page":42,"section":null,"position":2,"match_options":["onion"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/4 cup","related_recipe_id":null},{"source_text":"1 tablespoon minced garlic","source_pdf_page":42,"section":null,"position":3,"match_options":["garlic"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 tablespoon","related_recipe_id":null},{"source_text":"1/2 cup thinly sliced pork strips","source_pdf_page":42,"section":null,"position":4,"match_options":["pork"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2 cup","related_recipe_id":null},{"source_text":"2 cups carrots, thinly sliced on the bias","source_pdf_page":42,"section":null,"position":5,"match_options":["carrot"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 cups","related_recipe_id":null},{"source_text":"2 1/2 cups chicken stock","source_pdf_page":42,"section":null,"position":6,"match_options":["chicken stock"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 1/2 cups","related_recipe_id":null},{"source_text":"10 shrimp, peeled and deveined","source_pdf_page":42,"section":null,"position":7,"match_options":["shrimp"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"10","related_recipe_id":null},{"source_text":"1/2 cup soy sauce","source_pdf_page":42,"section":null,"position":8,"match_options":["soy sauce"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2 cup","related_recipe_id":null},{"source_text":"1/2 cup oyster sauce","source_pdf_page":42,"section":null,"position":9,"match_options":["oyster sauce"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2 cup","related_recipe_id":null},{"source_text":"1 pound dry Canton noodles","source_pdf_page":42,"section":null,"position":10,"match_options":["canton noodle"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 pound","related_recipe_id":null},{"source_text":"3 cups shredded cabbage","source_pdf_page":42,"section":null,"position":11,"match_options":["cabbage"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3 cups","related_recipe_id":null},{"source_text":"1 cup snow peas","source_pdf_page":42,"section":null,"position":12,"match_options":["snow pea"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 cup","related_recipe_id":null},{"source_text":"Pinch freshly ground black pepper","source_pdf_page":42,"section":null,"position":13,"match_options":["black pepper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"Pinch","related_recipe_id":null},{"source_text":"5 calamansi, halved, or lemon wedges","source_pdf_page":42,"section":null,"position":14,"match_options":["calamansi","lemon"],"match_rule":"any_of","role":"main","required_for_matching":true,"quantity_prefix_text":"5","related_recipe_id":null},{"source_text":"3 scallions, both white and green parts, finely chopped, for garnish","source_pdf_page":42,"section":null,"position":15,"match_options":["scallion"],"match_rule":"single","role":"garnish","required_for_matching":false,"quantity_prefix_text":"3","related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"In a wok or large sauté pan, heat the oil over medium-high heat. Cook the onions, stirring regularly, for 3 to 5 minutes, or until translucent. Add the garlic and continue to stir until fragrant, about 30 seconds."},{"step":2,"source_step":2,"section":null,"text":"Add the pork and continue to cook for 5 to 8 minutes, or until the meat is no longer pink."},{"step":3,"source_step":3,"section":null,"text":"Add the carrots and chicken stock and cook for about 2 minutes."},{"step":4,"source_step":4,"section":null,"text":"Stir in the shrimp, soy sauce, and oyster sauce and cook for 2 to 3 minutes, until shrimp are pink and nearly cooked through."},{"step":5,"source_step":5,"section":null,"text":"Add the noodles to the wok and stir. Add the cabbage and gently mix together with the noodles and meat for 3 to 4 minutes, or until the noodles begin to soften."},{"step":6,"source_step":6,"section":null,"text":"Add the snow peas. Turn off the heat and stir. Season with pepper. Taste, then adjust the seasoning if needed."},{"step":7,"source_step":7,"section":null,"text":"Transfer onto a platter and garnish with calamansi halves or lemon wedges and scallions."}],"source_tips":["SUBSTITUTION TIP: This recipe can be made vegetarian by omitting the shrimp, pork, chicken stock, and oyster sauce and adding 3 more tablespoons of soy sauce instead. Replace the chicken stock with water and add 1 cup of sliced mushrooms for more flavor."],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[42,43],"printed_pages":[34,35]},"review_flags":[],"prep_minutes":15,"cook_minutes":25,"additional_time_text":null,"default_image":null,"slug":"chinese-style-shrimp-and-pork-noodles"},
{"id":15,"name":"Silky Thread Noodle Soup","filipino_name":"Misua Soup","category":"Rice and Noodles","prep_time_text":"10 minutes","cook_time_text":"15 minutes","yield_type":"serves","yield_text":"4 to 6","ingredients":[{"source_text":"3 tablespoons canola oil","source_pdf_page":44,"section":null,"position":1,"match_options":["canola oil"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3 tablespoons","related_recipe_id":null},{"source_text":"1/2 onion, thinly sliced","source_pdf_page":44,"section":null,"position":2,"match_options":["onion"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2","related_recipe_id":null},{"source_text":"3 garlic cloves, minced","source_pdf_page":44,"section":null,"position":3,"match_options":["garlic"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3","related_recipe_id":null},{"source_text":"8 ounces ground beef","source_pdf_page":44,"section":null,"position":4,"match_options":["ground beef"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"8 ounces","related_recipe_id":null},{"source_text":"4 cups water","source_pdf_page":44,"section":null,"position":5,"match_options":["water"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"4 cups","related_recipe_id":null},{"source_text":"1 sponge gourd or zucchini, cut into 1/4-inch slices (see tip)","source_pdf_page":44,"section":null,"position":6,"match_options":["sponge gourd","zucchini"],"match_rule":"any_of","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"4 large eggs","source_pdf_page":44,"section":null,"position":7,"match_options":["egg"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"4","related_recipe_id":null},{"source_text":"4 ounces misua noodles or wheat thread noodles","source_pdf_page":44,"section":null,"position":8,"match_options":["misua noodle"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"4 ounces","related_recipe_id":null},{"source_text":"Salt","source_pdf_page":44,"section":null,"position":9,"match_options":["salt"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":null,"related_recipe_id":null},{"source_text":"Freshly ground black pepper","source_pdf_page":44,"section":null,"position":10,"match_options":["black pepper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":null,"related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"In a wok or deep saucepan, heat the oil over medium-high heat. Add the onion and cook for 3 to 5 minutes, or until translucent. Add the garlic and cook for about 30 seconds, or until fragrant."},{"step":2,"source_step":2,"section":null,"text":"Stir in the ground beef and cook for about 8 minutes, until medium brown."},{"step":3,"source_step":3,"section":null,"text":"Add the water and bring to a boil. Add the sponge gourd and cook for about 3 minutes, or until soft."},{"step":4,"source_step":4,"section":null,"text":"Into a small bowl, crack one egg and add it to the soup. Repeat for all of the eggs. Let the eggs set for about 30 seconds, then stir until mixed well."},{"step":5,"source_step":5,"section":null,"text":"Break the misua noodles into three pieces, stir them into the soup, and cook for 2 minutes, or until tender. Season with salt and pepper."}],"source_tips":["INGREDIENT TIP: In its young state, at 4 to 5 inches long, sponge gourd is eaten in India, China, Vietnam, and the Philippines. Once matured, the vegetable becomes extremely fibrous and inedible; if left to dry it becomes a loofah, which is used as a scrubbing sponge. Look for it at Asian markets."],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[44],"printed_pages":[36]},"review_flags":[],"prep_minutes":10,"cook_minutes":15,"additional_time_text":null,"default_image":null,"slug":"silky-thread-noodle-soup"},
{"id":16,"name":"Noodles With Shrimp, Smoked Mackerel, And Crackling Pork","filipino_name":"Pancit Palabok","category":"Rice and Noodles","prep_time_text":"15 minutes","cook_time_text":"15 minutes","yield_type":"serves","yield_text":"2 to 4","ingredients":[{"source_text":"8 ounces thin cornstarch noodles, soaked in water for 15 minutes (see tip)","source_pdf_page":45,"section":null,"position":1,"match_options":["cornstarch noodle"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"8 ounces","related_recipe_id":null},{"source_text":"10 shrimp, peeled and deveined","source_pdf_page":45,"section":null,"position":2,"match_options":["shrimp"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"10","related_recipe_id":null},{"source_text":"4 cups chicken stock","source_pdf_page":45,"section":null,"position":3,"match_options":["chicken stock"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"4 cups","related_recipe_id":null},{"source_text":"3 tablespoons cornstarch or flour, dissolved in 1/3 cup water","source_pdf_page":45,"section":null,"position":4,"match_options":["cornstarch","flour"],"match_rule":"any_of","role":"main","required_for_matching":true,"quantity_prefix_text":"3 tablespoons","related_recipe_id":null},{"source_text":"1 tablespoon annatto powder, dissolved in 3 tablespoons hot water","source_pdf_page":45,"section":null,"position":5,"match_options":["annatto powder"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 tablespoon","related_recipe_id":null},{"source_text":"Salt","source_pdf_page":45,"section":null,"position":6,"match_options":["salt"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":null,"related_recipe_id":null},{"source_text":"2 hardboiled eggs, quartered","source_pdf_page":45,"section":null,"position":7,"match_options":["hardboiled egg"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2","related_recipe_id":null},{"source_text":"1/2 cup crushed Crackling Pork (page 12)","source_pdf_page":45,"section":null,"position":8,"match_options":["crackling pork"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2 cup","related_recipe_id":3},{"source_text":"1/4 cup flaked smoked mackerel or herring","source_pdf_page":45,"section":null,"position":9,"match_options":["smoked mackerel","smoked herring"],"match_rule":"any_of","role":"main","required_for_matching":true,"quantity_prefix_text":"1/4 cup","quantity_note":"Display source_text to preserve compound quantities and/or alternative amounts; quantity_prefix_text is only the leading amount.","related_recipe_id":null},{"source_text":"1/4 cup finely chopped scallions","source_pdf_page":45,"section":null,"position":10,"match_options":["scallion"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/4 cup","related_recipe_id":null},{"source_text":"2 calamansi or lemons, halved","source_pdf_page":45,"section":null,"position":11,"match_options":["calamansi","lemon"],"match_rule":"any_of","role":"main","required_for_matching":true,"quantity_prefix_text":"2","related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"Fill a medium pot halfway with water and bring the water to a boil. Parboil the noodles for 2 minutes, drain, and set aside."},{"step":2,"source_step":2,"section":null,"text":"Fill a medium saucepan halfway with water and bring to a boil. Add the shrimp and cook for 5 minutes, or until opaque and cooked through. Drain and set aside."},{"step":3,"source_step":3,"section":null,"text":"In the same saucepan set over medium-high heat, combine the chicken stock, cornstarch, and annatto. Stirring constantly, bring the sauce to a boil and continue cooking until thickened. Season with salt."},{"step":4,"source_step":4,"section":null,"text":"On a platter, arrange the noodles and ladle the sauce over the top."},{"step":5,"source_step":5,"section":null,"text":"Garnish with the shrimp, eggs, crackling pork, smoked mackerel, and scallions. Serve with the calamansi or lemon halves."}],"source_tips":["INGREDIENT TIP: Cornstarch noodles, also known as pancit luglug, are Filipino noodles made from cornstarch, rice flour, and water. Find them at Asian grocery stores or online. Rice noodles can also be used for this recipe."],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[45],"printed_pages":[37]},"review_flags":["Instructions mention water outside the ingredient list; source list retained. Review cooking/soaking water handling in the app."],"prep_minutes":15,"cook_minutes":15,"additional_time_text":null,"default_image":null,"slug":"noodles-with-shrimp-smoked-mackerel-and-crackling-pork"},
{"id":17,"name":"Mixed Noodles With Chicken And Vegetables","filipino_name":"Pancit Bihon And Canton","category":"Rice and Noodles","prep_time_text":"15 minutes","cook_time_text":"30 minutes","yield_type":"serves","yield_text":"4 to 6","ingredients":[{"source_text":"1/4 cup canola oil","source_pdf_page":46,"section":null,"position":1,"match_options":["canola oil"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/4 cup","related_recipe_id":null},{"source_text":"1/2 cup thinly sliced onion","source_pdf_page":46,"section":null,"position":2,"match_options":["onion"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2 cup","related_recipe_id":null},{"source_text":"3 garlic cloves, minced","source_pdf_page":46,"section":null,"position":3,"match_options":["garlic"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3","related_recipe_id":null},{"source_text":"2 cups diced chicken","source_pdf_page":46,"section":null,"position":4,"match_options":["chicken"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 cups","related_recipe_id":null},{"source_text":"8 cups chicken stock or water, divided","source_pdf_page":46,"section":null,"position":5,"match_options":["chicken stock","water"],"match_rule":"any_of","role":"main","required_for_matching":true,"quantity_prefix_text":"8 cups","related_recipe_id":null},{"source_text":"2 cups thinly sliced carrots","source_pdf_page":46,"section":null,"position":6,"match_options":["carrot"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 cups","related_recipe_id":null},{"source_text":"1 cup snow peas or green beans, ends removed","source_pdf_page":46,"section":null,"position":7,"match_options":["snow pea","green bean"],"match_rule":"any_of","role":"main","required_for_matching":true,"quantity_prefix_text":"1 cup","related_recipe_id":null},{"source_text":"1/2 cup soy sauce","source_pdf_page":46,"section":null,"position":8,"match_options":["soy sauce"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2 cup","related_recipe_id":null},{"source_text":"8 ounces dry Canton noodles","source_pdf_page":46,"section":null,"position":9,"match_options":["canton noodle"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"8 ounces","related_recipe_id":null},{"source_text":"8 ounces thin rice noodles, soaked in warm water for 15 minutes and drained","source_pdf_page":46,"section":null,"position":10,"match_options":["rice noodle"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"8 ounces","related_recipe_id":null},{"source_text":"2 cups thinly sliced celery","source_pdf_page":46,"section":null,"position":11,"match_options":["celery"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 cups","related_recipe_id":null},{"source_text":"1/2 green or napa cabbage, shredded","source_pdf_page":46,"section":null,"position":12,"match_options":["cabbage","napa cabbage"],"match_rule":"any_of","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2","quantity_note":"Display source_text to preserve compound quantities and/or alternative amounts; quantity_prefix_text is only the leading amount.","related_recipe_id":null},{"source_text":"1 teaspoon freshly ground black pepper","source_pdf_page":46,"section":null,"position":13,"match_options":["black pepper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 teaspoon","related_recipe_id":null},{"source_text":"6 calamansi or lemons, halved","source_pdf_page":46,"section":null,"position":14,"match_options":["calamansi","lemon"],"match_rule":"any_of","role":"main","required_for_matching":true,"quantity_prefix_text":"6","related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"In a wok or large sauté pan, heat the oil over medium-high heat. Add the onion and sauté for 3 to 5 minutes, or until translucent. Add the garlic and continue to sauté until fragrant, about 30 seconds more."},{"step":2,"source_step":2,"section":null,"text":"Add the chicken and stir. Add 1 cup of chicken stock or water and simmer the chicken until cooked through, about 5 minutes. Stir in the carrots and cook for 1 minute. Add the snow peas and cook for 1 minute."},{"step":3,"source_step":3,"section":null,"text":"Add 4 cups of chicken stock or water and the soy sauce and cook for about 2 minutes, or until the liquid is simmering. Add the Canton noodles and toss gently to soften."},{"step":4,"source_step":4,"section":null,"text":"After about 5 minutes, add 1 cup of chicken stock or water and stir gently as the noodles absorb the liquid. Repeat with an additional cup of liquid."},{"step":5,"source_step":5,"section":null,"text":"Add the final cup of liquid and the rice noodles and continue to stir. The dry noodles will absorb all of the liquid as they cook. (You don’t want this dish to be soupy because the noodles will get soggy)."},{"step":6,"source_step":6,"section":null,"text":"Once the noodles are softened, add the celery, cabbage, and pepper. Taste and adjust the seasoning as desired. Serve garnished with calamansi."}],"source_tips":["VARIATION TIP: This dish can also be served with more sauce by adding 2 tablespoons of a cornstarch-and-water slurry before the noodles absorb all the liquid in step 6. Continue tossing the noodles and allow the sauce to thicken toward the end of cooking when the cabbage is added."],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[46,47],"printed_pages":[38,39]},"review_flags":[],"prep_minutes":15,"cook_minutes":30,"additional_time_text":null,"default_image":null,"slug":"mixed-noodles-with-chicken-and-vegetables"},
{"id":18,"name":"Sweet Spaghetti","filipino_name":null,"category":"Rice and Noodles","prep_time_text":"10 minutes","cook_time_text":"40 minutes","yield_type":"serves","yield_text":"4 to 6","ingredients":[{"source_text":"1 pound spaghetti noodles","source_pdf_page":48,"section":null,"position":1,"match_options":["spaghetti"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 pound","related_recipe_id":null},{"source_text":"2 tablespoons salt plus pinch salt, divided","source_pdf_page":48,"section":null,"position":2,"match_options":["salt"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 tablespoons","quantity_note":"Display source_text to preserve compound quantities and/or alternative amounts; quantity_prefix_text is only the leading amount.","related_recipe_id":null},{"source_text":"3 tablespoons vegetable oil or olive oil","source_pdf_page":48,"section":null,"position":3,"match_options":["vegetable oil","olive oil"],"match_rule":"any_of","role":"main","required_for_matching":true,"quantity_prefix_text":"3 tablespoons","related_recipe_id":null},{"source_text":"1 tablespoon finely chopped onion","source_pdf_page":48,"section":null,"position":4,"match_options":["onion"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 tablespoon","related_recipe_id":null},{"source_text":"1 tablespoon crushed garlic","source_pdf_page":48,"section":null,"position":5,"match_options":["garlic"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 tablespoon","related_recipe_id":null},{"source_text":"1 pound 80 percent lean ground beef","source_pdf_page":48,"section":null,"position":6,"match_options":["ground beef"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 pound","related_recipe_id":null},{"source_text":"3 hot dogs, cut diagonally","source_pdf_page":48,"section":null,"position":7,"match_options":["hot dog"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3","related_recipe_id":null},{"source_text":"2 bay leaves","source_pdf_page":48,"section":null,"position":8,"match_options":["bay leaf"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2","related_recipe_id":null},{"source_text":"3 cups tomato sauce","source_pdf_page":48,"section":null,"position":9,"match_options":["tomato sauce"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3 cups","related_recipe_id":null},{"source_text":"2 cups Banana Ketchup (page 153)","source_pdf_page":48,"section":null,"position":10,"match_options":["banana ketchup"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 cups","related_recipe_id":98},{"source_text":"1 cup sugar","source_pdf_page":48,"section":null,"position":11,"match_options":["sugar"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 cup","related_recipe_id":null},{"source_text":"Freshly ground black pepper","source_pdf_page":48,"section":null,"position":12,"match_options":["black pepper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":null,"related_recipe_id":null},{"source_text":"1/2 cup shredded cheddar cheese, for topping","source_pdf_page":48,"section":null,"position":13,"match_options":["cheddar cheese"],"match_rule":"single","role":"garnish","required_for_matching":false,"quantity_prefix_text":"1/2 cup","related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"Bring a large pot of water to a boil over high heat. Add the spaghetti noodles and salt and cook the noodles until al dente, 10 to 12 minutes. Reserve 2 cups of cooking liquid and set aside. Drain the noodles."},{"step":2,"source_step":2,"section":null,"text":"In a large saucepan, heat the vegetable oil over medium-high heat. Add the onions and cook for about 3 minutes, or until softened. Add the garlic and cook for about 30 seconds, or until fragrant."},{"step":3,"source_step":3,"section":null,"text":"Crumble in the ground beef and cook, stirring regularly, until the meat is tender and lightly browned, about 10 minutes."},{"step":4,"source_step":4,"section":null,"text":"Add the hot dogs and bay leaves and cook for about 3 minutes."},{"step":5,"source_step":5,"section":null,"text":"Pour in the tomato sauce, banana ketchup, sugar, and reserved cooking liquid and simmer for 15 minutes. Remove the bay leaves."},{"step":6,"source_step":6,"section":null,"text":"Using a large spoon, skim the layer of fat on top of the tomato sauce. Season with salt and pepper."},{"step":7,"source_step":7,"section":null,"text":"Arrange the noodles in a big bowl or platter and pour the spaghetti sauce over the noodles. Top with cheddar cheese and serve."}],"source_tips":["SUBSTITUTION TIP: Tomato ketchup may be used instead of banana ketchup."],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[48,49],"printed_pages":[40,41]},"review_flags":["Instructions mention water outside the ingredient list; source list retained. Review cooking/soaking water handling in the app."],"prep_minutes":10,"cook_minutes":40,"additional_time_text":null,"default_image":null,"slug":"sweet-spaghetti"},
{"id":19,"name":"Malabon-Style Noodles","filipino_name":"Pancit Malabon","category":"Rice and Noodles","prep_time_text":"15 minutes","cook_time_text":"35 minutes","yield_type":"serves","yield_text":"4 to 6","ingredients":[{"source_text":"8 cups chicken stock or water","source_pdf_page":50,"section":null,"position":1,"match_options":["chicken stock","water"],"match_rule":"any_of","role":"main","required_for_matching":true,"quantity_prefix_text":"8 cups","related_recipe_id":null},{"source_text":"8 ounces thick cornstarch noodles","source_pdf_page":50,"section":null,"position":2,"match_options":["cornstarch noodle"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"8 ounces","related_recipe_id":null},{"source_text":"1/4 cup vegetable oil","source_pdf_page":50,"section":null,"position":3,"match_options":["vegetable oil"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/4 cup","related_recipe_id":null},{"source_text":"2 tablespoons minced garlic","source_pdf_page":50,"section":null,"position":4,"match_options":["garlic"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 tablespoons","related_recipe_id":null},{"source_text":"10 mussels, washed and soaked in water","source_pdf_page":50,"section":null,"position":5,"match_options":["mussel"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"10","related_recipe_id":null},{"source_text":"10 shrimp, peeled and deveined","source_pdf_page":50,"section":null,"position":6,"match_options":["shrimp"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"10","related_recipe_id":null},{"source_text":"1/2 cup squid, sliced 1/4-inch thick","source_pdf_page":50,"section":null,"position":7,"match_options":["squid"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2 cup","related_recipe_id":null},{"source_text":"2 tablespoons annatto powder, dissolved in 1/4 cup water","source_pdf_page":50,"section":null,"position":8,"match_options":["annatto powder"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 tablespoons","related_recipe_id":null},{"source_text":"Salt","source_pdf_page":50,"section":null,"position":9,"match_options":["salt"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":null,"related_recipe_id":null},{"source_text":"1/4 cup finely chopped scallions, both white and green parts, for garnish","source_pdf_page":50,"section":null,"position":10,"match_options":["scallion"],"match_rule":"single","role":"garnish","required_for_matching":false,"quantity_prefix_text":"1/4 cup","related_recipe_id":null},{"source_text":"2 hardboiled eggs, quartered","source_pdf_page":50,"section":null,"position":11,"match_options":["hardboiled egg"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2","related_recipe_id":null},{"source_text":"2 calamansi or lemons, halved","source_pdf_page":50,"section":null,"position":12,"match_options":["calamansi","lemon"],"match_rule":"any_of","role":"main","required_for_matching":true,"quantity_prefix_text":"2","related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"In a large pot, bring the chicken stock to a boil over high heat. Add the noodles and cook for 30 minutes, or until al dente. Drain."},{"step":2,"source_step":2,"section":null,"text":"Meanwhile, in a wok or large sauté pan, heat the oil over medium-high heat and sauté the garlic. Add the mussels and toss for about 2 minutes. Add the shrimp and squid and cook for 2 to 3 minutes, or until the shrimp turns pink. Remove the seafood from the wok and set aside."},{"step":3,"source_step":3,"section":null,"text":"Adjust the heat to low and pour the annatto in the wok. Add the cooked noodles and toss to coat with the sauce."},{"step":4,"source_step":4,"section":null,"text":"Return the mussels, shrimp, and squid to the pan and season with salt. Turn off the heat and transfer the noodles to a serving dish."},{"step":5,"source_step":5,"section":null,"text":"Garnish with scallions, eggs, and calamansi before serving."}],"source_tips":["SUBSTITUTION TIP: Sometimes I use ground beef and Crackling Pork (page 12) in place of the seafood for a different flavor profile."],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[50],"printed_pages":[42]},"review_flags":[],"prep_minutes":15,"cook_minutes":35,"additional_time_text":null,"default_image":null,"slug":"malabon-style-noodles"},
{"id":20,"name":"Eggplant Omelet","filipino_name":"Torta Talong","category":"Vegetables","prep_time_text":"5 minutes","cook_time_text":"25 minutes","yield_type":"serves","yield_text":"2","ingredients":[{"source_text":"2 Filipino eggplant (see tip)","source_pdf_page":54,"section":null,"position":1,"match_options":["eggplant"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2","related_recipe_id":null},{"source_text":"4 large eggs","source_pdf_page":54,"section":null,"position":2,"match_options":["egg"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"4","related_recipe_id":null},{"source_text":"2 tablespoons water","source_pdf_page":54,"section":null,"position":3,"match_options":["water"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 tablespoons","related_recipe_id":null},{"source_text":"Salt","source_pdf_page":54,"section":null,"position":4,"match_options":["salt"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":null,"related_recipe_id":null},{"source_text":"Freshly ground black pepper","source_pdf_page":54,"section":null,"position":5,"match_options":["black pepper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":null,"related_recipe_id":null},{"source_text":"1/2 cup canola oil","source_pdf_page":54,"section":null,"position":6,"match_options":["canola oil"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2 cup","related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"Preheat the broiler on high. Poke holes around the outside of the eggplant to avoid them bursting in the oven."},{"step":2,"source_step":2,"section":null,"text":"Place the eggplant on a baking sheet. Broil the eggplant until the skin is charred, about 10 minutes, flipping a couple times. Transfer to a plate and let cool before peeling off the skin."},{"step":3,"source_step":3,"section":null,"text":"In a medium bowl, crack the eggs and add the water, salt, and pepper and whisk well."},{"step":4,"source_step":4,"section":null,"text":"Using a fork, spread and flatten the eggplant and dip it in the beaten egg."},{"step":5,"source_step":5,"section":null,"text":"In a large pan, heat the oil over medium-high heat. Lay the eggplant in the pan and fry for 3 minutes on each side, until brown."},{"step":6,"source_step":6,"section":null,"text":"Transfer the eggplant to a paper-towel-lined plate to remove excess oil. Repeat steps 4 through 6 with the second eggplant."}],"source_tips":["INGREDIENT TIP: Filipino eggplant are long and slender with violet skin and creamy white flesh. Look for them at Asian specialty markets, or substitute other thin, small eggplant varieties like Japanese or Chinese eggplant."],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[54],"printed_pages":[46]},"review_flags":[],"prep_minutes":5,"cook_minutes":25,"additional_time_text":null,"default_image":null,"slug":"eggplant-omelet"},
{"id":21,"name":"Spicy Taro Leaves In Coconut Milk","filipino_name":"Laing","category":"Vegetables","prep_time_text":"15 minutes","cook_time_text":"35 minutes","yield_type":"serves","yield_text":"4 to 6","ingredients":[{"source_text":"8 cups water","source_pdf_page":55,"section":null,"position":1,"match_options":["water"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"8 cups","related_recipe_id":null},{"source_text":"8 ounces dried taro leaves or 1 pound spinach","source_pdf_page":55,"section":null,"position":2,"match_options":["taro leaf","spinach"],"match_rule":"any_of","role":"main","required_for_matching":true,"quantity_prefix_text":"8 ounces","quantity_note":"Display source_text to preserve compound quantities and/or alternative amounts; quantity_prefix_text is only the leading amount.","related_recipe_id":null},{"source_text":"8 ounces pork belly, cut into strips","source_pdf_page":55,"section":null,"position":3,"match_options":["pork"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"8 ounces","related_recipe_id":null},{"source_text":"1/2 cup peeled minced fresh ginger","source_pdf_page":55,"section":null,"position":4,"match_options":["ginger"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2 cup","related_recipe_id":null},{"source_text":"1/2 onion, minced","source_pdf_page":55,"section":null,"position":5,"match_options":["onion"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2","related_recipe_id":null},{"source_text":"3 tablespoons shrimp paste","source_pdf_page":55,"section":null,"position":6,"match_options":["shrimp paste"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3 tablespoons","related_recipe_id":null},{"source_text":"5 garlic cloves, minced","source_pdf_page":55,"section":null,"position":7,"match_options":["garlic"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"5","related_recipe_id":null},{"source_text":"6 cups coconut milk","source_pdf_page":55,"section":null,"position":8,"match_options":["coconut milk"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"6 cups","related_recipe_id":null},{"source_text":"8 whole labuyo chiles or Thai chiles","source_pdf_page":55,"section":null,"position":9,"match_options":["labuyo chili","thai chili"],"match_rule":"any_of","role":"main","required_for_matching":true,"quantity_prefix_text":"8","related_recipe_id":null},{"source_text":"Salt","source_pdf_page":55,"section":null,"position":10,"match_options":["salt"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":null,"related_recipe_id":null},{"source_text":"Freshly ground black pepper","source_pdf_page":55,"section":null,"position":11,"match_options":["black pepper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":null,"related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"In a large pot, combine the water, taro leaves, pork belly, ginger, onion, shrimp paste, and garlic."},{"step":2,"source_step":2,"section":null,"text":"Heat over medium-high heat and bring to a boil. Reduce the heat to medium-low and simmer for 25 minutes. Some taro leaves will be floating, but just push them down with the back of a spoon and stir a couple of times to prevent the leaves from sticking to the bottom of the pot."},{"step":3,"source_step":3,"section":null,"text":"Add the coconut milk and chiles and let simmer for 20 minutes, until reduced to a consistency close to that of a spinach dip. Season with salt and pepper."},{"step":4,"source_step":4,"section":null,"text":"Spoon onto a platter and serve."}],"source_tips":["SUBSTITUTION TIP: I also like adding shrimp to laing. When I do this, I substitute the shrimp paste with fish sauce or salt.","VARIATION TIP: To make the dish lighter, use 3 cups of coconut milk and 3 cups of water when using dried taro leaves."],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[55],"printed_pages":[47]},"review_flags":[],"prep_minutes":15,"cook_minutes":35,"additional_time_text":null,"default_image":null,"slug":"spicy-taro-leaves-in-coconut-milk"},
{"id":22,"name":"Sauteed Mung Beans With Pork And Shrimp","filipino_name":"Ginisang Munggo","category":"Vegetables","prep_time_text":"15 minutes","cook_time_text":"55 minutes","yield_type":"serves","yield_text":"4 to 6","ingredients":[{"source_text":"2 cups green mung beans","source_pdf_page":56,"section":null,"position":1,"match_options":["mung bean"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 cups","related_recipe_id":null},{"source_text":"3 tablespoons canola oil or vegetable oil","source_pdf_page":56,"section":null,"position":2,"match_options":["canola oil","vegetable oil"],"match_rule":"any_of","role":"main","required_for_matching":true,"quantity_prefix_text":"3 tablespoons","related_recipe_id":null},{"source_text":"1 onion, cut into 1/4-inch slices","source_pdf_page":56,"section":null,"position":3,"match_options":["onion"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"1 tomato, cored and cut into 1/4-inch slices","source_pdf_page":56,"section":null,"position":4,"match_options":["tomato"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"3 garlic cloves, coarsely chopped","source_pdf_page":56,"section":null,"position":5,"match_options":["garlic"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3","related_recipe_id":null},{"source_text":"8 ounces pork belly, cut into 1/4-inch-thick strips","source_pdf_page":56,"section":null,"position":6,"match_options":["pork"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"8 ounces","related_recipe_id":null},{"source_text":"8 ounces whole medium shrimp","source_pdf_page":56,"section":null,"position":7,"match_options":["shrimp"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"8 ounces","related_recipe_id":null},{"source_text":"2 cups spinach, stems removed","source_pdf_page":56,"section":null,"position":8,"match_options":["spinach"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 cups","related_recipe_id":null},{"source_text":"2 cups Crackling Pork (page 12)","source_pdf_page":56,"section":null,"position":9,"match_options":["crackling pork"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 cups","related_recipe_id":3},{"source_text":"Salt","source_pdf_page":56,"section":null,"position":10,"match_options":["salt"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":null,"related_recipe_id":null},{"source_text":"Freshly ground black pepper","source_pdf_page":56,"section":null,"position":11,"match_options":["black pepper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":null,"related_recipe_id":null},{"source_text":"Fish sauce, for serving","source_pdf_page":56,"section":null,"position":12,"match_options":["fish sauce"],"match_rule":"single","role":"serving","required_for_matching":false,"quantity_prefix_text":null,"related_recipe_id":null},{"source_text":"Calamansi halves or lemon wedges, for serving","source_pdf_page":56,"section":null,"position":13,"match_options":["calamansi","lemon"],"match_rule":"any_of","role":"serving","required_for_matching":false,"quantity_prefix_text":null,"related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"In a deep pot, place the mung beans and cover with water by several inches. Bring to a boil over high heat for about 35 minutes, or until soft. Skim the skins and foam off the top as the beans cook. Drain."},{"step":2,"source_step":2,"section":null,"text":"In a separate large pot, heat the canola oil over medium-high heat. Sauté the onion for 3 to 5 minutes, or until translucent, then add the tomato and garlic and continue to sauté until softened."},{"step":3,"source_step":3,"section":null,"text":"Add the pork belly and sauté for about 5 minutes, or until lightly browned."},{"step":4,"source_step":4,"section":null,"text":"Add the shrimp and the cooked beans. Simmer to cook the shrimp and thicken the sauce to the consistency of a light stew, 4 to 5 minutes."},{"step":5,"source_step":5,"section":null,"text":"Add the spinach and crackling pork and mix well. Season with salt and pepper."},{"step":6,"source_step":6,"section":null,"text":"Serve hot in a bowl with fish sauce and halved calamansi or lemon wedges on the side."}],"source_tips":["INGREDIENT TIP: If you don’t want to make crackling pork from scratch, buy it from the store, but be sure to buy an unflavored option.","SUBSTITUTION TIP: If you can find it, use moringa leaves (malunggay) in place of the spinach."],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[56,57],"printed_pages":[48,49]},"review_flags":["Instructions mention water outside the ingredient list; source list retained. Review cooking/soaking water handling in the app."],"prep_minutes":15,"cook_minutes":55,"additional_time_text":null,"default_image":null,"slug":"sauteed-mung-beans-with-pork-and-shrimp"},
{"id":23,"name":"Sauteed Snow Peas With Pork And Shrimp","filipino_name":"Gisadong Sitsaro","category":"Vegetables","prep_time_text":"15 minutes","cook_time_text":"20 minutes","yield_type":"serves","yield_text":"4","ingredients":[{"source_text":"3 tablespoons canola oil","source_pdf_page":58,"section":null,"position":1,"match_options":["canola oil"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3 tablespoons","related_recipe_id":null},{"source_text":"1 tomato, cut into 1/4-inch slices","source_pdf_page":58,"section":null,"position":2,"match_options":["tomato"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"1/2 onion, thinly sliced","source_pdf_page":58,"section":null,"position":3,"match_options":["onion"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2","related_recipe_id":null},{"source_text":"3 garlic cloves, coarsely chopped","source_pdf_page":58,"section":null,"position":4,"match_options":["garlic"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3","related_recipe_id":null},{"source_text":"8 ounces pork belly, cut into 1/4-inch slices","source_pdf_page":58,"section":null,"position":5,"match_options":["pork"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"8 ounces","related_recipe_id":null},{"source_text":"2 cups water","source_pdf_page":58,"section":null,"position":6,"match_options":["water"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 cups","related_recipe_id":null},{"source_text":"1 tablespoon salt","source_pdf_page":58,"section":null,"position":7,"match_options":["salt"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 tablespoon","related_recipe_id":null},{"source_text":"8 ounces shrimp, peeled and deveined","source_pdf_page":58,"section":null,"position":8,"match_options":["shrimp"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"8 ounces","related_recipe_id":null},{"source_text":"1 pound snow peas","source_pdf_page":58,"section":null,"position":9,"match_options":["snow pea"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 pound","related_recipe_id":null},{"source_text":"Pinch freshly ground black pepper","source_pdf_page":58,"section":null,"position":10,"match_options":["black pepper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"Pinch","related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"In a wok or large sauté pan, heat the oil over medium-high heat. Add the tomato, onion, and garlic and sauté for about 3 minutes, or until the onion is translucent."},{"step":2,"source_step":2,"section":null,"text":"Add the pork and stir. Add the water and salt, stir, and bring to a boil. Cook for about 10 minutes, or until the pork belly is fork-tender."},{"step":3,"source_step":3,"section":null,"text":"Add the shrimp, stirring constantly, for 3 to 6 minutes, until the shrimp turns pink."},{"step":4,"source_step":4,"section":null,"text":"Add the snow peas and stir for about 2 minutes. Season with pepper."}],"source_tips":["SUBSTITUTION TIP: Use ground or thinly sliced strips of beef or pork in place of the pork belly."],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[58],"printed_pages":[50]},"review_flags":[],"prep_minutes":15,"cook_minutes":20,"additional_time_text":null,"default_image":null,"slug":"sauteed-snow-peas-with-pork-and-shrimp"},
{"id":24,"name":"Kabocha And Long Beans In Coconut Milk","filipino_name":"Kalabasa-Sitaw","category":"Vegetables","prep_time_text":"15 minutes","cook_time_text":"20 minutes","yield_type":"serves","yield_text":"4 to 6","ingredients":[{"source_text":"3 tablespoons canola oil","source_pdf_page":59,"section":null,"position":1,"match_options":["canola oil"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3 tablespoons","related_recipe_id":null},{"source_text":"1/2 onion, thinly sliced","source_pdf_page":59,"section":null,"position":2,"match_options":["onion"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2","related_recipe_id":null},{"source_text":"3 garlic cloves, coarsely chopped","source_pdf_page":59,"section":null,"position":3,"match_options":["garlic"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3","related_recipe_id":null},{"source_text":"1 pound kabocha, cut into 1-inch cubes (see Prep Tip)","source_pdf_page":59,"section":null,"position":4,"match_options":["kabocha squash"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 pound","related_recipe_id":null},{"source_text":"4 cups coconut milk","source_pdf_page":59,"section":null,"position":5,"match_options":["coconut milk"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"4 cups","related_recipe_id":null},{"source_text":"1 pound long beans or green beans, cut into 3-inch pieces","source_pdf_page":59,"section":null,"position":6,"match_options":["long bean","green bean"],"match_rule":"any_of","role":"main","required_for_matching":true,"quantity_prefix_text":"1 pound","related_recipe_id":null},{"source_text":"1 tablespoon salt","source_pdf_page":59,"section":null,"position":7,"match_options":["salt"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 tablespoon","related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"In a large sauté pan or skillet, heat the oil over medium-high heat. Sauté the onion and garlic for 3 to 5 minutes, or until translucent and fragrant."},{"step":2,"source_step":2,"section":null,"text":"Add the kabocha and coconut milk and boil for 10 minutes, or until a fork easily pierces through the kabocha."},{"step":3,"source_step":3,"section":null,"text":"Stir in the long beans and salt and continue stirring until the beans are bright green, crisp, and tender, about 3 minutes."}],"source_tips":["PREP TIP: Kabocha is a bright-orange-fleshed Japanese squash with edible skin. Cutting it can be difficult, as it is rather hard. Be sure to use a sharp knife and start by cutting it in half to remove the seeds. Cut the seeded halves into strips, then cut each strip into cubes. This recipe will use about half of a medium kabocha. Store any remaining kabocha, covered in plastic wrap or in an airtight container for 2 to 3 days, or chop it and freeze it for up to a month.","VARIATION TIP: For a lighter coconut taste, use 2 cups of water and 2 cups of coconut milk instead of 4 cups of coconut milk."],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[59],"printed_pages":[51]},"review_flags":[],"prep_minutes":15,"cook_minutes":20,"additional_time_text":null,"default_image":null,"slug":"kabocha-and-long-beans-in-coconut-milk"},
{"id":25,"name":"Sauteed Bitter Melon","filipino_name":"Ginisang Ampalaya","category":"Vegetables","prep_time_text":"15 minutes","cook_time_text":"15 minutes","yield_type":"serves","yield_text":"4","ingredients":[{"source_text":"2 bitter melons (see tip)","source_pdf_page":60,"section":null,"position":1,"match_options":["bitter melon"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2","related_recipe_id":null},{"source_text":"5 tablespoons canola oil or vegetable oil","source_pdf_page":60,"section":null,"position":2,"match_options":["canola oil","vegetable oil"],"match_rule":"any_of","role":"main","required_for_matching":true,"quantity_prefix_text":"5 tablespoons","related_recipe_id":null},{"source_text":"1/2 onion, finely chopped","source_pdf_page":60,"section":null,"position":3,"match_options":["onion"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2","related_recipe_id":null},{"source_text":"2 garlic cloves, minced","source_pdf_page":60,"section":null,"position":4,"match_options":["garlic"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2","related_recipe_id":null},{"source_text":"1 tomato, finely chopped","source_pdf_page":60,"section":null,"position":5,"match_options":["tomato"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"4 large eggs, beaten","source_pdf_page":60,"section":null,"position":6,"match_options":["egg"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"4","related_recipe_id":null},{"source_text":"Salt","source_pdf_page":60,"section":null,"position":7,"match_options":["salt"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":null,"related_recipe_id":null},{"source_text":"Freshly ground black pepper","source_pdf_page":60,"section":null,"position":8,"match_options":["black pepper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":null,"related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"Cut the melons in half lengthwise and remove the seeds. Then cut into 1/4-inch slices. Set aside."},{"step":2,"source_step":2,"section":null,"text":"In a large skillet, heat the oil over medium-high heat. Sauté the onion for 3 to 5 minutes, until translucent. Add the garlic and sauté until fragrant, about 30 seconds."},{"step":3,"source_step":3,"section":null,"text":"Add the tomato and sauté for about 2 minutes, or until softened. Add the bitter melon and sauté until tender and crisp, about 3 minutes."},{"step":4,"source_step":4,"section":null,"text":"Pour in the eggs and toss to combine with the bitter melon until the eggs are set, soft, and fluffy, 2 to 3 minutes. Season with salt and pepper."},{"step":5,"source_step":5,"section":null,"text":"Serve hot on a platter."}],"source_tips":["PREP TIP: When I prepare bitter melon, I wash it, rub it with rock salt, and let it sit for a few minutes to have the salt work its magic by reducing a bit of its bitterness. Here in the United States, I have noticed the bitter melon is not as bitter as those in Asia, so I sometimes skip this process."],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[60],"printed_pages":[52]},"review_flags":[],"prep_minutes":15,"cook_minutes":15,"additional_time_text":null,"default_image":null,"slug":"sauteed-bitter-melon"},
{"id":26,"name":"Shrimp Paste Vegetable Medley","filipino_name":"Pinakbet","category":"Vegetables","prep_time_text":"15 minutes","cook_time_text":"30 minutes","yield_type":"serves","yield_text":"4 to 6","ingredients":[{"source_text":"8 ounces pork belly, cut into 1/4-inch strips","source_pdf_page":61,"section":null,"position":1,"match_options":["pork"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"8 ounces","related_recipe_id":null},{"source_text":"1 tomato, finely chopped","source_pdf_page":61,"section":null,"position":2,"match_options":["tomato"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"1/2 onion, finely chopped","source_pdf_page":61,"section":null,"position":3,"match_options":["onion"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2","related_recipe_id":null},{"source_text":"3 garlic cloves, coarsely chopped","source_pdf_page":61,"section":null,"position":4,"match_options":["garlic"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3","related_recipe_id":null},{"source_text":"1 heaping tablespoon shrimp paste","source_pdf_page":61,"section":null,"position":5,"match_options":["shrimp paste"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 heaping tablespoon","related_recipe_id":null},{"source_text":"1/2 kabocha, cut into 1-inch cubes","source_pdf_page":61,"section":null,"position":6,"match_options":["kabocha squash"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2","related_recipe_id":null},{"source_text":"3 cups water","source_pdf_page":61,"section":null,"position":7,"match_options":["water"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3 cups","related_recipe_id":null},{"source_text":"1 Filipino or Japanese or Chinese eggplant, cut into 1/2-inch slices","source_pdf_page":61,"section":null,"position":8,"match_options":["eggplant"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"1 bitter melon, seeded and cut into 1/4-inch-thick slices","source_pdf_page":61,"section":null,"position":9,"match_options":["bitter melon"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"1 cup okra pods","source_pdf_page":61,"section":null,"position":10,"match_options":["okra"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 cup","related_recipe_id":null},{"source_text":"1 cup long beans or green beans, cut into 3-inch pieces","source_pdf_page":61,"section":null,"position":11,"match_options":["long bean","green bean"],"match_rule":"any_of","role":"main","required_for_matching":true,"quantity_prefix_text":"1 cup","related_recipe_id":null},{"source_text":"Freshly ground black pepper","source_pdf_page":61,"section":null,"position":12,"match_options":["black pepper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":null,"related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"In a wok or large sauté pan, fry the pork belly over medium heat for about 5 minutes, until browned."},{"step":2,"source_step":2,"section":null,"text":"Add the tomato, onion, and garlic and sauté for 3 to 5 minutes, until softened. Stir in the shrimp paste and cook for 2 minutes while stirring to incorporate."},{"step":3,"source_step":3,"section":null,"text":"Add the kabocha and sauté for about 2 minutes before adding the water to the wok. Adjust the heat to high and bring to a boil for 10 minutes, until you can easily pierce the kabocha with a fork."},{"step":4,"source_step":4,"section":null,"text":"Add the eggplant, stir to incorporate, and cook for 2 minutes, until fork-tender. Add the bitter melon, okra, and beans. Cook for about 5 minutes, until the okra, beans, and bitter melon are bright green and crisp."},{"step":5,"source_step":5,"section":null,"text":"Add more liquid if the mixture is dry. Season with black pepper, taste, and adjust the seasoning as desired."}],"source_tips":["SUBSTITUTION TIP: Make this recipe vegan by omitting the pork and sautéing the vegetables in 1 tablespoon of olive oil or vegetable oil, then using fermented soybeans or salted black beans instead of shrimp paste."],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[61],"printed_pages":[53]},"review_flags":[],"prep_minutes":15,"cook_minutes":30,"additional_time_text":null,"default_image":null,"slug":"shrimp-paste-vegetable-medley"},
{"id":27,"name":"Fresh Lumpia","filipino_name":"Lumpia Sariwa","category":"Vegetables","prep_time_text":"30 minutes","cook_time_text":"20 minutes","yield_type":"makes","yield_text":"10 lumpia","ingredients":[{"source_text":"3 tablespoons vegetable oil","source_pdf_page":62,"section":"FOR THE VEGETABLES","position":1,"match_options":["vegetable oil"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3 tablespoons","related_recipe_id":null},{"source_text":"1/2 onion, finely sliced","source_pdf_page":62,"section":"FOR THE VEGETABLES","position":2,"match_options":["onion"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2","related_recipe_id":null},{"source_text":"3 garlic cloves, crushed","source_pdf_page":62,"section":"FOR THE VEGETABLES","position":3,"match_options":["garlic"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3","related_recipe_id":null},{"source_text":"1 carrot, julienned","source_pdf_page":62,"section":"FOR THE VEGETABLES","position":4,"match_options":["carrot"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"1/2 sweet potato, julienned","source_pdf_page":62,"section":"FOR THE VEGETABLES","position":5,"match_options":["sweet potato"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2","related_recipe_id":null},{"source_text":"2 cups green beans, thinly sliced","source_pdf_page":62,"section":"FOR THE VEGETABLES","position":6,"match_options":["green bean"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 cups","related_recipe_id":null},{"source_text":"1 cup cooked chickpeas","source_pdf_page":62,"section":"FOR THE VEGETABLES","position":7,"match_options":["chickpea"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 cup","related_recipe_id":null},{"source_text":"1 green cabbage, thinly shredded","source_pdf_page":62,"section":"FOR THE VEGETABLES","position":8,"match_options":["cabbage"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"1 tablespoon sugar","source_pdf_page":62,"section":"FOR THE VEGETABLES","position":9,"match_options":["sugar"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 tablespoon","related_recipe_id":null},{"source_text":"2 pinches salt","source_pdf_page":62,"section":"FOR THE VEGETABLES","position":10,"match_options":["salt"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 pinches","related_recipe_id":null},{"source_text":"Pinch freshly ground black pepper","source_pdf_page":62,"section":"FOR THE VEGETABLES","position":11,"match_options":["black pepper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"Pinch","related_recipe_id":null},{"source_text":"10 lumpia wrappers","source_pdf_page":63,"section":"FOR THE LUMPIA ROLLS","position":12,"match_options":["lumpia wrapper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"10","related_recipe_id":null},{"source_text":"5 leafy green lettuce leaves, cut in half lengthwise","source_pdf_page":63,"section":"FOR THE LUMPIA ROLLS","position":13,"match_options":["lettuce"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"5","related_recipe_id":null},{"source_text":"3 tablespoons peanut butter","source_pdf_page":63,"section":"FOR THE LUMPIA ROLLS","position":14,"match_options":["peanut butter"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3 tablespoons","related_recipe_id":null},{"source_text":"Fresh Lumpia Sauce (page 149)","source_pdf_page":63,"section":"FOR THE LUMPIA ROLLS","position":15,"match_options":["fresh lumpia sauce"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":null,"related_recipe_id":94},{"source_text":"1 cup ground peanuts","source_pdf_page":63,"section":"FOR THE LUMPIA ROLLS","position":16,"match_options":["peanut"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 cup","related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":"TO MAKE THE VEGETABLES","text":"In a wok or large sauté pan, heat the oil over medium-high heat. Add the onion and garlic and sauté for about 3 to 5 minutes, or until softened."},{"step":2,"source_step":2,"section":"TO MAKE THE VEGETABLES","text":"Add the carrot and stir-fry for about 3 minutes. Add the sweet potato and stir-fry for about 3 minutes."},{"step":3,"source_step":3,"section":"TO MAKE THE VEGETABLES","text":"Add the green beans and stir-fry for about 3 minutes. Add the chickpeas and stir-fry for about 3 minutes."},{"step":4,"source_step":4,"section":"TO MAKE THE VEGETABLES","text":"Add the shredded cabbage and stir-fry for about 3 minutes, until everything is crisp and tender. Taste test the vegetables. Season with sugar, salt, and pepper."},{"step":5,"source_step":5,"section":"TO MAKE THE VEGETABLES","text":"Remove the pan from the heat as soon as the vegetables are cooked, making sure not to overcook them. Transfer to a colander to drain and set aside to cool."},{"step":6,"source_step":1,"section":"TO MAKE THE LUMPIA ROLLS","text":"Separate the lumpia sheets and arrange them on a large, clean work surface. Cover the wrappers with a damp cloth to prevent drying as you work."},{"step":7,"source_step":2,"section":"TO MAKE THE LUMPIA ROLLS","text":"Place a wrapper diagonally in front of you, so it looks like a diamond. Place a lettuce leaf in the center of each wrap. Spread 1 to 2 teaspoons of peanut butter on the lettuce, then place about 2 tablespoons of the vegetables on the lettuce."},{"step":8,"source_step":3,"section":"TO MAKE THE LUMPIA ROLLS","text":"Tuck in the sides of the wrapper and roll it up like a burrito. Arrange on a platter and continue until all wrappers and vegetables are used."},{"step":9,"source_step":4,"section":"TO MAKE THE LUMPIA ROLLS","text":"Pour the fresh lumpia sauce on top of the lumpia and garnish with ground peanuts."}],"source_tips":[],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[62,63],"printed_pages":[54,55]},"review_flags":["Multi-component recipe: preserve ingredient sections and instruction sections."],"prep_minutes":30,"cook_minutes":20,"additional_time_text":null,"default_image":null,"slug":"fresh-lumpia"},
{"id":28,"name":"Easy Fried Chicken","filipino_name":null,"category":"Chicken","prep_time_text":"10 minutes, plus 20 minutes to marinate","cook_time_text":"30 minutes","yield_type":"serves","yield_text":"4","ingredients":[{"source_text":"1/2 cup freshly squeezed calamansi juice (see tip)","source_pdf_page":66,"section":null,"position":1,"match_options":["calamansi"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2 cup","related_recipe_id":null},{"source_text":"1/2 cup soy sauce","source_pdf_page":66,"section":null,"position":2,"match_options":["soy sauce"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2 cup","related_recipe_id":null},{"source_text":"1 tablespoon chopped garlic","source_pdf_page":66,"section":null,"position":3,"match_options":["garlic"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 tablespoon","related_recipe_id":null},{"source_text":"4 whole chicken legs, cut into drumsticks and thighs","source_pdf_page":66,"section":null,"position":4,"match_options":["chicken"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"4","related_recipe_id":null},{"source_text":"1 teaspoon salt","source_pdf_page":66,"section":null,"position":5,"match_options":["salt"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 teaspoon","related_recipe_id":null},{"source_text":"Pinch freshly ground black pepper","source_pdf_page":66,"section":null,"position":6,"match_options":["black pepper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"Pinch","related_recipe_id":null},{"source_text":"2 cups canola oil, for frying","source_pdf_page":66,"section":null,"position":7,"match_options":["canola oil"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 cups","related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"In a small bowl, mix the calamansi juice, soy sauce, and garlic."},{"step":2,"source_step":2,"section":null,"text":"In a nonreactive baking pan, season the chicken with salt and pepper, then pour the marinade over the meat. Cover with plastic wrap and marinate for 20 minutes."},{"step":3,"source_step":3,"section":null,"text":"In a large sauté pan or skillet, heat the oil over medium heat, until it shimmers or the end of a wooden spoon dipped into it produces bubbles."},{"step":4,"source_step":4,"section":null,"text":"Working in batches, arrange the chicken in the pan, skin-side down, and fry. Spoon the hot oil over the chicken as it is frying to help with even cooking."},{"step":5,"source_step":5,"section":null,"text":"When the skin is golden brown, flip the chicken and continue to cook for a total of 12 to 15 minutes, until the juices run clear or a thermometer inserted into the thickest part of the meat reads 165°F."},{"step":6,"source_step":6,"section":null,"text":"Using tongs, remove the chicken from the pan and transfer to a cooling rack. Season with a little salt before serving."}],"source_tips":["SUBSTITUTION TIP: If calamansi is unavailable, lemon juice or vinegar can be used in its place."],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[66],"printed_pages":[58]},"review_flags":["Additional waiting time is retained as text; do not display prep + cook as total elapsed time."],"prep_minutes":10,"cook_minutes":30,"additional_time_text":"20 minutes to marinate","default_image":null,"slug":"easy-fried-chicken"},
{"id":29,"name":"Chicken Tinola","filipino_name":"Tinolang Manok","category":"Chicken","prep_time_text":"15 minutes","cook_time_text":"45 minutes","yield_type":"serves","yield_text":"4 to 6","ingredients":[{"source_text":"3 tablespoons canola oil","source_pdf_page":67,"section":null,"position":1,"match_options":["canola oil"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3 tablespoons","related_recipe_id":null},{"source_text":"1 onion, quartered","source_pdf_page":67,"section":null,"position":2,"match_options":["onion"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"1 cup peeled and thinly sliced fresh ginger","source_pdf_page":67,"section":null,"position":3,"match_options":["ginger"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 cup","related_recipe_id":null},{"source_text":"3 garlic cloves, coarsely chopped","source_pdf_page":67,"section":null,"position":4,"match_options":["garlic"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3","related_recipe_id":null},{"source_text":"1 whole chicken, cut into 12 serving pieces","source_pdf_page":67,"section":null,"position":5,"match_options":["chicken"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"1/2 green papaya, peeled and cut into 4 slices and then cut diagonally into 1/2-inch-thick wedges","source_pdf_page":67,"section":null,"position":6,"match_options":["green papaya"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2","related_recipe_id":null},{"source_text":"Salt","source_pdf_page":67,"section":null,"position":7,"match_options":["salt"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":null,"related_recipe_id":null},{"source_text":"Freshly ground black pepper","source_pdf_page":67,"section":null,"position":8,"match_options":["black pepper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":null,"related_recipe_id":null},{"source_text":"1 cup spinach","source_pdf_page":67,"section":null,"position":9,"match_options":["spinach"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 cup","related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"In a wok or large pot, heat the oil over medium-high heat. Sauté the onion, ginger, and garlic for about 3 minutes, until softened."},{"step":2,"source_step":2,"section":null,"text":"Add the chicken and continue to sauté for about 5 minutes, until it is lightly browned."},{"step":3,"source_step":3,"section":null,"text":"Cover with water and cook for about 25 minutes, until the chicken is tender and cooked through."},{"step":4,"source_step":4,"section":null,"text":"Add the papaya and cook for about 8 minutes, until soft but not mushy. Season with salt and pepper. Stir in the spinach just before serving."}],"source_tips":["SUBSTITUTION TIP: While spinach is used in this recipe, traditionally chile pepper leaves would be used instead. If you can find them in an Asian specialty store, use them; otherwise, substitute moringa (malunggay), bok choy, or spinach. You can also substitute chayote or bottle gourd (upo) for the green papaya."],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[67],"printed_pages":[59]},"review_flags":["Instructions mention water outside the ingredient list; source list retained. Review cooking/soaking water handling in the app."],"prep_minutes":15,"cook_minutes":45,"additional_time_text":null,"default_image":null,"slug":"chicken-tinola"},
{"id":30,"name":"Simple Ginger And Chicken Soup","filipino_name":"Pesang Chicken","category":"Chicken","prep_time_text":"15 minutes","cook_time_text":"35 minutes","yield_type":"serves","yield_text":"4 to 6","ingredients":[{"source_text":"1 whole chicken or 4 leg quarters, cut into serving-size pieces","source_pdf_page":68,"section":null,"position":1,"match_options":["chicken"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","quantity_note":"Display source_text to preserve compound quantities and/or alternative amounts; quantity_prefix_text is only the leading amount.","related_recipe_id":null},{"source_text":"1 cup peeled 1/2-inch slices ginger","source_pdf_page":68,"section":null,"position":2,"match_options":["ginger"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 cup","related_recipe_id":null},{"source_text":"1 onion, quartered","source_pdf_page":68,"section":null,"position":3,"match_options":["onion"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"1/2 teaspoon whole black peppercorns","source_pdf_page":68,"section":null,"position":4,"match_options":["black peppercorn"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2 teaspoon","related_recipe_id":null},{"source_text":"Salt","source_pdf_page":68,"section":null,"position":5,"match_options":["salt"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":null,"related_recipe_id":null},{"source_text":"4 medium potatoes, quartered","source_pdf_page":68,"section":null,"position":6,"match_options":["potato"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"4","related_recipe_id":null},{"source_text":"1/2 green or napa cabbage, quartered","source_pdf_page":68,"section":null,"position":7,"match_options":["cabbage","napa cabbage"],"match_rule":"any_of","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2","quantity_note":"Display source_text to preserve compound quantities and/or alternative amounts; quantity_prefix_text is only the leading amount.","related_recipe_id":null},{"source_text":"4 baby bok choy, halved lengthwise","source_pdf_page":68,"section":null,"position":8,"match_options":["bok choy"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"4","related_recipe_id":null},{"source_text":"Salt","source_pdf_page":68,"section":null,"position":9,"match_options":["salt"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":null,"related_recipe_id":null},{"source_text":"Freshly ground black pepper","source_pdf_page":68,"section":null,"position":10,"match_options":["black pepper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":null,"related_recipe_id":null},{"source_text":"1/2 cup finely chopped scallions, both white and green parts","source_pdf_page":68,"section":null,"position":11,"match_options":["scallion"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2 cup","related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"Place the chicken in a large deep pot and cover with cold water. Add the ginger, onion, peppercorns, and salt. Bring to a boil, skimming the foam off the surface as it cooks. Cook for about 15 minutes, or until the vegetables are tender."},{"step":2,"source_step":2,"section":null,"text":"Add the potatoes and cook until they are fork-tender, about 5 minutes."},{"step":3,"source_step":3,"section":null,"text":"Add the cabbage and bok choy and cook for 3 minutes. Season with salt and pepper to taste."},{"step":4,"source_step":4,"section":null,"text":"Top with the scallions, and serve family style in a large bowl."}],"source_tips":["INGREDIENT TIP: Ginger is good for the digestive system and is meant to be eaten; however, it can be omitted if you don’t like or want to eat the ginger."],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[68],"printed_pages":[60]},"review_flags":["Instructions mention water outside the ingredient list; source list retained. Review cooking/soaking water handling in the app."],"prep_minutes":15,"cook_minutes":35,"additional_time_text":null,"default_image":null,"slug":"simple-ginger-and-chicken-soup"},
{"id":31,"name":"Coconut, Chicken, And Papaya Soup","filipino_name":"Binakol Na Manok","category":"Chicken","prep_time_text":"15 minutes","cook_time_text":"1 hour","yield_type":"serves","yield_text":"4 to 6","ingredients":[{"source_text":"3 tablespoons canola oil","source_pdf_page":69,"section":null,"position":1,"match_options":["canola oil"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3 tablespoons","related_recipe_id":null},{"source_text":"1 shallot, thinly sliced","source_pdf_page":69,"section":null,"position":2,"match_options":["shallot"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"1/4 cup peeled and thinly sliced ginger","source_pdf_page":69,"section":null,"position":3,"match_options":["ginger"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/4 cup","related_recipe_id":null},{"source_text":"3 garlic cloves, crushed","source_pdf_page":69,"section":null,"position":4,"match_options":["garlic"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3","related_recipe_id":null},{"source_text":"4 pounds whole chicken legs, cut into drumsticks and thighs","source_pdf_page":69,"section":null,"position":5,"match_options":["chicken"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"4 pounds","related_recipe_id":null},{"source_text":"4 cups coconut water","source_pdf_page":69,"section":null,"position":6,"match_options":["coconut water"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"4 cups","related_recipe_id":null},{"source_text":"1 green papaya, peeled, seeded, and cut into 2-inch cubes","source_pdf_page":69,"section":null,"position":7,"match_options":["green papaya"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"2 cups coconut meat, cut into 2-inch cubes","source_pdf_page":69,"section":null,"position":8,"match_options":["coconut meat"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 cups","related_recipe_id":null},{"source_text":"Salt","source_pdf_page":69,"section":null,"position":9,"match_options":["salt"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":null,"related_recipe_id":null},{"source_text":"Freshly ground black pepper","source_pdf_page":69,"section":null,"position":10,"match_options":["black pepper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":null,"related_recipe_id":null},{"source_text":"2 cups spinach, trimmed of coarse stems","source_pdf_page":69,"section":null,"position":11,"match_options":["spinach"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 cups","related_recipe_id":null},{"source_text":"Fish sauce, for serving (optional)","source_pdf_page":69,"section":null,"position":12,"match_options":["fish sauce"],"match_rule":"single","role":"optional","required_for_matching":false,"quantity_prefix_text":null,"related_recipe_id":null},{"source_text":"Calamansi or lemon slices, for serving (optional)","source_pdf_page":69,"section":null,"position":13,"match_options":["calamansi","lemon"],"match_rule":"any_of","role":"optional","required_for_matching":false,"quantity_prefix_text":null,"related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"In a large pot, heat the oil over medium-high heat. Sauté the shallot for 3 to 5 minutes, or until translucent. Add the ginger and garlic and stir until fragrant, about 30 seconds."},{"step":2,"source_step":2,"section":null,"text":"Add the chicken and sauté for 5 to 6 minutes, until browned."},{"step":3,"source_step":3,"section":null,"text":"Pour in the coconut water and cover. Bring to a boil, then reduce the heat to medium-low and simmer for 25 minutes, or until the chicken is tender."},{"step":4,"source_step":4,"section":null,"text":"Add the green papaya and cook until fork-tender, about 5 minutes. Add the coconut meat and cook 5 minutes, or until fork-tender."},{"step":5,"source_step":5,"section":null,"text":"Season with salt and pepper. Stir in the spinach and cook until just wilted. Serve with fish sauce or calamansi or lemon slices, if using."}],"source_tips":[],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[69],"printed_pages":[61]},"review_flags":["Instructions mention water outside the ingredient list; source list retained. Review cooking/soaking water handling in the app."],"prep_minutes":15,"cook_minutes":60,"additional_time_text":null,"default_image":null,"slug":"coconut-chicken-and-papaya-soup"},
{"id":32,"name":"Coconut And Ginger Chicken Soup","filipino_name":"Ginataang Manok","category":"Chicken","prep_time_text":"15 minutes","cook_time_text":"1 hour","yield_type":"serves","yield_text":"4 to 6","ingredients":[{"source_text":"3 tablespoons canola oil","source_pdf_page":70,"section":null,"position":1,"match_options":["canola oil"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3 tablespoons","related_recipe_id":null},{"source_text":"1/2 onion, thinly sliced","source_pdf_page":70,"section":null,"position":2,"match_options":["onion"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2","related_recipe_id":null},{"source_text":"2 tablespoons peeled and thinly sliced ginger","source_pdf_page":70,"section":null,"position":3,"match_options":["ginger"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 tablespoons","related_recipe_id":null},{"source_text":"1 tablespoon crushed garlic","source_pdf_page":70,"section":null,"position":4,"match_options":["garlic"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 tablespoon","related_recipe_id":null},{"source_text":"2 pounds bone-in chicken (thighs, drumsticks, or a combination)","source_pdf_page":70,"section":null,"position":5,"match_options":["chicken"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 pounds","related_recipe_id":null},{"source_text":"2 (13.5-ounce) cans full-fat coconut milk","source_pdf_page":70,"section":null,"position":6,"match_options":["coconut milk"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 (13.5-ounce) cans","related_recipe_id":null},{"source_text":"1 bay leaf","source_pdf_page":70,"section":null,"position":7,"match_options":["bay leaf"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"2 green papayas, peeled and cut into 2-inch cubes (see tip)","source_pdf_page":70,"section":null,"position":8,"match_options":["green papaya"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2","related_recipe_id":null},{"source_text":"1 (13.5-ounce) can coconut cream","source_pdf_page":70,"section":null,"position":9,"match_options":["coconut cream"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 (13.5-ounce) can","related_recipe_id":null},{"source_text":"Salt","source_pdf_page":70,"section":null,"position":10,"match_options":["salt"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":null,"related_recipe_id":null},{"source_text":"Freshly ground black pepper","source_pdf_page":70,"section":null,"position":11,"match_options":["black pepper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":null,"related_recipe_id":null},{"source_text":"3 labuyo chiles (optional)","source_pdf_page":70,"section":null,"position":12,"match_options":["labuyo chili"],"match_rule":"single","role":"optional","required_for_matching":false,"quantity_prefix_text":"3","related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"In a large sauté pan or skillet, heat the oil over medium-high heat. Add the onion and sauté for 3 to 5 minutes, or until translucent. Add the ginger and garlic and sauté until fragrant, about 30 seconds."},{"step":2,"source_step":2,"section":null,"text":"Add the chicken and cook for 5 to 10 minutes, or until lightly browned."},{"step":3,"source_step":3,"section":null,"text":"Stir in the coconut milk and add the bay leaf. Bring it to a boil for about 3 minutes. Reduce the heat to low and let it simmer, uncovered, for 20 minutes."},{"step":4,"source_step":4,"section":null,"text":"Add the papaya and cook until the chicken and papaya are both tender, for about 10 to 15 minutes. Stir a few times to ensure the chicken is not sticking to pan."},{"step":5,"source_step":5,"section":null,"text":"Stir in the coconut cream. Season with salt and pepper and continue to cook for about 10 minutes, or until the liquid has reduced to the consistency of a thick stew."},{"step":6,"source_step":6,"section":null,"text":"Stir in the labuyo chiles, if using, and serve."}],"source_tips":["SUBSTITUTION TIP: You can use potatoes in place of green papayas."],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[70],"printed_pages":[62]},"review_flags":[],"prep_minutes":15,"cook_minutes":60,"additional_time_text":null,"default_image":null,"slug":"coconut-and-ginger-chicken-soup"},
{"id":33,"name":"Easy Chicken Sour Soup","filipino_name":"Sinampalukan Manok","category":"Chicken","prep_time_text":"10 minutes","cook_time_text":"40 minutes","yield_type":"serves","yield_text":"4","ingredients":[{"source_text":"3 tablespoons canola oil","source_pdf_page":71,"section":null,"position":1,"match_options":["canola oil"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3 tablespoons","related_recipe_id":null},{"source_text":"2 tomatoes, quartered","source_pdf_page":71,"section":null,"position":2,"match_options":["tomato"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2","related_recipe_id":null},{"source_text":"1/2 onion, quartered","source_pdf_page":71,"section":null,"position":3,"match_options":["onion"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2","related_recipe_id":null},{"source_text":"2 pounds whole chicken legs, cut into drumsticks and thighs","source_pdf_page":71,"section":null,"position":4,"match_options":["chicken"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 pounds","related_recipe_id":null},{"source_text":"2 cups young tamarind leaves and flowers or sorrel","source_pdf_page":71,"section":null,"position":5,"match_options":["tamarind leaf and flower","sorrel"],"match_rule":"any_of","role":"main","required_for_matching":true,"quantity_prefix_text":"2 cups","related_recipe_id":null},{"source_text":"1 1/2 tablespoons salt","source_pdf_page":71,"section":null,"position":6,"match_options":["salt"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 1/2 tablespoons","related_recipe_id":null},{"source_text":"1 tablespoon fish sauce","source_pdf_page":71,"section":null,"position":7,"match_options":["fish sauce"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 tablespoon","related_recipe_id":null},{"source_text":"1 pound long beans or green beans, cut about 2 to 3 inches long","source_pdf_page":71,"section":null,"position":8,"match_options":["long bean","green bean"],"match_rule":"any_of","role":"main","required_for_matching":true,"quantity_prefix_text":"1 pound","related_recipe_id":null},{"source_text":"2 cups sweet potato leaves (see tip)","source_pdf_page":71,"section":null,"position":9,"match_options":["sweet potato leaf"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 cups","related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"In a wok or large pot, heat the oil over medium-high heat. Sauté the tomatoes and onion for 3 to 5 minutes, or until softened."},{"step":2,"source_step":2,"section":null,"text":"Add the chicken and sauté for 5 to 6 minutes, or until browned on the outside."},{"step":3,"source_step":3,"section":null,"text":"Add enough water to fully cover the chicken, then add the tamarind leaves. Cook until the chicken is tender, about 20 minutes."},{"step":4,"source_step":4,"section":null,"text":"Season with salt and fish sauce. Add the long beans and simmer until they are bright green and crisp, 3 to 5 minutes."},{"step":5,"source_step":5,"section":null,"text":"Turn off the heat and add the sweet potato leaves, stirring until wilted."}],"source_tips":["INGREDIENT TIP: Called kamote, sweet potato leaves are a healthy green widely used throughout Asia and Africa. Unlike potatoes with inedible greens, sweet potato greens are strongly flavored, very nutritious, and work well in stir-fries, sauces, and simmered dishes. Look for them frozen at Asian markets or use spinach instead."],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[71],"printed_pages":[63]},"review_flags":["Instructions mention water outside the ingredient list; source list retained. Review cooking/soaking water handling in the app."],"prep_minutes":10,"cook_minutes":40,"additional_time_text":null,"default_image":null,"slug":"easy-chicken-sour-soup"},
{"id":34,"name":"Tamarind Chicken Sour Soup","filipino_name":"Sinigang Manok","category":"Chicken","prep_time_text":"15 minutes","cook_time_text":"40 minutes","yield_type":"serves","yield_text":"4 to 6","ingredients":[{"source_text":"3 tablespoons canola oil","source_pdf_page":72,"section":null,"position":1,"match_options":["canola oil"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3 tablespoons","related_recipe_id":null},{"source_text":"2 tomatoes, quartered","source_pdf_page":72,"section":null,"position":2,"match_options":["tomato"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2","related_recipe_id":null},{"source_text":"1 onion, quartered","source_pdf_page":72,"section":null,"position":3,"match_options":["onion"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"4 pounds leg quarters, separated","source_pdf_page":72,"section":null,"position":4,"match_options":["chicken"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"4 pounds","related_recipe_id":null},{"source_text":"16 cups chicken stock","source_pdf_page":72,"section":null,"position":5,"match_options":["chicken stock"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"16 cups","related_recipe_id":null},{"source_text":"10 whole tamarind pods (see tip)","source_pdf_page":72,"section":null,"position":6,"match_options":["tamarind"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"10","related_recipe_id":null},{"source_text":"4 small taro root, peeled and cut in half","source_pdf_page":72,"section":null,"position":7,"match_options":["taro root"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"4","related_recipe_id":null},{"source_text":"2 cups long beans or green beans, cut into 3-inch pieces","source_pdf_page":72,"section":null,"position":8,"match_options":["long bean","green bean"],"match_rule":"any_of","role":"main","required_for_matching":true,"quantity_prefix_text":"2 cups","related_recipe_id":null},{"source_text":"Salt","source_pdf_page":72,"section":null,"position":9,"match_options":["salt"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":null,"related_recipe_id":null},{"source_text":"2 cups spinach, trimmed","source_pdf_page":72,"section":null,"position":10,"match_options":["spinach"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 cups","related_recipe_id":null},{"source_text":"3 siling Tagalog (long chile) (optional)","source_pdf_page":72,"section":null,"position":11,"match_options":["green chili"],"match_rule":"single","role":"optional","required_for_matching":false,"quantity_prefix_text":"3","related_recipe_id":null},{"source_text":"3 Calamansi or lemons, halved, for serving","source_pdf_page":72,"section":null,"position":12,"match_options":["calamansi","lemon"],"match_rule":"any_of","role":"serving","required_for_matching":false,"quantity_prefix_text":"3","related_recipe_id":null},{"source_text":"Fish sauce, for serving","source_pdf_page":72,"section":null,"position":13,"match_options":["fish sauce"],"match_rule":"single","role":"serving","required_for_matching":false,"quantity_prefix_text":null,"related_recipe_id":null},{"source_text":"Steamed rice (optional)","source_pdf_page":72,"section":null,"position":14,"match_options":["cooked rice"],"match_rule":"single","role":"optional","required_for_matching":false,"quantity_prefix_text":null,"related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"In a large pot, heat the oil over medium-high heat and sauté the tomatoes and onion for 3 to 5 minutes, or until softened. Add the chicken and sauté for 2 to 3 minutes, until lightly browned."},{"step":2,"source_step":2,"section":null,"text":"Add the chicken stock and bring it to a boil over high heat for 20 minutes, skimming the foam off the surface as it cooks."},{"step":3,"source_step":3,"section":null,"text":"Meanwhile, in a separate large pot, boil the tamarind pods, covered in water, for about 15 minutes, until soft."},{"step":4,"source_step":4,"section":null,"text":"Turn off the heat and remove the tamarind. Using the back of a ladle, mash the tamarind in a strainer set over a medium bowl to catch the tamarind pulp and juice. Reserve the pulp and juice. Discard the tamarind pods."},{"step":5,"source_step":5,"section":null,"text":"Add the taro root and the tamarind pulp and juice to the soup. Reduce the heat to medium and continue to simmer for 10 minutes, or until the chicken is cooked through and the taro is fork-tender."},{"step":6,"source_step":6,"section":null,"text":"Add the long beans and cook until bright green and crisp, about 3 minutes."},{"step":7,"source_step":7,"section":null,"text":"Season with salt and stir in the spinach and chile, if using."},{"step":8,"source_step":8,"section":null,"text":"Serve hot with sides of calamansi and fish sauce."}],"source_tips":["SUBSTITUTION TIP: Substitute 2 packs of Sinigang Sampalok, a packaged tamarind soup mix, if whole tamarind pods are unavailable. Follow package directions for mixing with water. Skip steps 3 and 4 and add the liquid soup mix to the soup as instructed in step 5. Continue preparing the recipe as directed."],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[72,73],"printed_pages":[64,65]},"review_flags":["Instructions mention water outside the ingredient list; source list retained. Review cooking/soaking water handling in the app."],"prep_minutes":15,"cook_minutes":40,"additional_time_text":null,"default_image":null,"slug":"tamarind-chicken-sour-soup"},
{"id":35,"name":"Chicken Soup With Macaroni","filipino_name":"Sopas Na Manok","category":"Chicken","prep_time_text":"20 minutes","cook_time_text":"20 minutes","yield_type":"serves","yield_text":"4 to 6","ingredients":[{"source_text":"3 tablespoons canola oil","source_pdf_page":74,"section":null,"position":1,"match_options":["canola oil"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3 tablespoons","related_recipe_id":null},{"source_text":"1/2 onion, finely chopped","source_pdf_page":74,"section":null,"position":2,"match_options":["onion"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2","related_recipe_id":null},{"source_text":"2 tablespoons minced garlic","source_pdf_page":74,"section":null,"position":3,"match_options":["garlic"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 tablespoons","related_recipe_id":null},{"source_text":"1/2 cooked boneless, skinless chicken breast, shredded","source_pdf_page":74,"section":null,"position":4,"match_options":["cooked chicken"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2","related_recipe_id":null},{"source_text":"2 cups finely chopped carrots","source_pdf_page":74,"section":null,"position":5,"match_options":["carrot"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 cups","related_recipe_id":null},{"source_text":"1 cup finely chopped celery","source_pdf_page":74,"section":null,"position":6,"match_options":["celery"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 cup","related_recipe_id":null},{"source_text":"6 to 8 cups chicken stock","source_pdf_page":74,"section":null,"position":7,"match_options":["chicken stock"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"6 to 8 cups","related_recipe_id":null},{"source_text":"2 cups elbow macaroni noodles","source_pdf_page":74,"section":null,"position":8,"match_options":["elbow macaroni"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 cups","related_recipe_id":null},{"source_text":"5 hot dogs, cut into 1/2-inch- thick slices on the bias","source_pdf_page":74,"section":null,"position":9,"match_options":["hot dog"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"5","related_recipe_id":null},{"source_text":"2 cups evaporated milk or heavy cream","source_pdf_page":74,"section":null,"position":10,"match_options":["evaporated milk","heavy cream"],"match_rule":"any_of","role":"main","required_for_matching":true,"quantity_prefix_text":"2 cups","related_recipe_id":null},{"source_text":"1/2 cabbage, shredded","source_pdf_page":74,"section":null,"position":11,"match_options":["cabbage"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2","related_recipe_id":null},{"source_text":"1 tablespoon butter","source_pdf_page":74,"section":null,"position":12,"match_options":["butter"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 tablespoon","related_recipe_id":null},{"source_text":"2 tablespoons freshly squeezed calamansi juice or lemon juice","source_pdf_page":74,"section":null,"position":13,"match_options":["calamansi","lemon"],"match_rule":"any_of","role":"main","required_for_matching":true,"quantity_prefix_text":"2 tablespoons","related_recipe_id":null},{"source_text":"Salt","source_pdf_page":74,"section":null,"position":14,"match_options":["salt"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":null,"related_recipe_id":null},{"source_text":"Freshly ground black pepper","source_pdf_page":74,"section":null,"position":15,"match_options":["black pepper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":null,"related_recipe_id":null},{"source_text":"1/4 cup thinly sliced scallions, both white and green parts","source_pdf_page":74,"section":null,"position":16,"match_options":["scallion"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/4 cup","related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"In a medium-size deep pot, heat the oil over medium-high heat and sauté the onion and garlic for about 3 minutes, or until translucent and fragrant."},{"step":2,"source_step":2,"section":null,"text":"Add the shredded chicken, carrots, and celery, and continue to sauté for about 5 minutes."},{"step":3,"source_step":3,"section":null,"text":"Pour enough chicken stock to cover the sautéed ingredients and let it simmer for 1 minute. Add the noodles and cook for 8 to 10 minutes, or until the noodles are al dente."},{"step":4,"source_step":4,"section":null,"text":"While constantly stirring, add the hot dogs and milk. Add the cabbage and butter, and stir to combine."},{"step":5,"source_step":5,"section":null,"text":"Stir in the calamansi juice. Taste, and season with salt and pepper."},{"step":6,"source_step":6,"section":null,"text":"Divide into serving bowls, and sprinkle with the scallions to garnish."}],"source_tips":[],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[74],"printed_pages":[66]},"review_flags":[],"prep_minutes":20,"cook_minutes":20,"additional_time_text":null,"default_image":null,"slug":"chicken-soup-with-macaroni"},
{"id":36,"name":"Easy Sauteed Chicken With Green Beans","filipino_name":"Ginisang Manok","category":"Chicken","prep_time_text":"15 minutes","cook_time_text":"25 minutes","yield_type":"serves","yield_text":"4 to 6","ingredients":[{"source_text":"3 tablespoons canola oil or vegetable oil","source_pdf_page":75,"section":null,"position":1,"match_options":["canola oil","vegetable oil"],"match_rule":"any_of","role":"main","required_for_matching":true,"quantity_prefix_text":"3 tablespoons","related_recipe_id":null},{"source_text":"1 shallot, thinly sliced","source_pdf_page":75,"section":null,"position":2,"match_options":["shallot"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"3 garlic cloves, minced","source_pdf_page":75,"section":null,"position":3,"match_options":["garlic"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3","related_recipe_id":null},{"source_text":"2 pounds boneless chicken thighs, cut into 1-inch cubes","source_pdf_page":75,"section":null,"position":4,"match_options":["chicken"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 pounds","related_recipe_id":null},{"source_text":"1 teaspoon sugar","source_pdf_page":75,"section":null,"position":5,"match_options":["sugar"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 teaspoon","related_recipe_id":null},{"source_text":"1/2 cup chicken stock","source_pdf_page":75,"section":null,"position":6,"match_options":["chicken stock"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2 cup","related_recipe_id":null},{"source_text":"1 pound green beans, cut into 1-inch pieces","source_pdf_page":75,"section":null,"position":7,"match_options":["green bean"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 pound","related_recipe_id":null},{"source_text":"1 red bell pepper, thinly sliced","source_pdf_page":75,"section":null,"position":8,"match_options":["red bell pepper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"Salt","source_pdf_page":75,"section":null,"position":9,"match_options":["salt"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":null,"related_recipe_id":null},{"source_text":"Freshly ground black pepper","source_pdf_page":75,"section":null,"position":10,"match_options":["black pepper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":null,"related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"In a large sauté pan or skillet, heat the oil over medium-high heat. Sauté the shallot for 3 to 5 minutes, or until translucent. Add the garlic and sauté until fragrant, about 30 seconds."},{"step":2,"source_step":2,"section":null,"text":"Add the chicken and sauté until lightly browned, 3 to 5 minutes."},{"step":3,"source_step":3,"section":null,"text":"Stir in the sugar and mix well. Add the chicken stock and simmer for 10 minutes, or until the chicken is fork-tender and cooked through."},{"step":4,"source_step":4,"section":null,"text":"Stir in the green beans and bell pepper and cook for 3 minutes, or until the beans are bright green and crisp. Season with salt and pepper."}],"source_tips":["VARIATION TIP: Different varieties of vegetables like chayote, cabbage, and green papaya are commonly included in the dish; feel free to add or substitute as desired."],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[75],"printed_pages":[67]},"review_flags":[],"prep_minutes":15,"cook_minutes":25,"additional_time_text":null,"default_image":null,"slug":"easy-sauteed-chicken-with-green-beans"},
{"id":37,"name":"Chicken Inasal","filipino_name":null,"category":"Chicken","prep_time_text":"10 minutes, plus 1 hour (or overnight) to marinate","cook_time_text":"35 minutes","yield_type":"serves","yield_text":"4","ingredients":[{"source_text":"1 cup vinegar","source_pdf_page":76,"section":"FOR THE MARINADE","position":1,"match_options":["vinegar"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 cup","related_recipe_id":null},{"source_text":"1 cup brown sugar","source_pdf_page":76,"section":"FOR THE MARINADE","position":2,"match_options":["brown sugar"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 cup","related_recipe_id":null},{"source_text":"1/2 cup freshly squeezed calamansi juice or lemon juice","source_pdf_page":76,"section":"FOR THE MARINADE","position":3,"match_options":["calamansi","lemon"],"match_rule":"any_of","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2 cup","quantity_note":"Display source_text to preserve compound quantities and/or alternative amounts; quantity_prefix_text is only the leading amount.","related_recipe_id":null},{"source_text":"3 lemongrass stalks, trimmed and cut into 1-inch pieces","source_pdf_page":76,"section":"FOR THE MARINADE","position":4,"match_options":["lemongrass"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3","related_recipe_id":null},{"source_text":"4 garlic cloves, peeled","source_pdf_page":76,"section":"FOR THE MARINADE","position":5,"match_options":["garlic"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"4","related_recipe_id":null},{"source_text":"2-inch piece of ginger, peeled and quartered","source_pdf_page":76,"section":"FOR THE MARINADE","position":6,"match_options":["ginger"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2-inch piece","related_recipe_id":null},{"source_text":"2 tablespoons salt","source_pdf_page":76,"section":"FOR THE MARINADE","position":7,"match_options":["salt"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 tablespoons","related_recipe_id":null},{"source_text":"1 teaspoon freshly ground black pepper","source_pdf_page":76,"section":"FOR THE MARINADE","position":8,"match_options":["black pepper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 teaspoon","related_recipe_id":null},{"source_text":"4 whole chicken legs, cut into drumsticks and thighs","source_pdf_page":76,"section":"FOR THE CHICKEN","position":9,"match_options":["chicken"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"4","related_recipe_id":null},{"source_text":"3 tablespoons annatto oil (see Ingredient Tip)","source_pdf_page":76,"section":"FOR THE CHICKEN","position":10,"match_options":["annatto oil"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3 tablespoons","related_recipe_id":null},{"source_text":"1/2 cup butter, melted","source_pdf_page":76,"section":"FOR THE CHICKEN","position":11,"match_options":["butter"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2 cup","related_recipe_id":null}],"instructions":[{"step":1,"source_step":null,"section":"TO MAKE THE MARINADE","text":"In a blender, combine the vinegar, brown sugar, calamansi juice, lemongrass, garlic, ginger, salt, and pepper. Pulse to combine. Set aside."},{"step":2,"source_step":1,"section":"TO MAKE THE CHICKEN","text":"Pat the chicken pieces dry with paper towels and arrange them in a single layer in a nonreactive baking dish. Pour in the marinade and stir to make sure the chicken is evenly coated. Cover and refrigerate for 1 hour, or as long as overnight."},{"step":3,"source_step":2,"section":"TO MAKE THE CHICKEN","text":"Preheat the grill to medium."},{"step":4,"source_step":3,"section":"TO MAKE THE CHICKEN","text":"In a small bowl, combine the annatto oil with the butter."},{"step":5,"source_step":4,"section":"TO MAKE THE CHICKEN","text":"Remove the chicken from the marinade and discard the marinade. Place the chicken on the grill and baste it with the annatto and butter mixture."},{"step":6,"source_step":5,"section":"TO MAKE THE CHICKEN","text":"Cook for 8 minutes, or until there are grill marks on the chicken. Turn the chicken pieces over, baste the top side, and cook for another 8 minutes."},{"step":7,"source_step":6,"section":"TO MAKE THE CHICKEN","text":"Continue regularly basting and turning the chicken for about 15 to 20 minutes, until the juices run clear and the internal temperature is 165°F in the thickest part of the meat."}],"source_tips":["INGREDIENT TIP: To make annatto oil, heat 1/4 cup of olive or canola oil over medium heat until shimmering. Add 1 tablespoon of annatto seeds to the hot oil for 5 to 10 minutes and strain and discard the seeds and reserve the oil for later use.","COOKING TIP: If you don’t have a grill, cook the chicken in a baking dish, uncovered, in a 375°F oven for 45 to 60 minutes."],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[76,77],"printed_pages":[68,69]},"review_flags":["Additional waiting time is retained as text; do not display prep + cook as total elapsed time.","Multi-component recipe: preserve ingredient sections and instruction sections."],"prep_minutes":10,"cook_minutes":35,"additional_time_text":"1 hour (or overnight) to marinate","default_image":null,"slug":"chicken-inasal"},
{"id":38,"name":"Chicken Barbecue","filipino_name":"Inihaw Na Manok","category":"Chicken","prep_time_text":"15 minutes, plus 2 hours (or overnight) to marinate","cook_time_text":"15 minutes","yield_type":"serves","yield_text":"4","ingredients":[{"source_text":"1 1/2 cups soy sauce","source_pdf_page":78,"section":null,"position":1,"match_options":["soy sauce"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 1/2 cups","related_recipe_id":null},{"source_text":"1 1/2 cups sugar","source_pdf_page":78,"section":null,"position":2,"match_options":["sugar"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 1/2 cups","related_recipe_id":null},{"source_text":"1 1/2 cups Banana Ketchup (page 153)","source_pdf_page":78,"section":null,"position":3,"match_options":["banana ketchup"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 1/2 cups","related_recipe_id":98},{"source_text":"1 cup freshly squeezed calamansi juice or lemon juice","source_pdf_page":78,"section":null,"position":4,"match_options":["calamansi","lemon"],"match_rule":"any_of","role":"main","required_for_matching":true,"quantity_prefix_text":"1 cup","related_recipe_id":null},{"source_text":"1 teaspoon crushed garlic","source_pdf_page":78,"section":null,"position":5,"match_options":["garlic"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 teaspoon","related_recipe_id":null},{"source_text":"1/3 teaspoon freshly ground black pepper","source_pdf_page":78,"section":null,"position":6,"match_options":["black pepper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/3 teaspoon","related_recipe_id":null},{"source_text":"3 pounds boneless chicken thighs, cut into 1-inch pieces","source_pdf_page":78,"section":null,"position":7,"match_options":["chicken"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3 pounds","related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"In a large bowl, combine the soy sauce, sugar, ketchup, calamansi juice, garlic, and pepper and stir until the sugar is dissolved."},{"step":2,"source_step":2,"section":null,"text":"Add the chicken to the marinade and cover with plastic wrap. Marinate in the refrigerator for at least 2 hours, or as long as overnight."},{"step":3,"source_step":3,"section":null,"text":"Thread the chicken onto skewers and discard the marinade."},{"step":4,"source_step":4,"section":null,"text":"Preheat the grill on high. Grill the chicken, turning several times, until it is cooked through, 10 to 12 minutes."}],"source_tips":["PREP TIP: If using wooden skewers, be sure to soak the skewers in water for 30 minutes prior to threading the chicken on them. This will prevent them from catching fire and burning while on the grill."],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[78],"printed_pages":[70]},"review_flags":["Additional waiting time is retained as text; do not display prep + cook as total elapsed time."],"prep_minutes":15,"cook_minutes":15,"additional_time_text":"2 hours (or overnight) to marinate","default_image":null,"slug":"chicken-barbecue"},
{"id":39,"name":"Chicken Adobo","filipino_name":null,"category":"Chicken","prep_time_text":"5 minutes","cook_time_text":"30 minutes","yield_type":"serves","yield_text":"6 to 8","ingredients":[{"source_text":"5 pounds chicken drumsticks, bone-in thighs, or a combination","source_pdf_page":79,"section":null,"position":1,"match_options":["chicken"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"5 pounds","related_recipe_id":null},{"source_text":"1 cup soy sauce","source_pdf_page":79,"section":null,"position":2,"match_options":["soy sauce"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 cup","related_recipe_id":null},{"source_text":"1 cup coconut vinegar (see tip)","source_pdf_page":79,"section":null,"position":3,"match_options":["coconut vinegar"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 cup","related_recipe_id":null},{"source_text":"1 cup water","source_pdf_page":79,"section":null,"position":4,"match_options":["water"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 cup","related_recipe_id":null},{"source_text":"1 head garlic, peeled and crushed","source_pdf_page":79,"section":null,"position":5,"match_options":["garlic"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 head","related_recipe_id":null},{"source_text":"1 teaspoon whole black peppercorns","source_pdf_page":79,"section":null,"position":6,"match_options":["black peppercorn"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 teaspoon","related_recipe_id":null},{"source_text":"5 bay leaves","source_pdf_page":79,"section":null,"position":7,"match_options":["bay leaf"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"5","related_recipe_id":null},{"source_text":"5 thinly sliced Thai chiles, for garnish","source_pdf_page":79,"section":null,"position":8,"match_options":["thai chili"],"match_rule":"single","role":"garnish","required_for_matching":false,"quantity_prefix_text":"5","related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"In a wok or large pot, combine the chicken with the soy sauce, vinegar, water, garlic, peppercorns, and bay leaves."},{"step":2,"source_step":2,"section":null,"text":"Turn the heat to medium-high and bring the liquid to a boil, skimming the foam off the surface as it cooks."},{"step":3,"source_step":3,"section":null,"text":"Lower the heat to medium-low and simmer for 30 minutes, until the chicken is fork-tender and the liquid has the consistency of a stew. Taste and adjust the seasoning as desired."},{"step":4,"source_step":4,"section":null,"text":"Garnish with the chiles before serving."}],"source_tips":["VARIATION TIP: While adobo is traditionally made using coconut vinegar, it can be cooked with different types of vinegar like white and balsamic vinegar, too."],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[79],"printed_pages":[71]},"review_flags":[],"prep_minutes":5,"cook_minutes":30,"additional_time_text":null,"default_image":null,"slug":"chicken-adobo"},
{"id":40,"name":"Chicken Curry","filipino_name":null,"category":"Chicken","prep_time_text":"15 minutes","cook_time_text":"40 minutes","yield_type":"serves","yield_text":"4 to 6","ingredients":[{"source_text":"3 tablespoons canola oil","source_pdf_page":80,"section":null,"position":1,"match_options":["canola oil"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3 tablespoons","related_recipe_id":null},{"source_text":"2 pounds whole chicken legs, cut into drumsticks and thighs","source_pdf_page":80,"section":null,"position":2,"match_options":["chicken"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 pounds","related_recipe_id":null},{"source_text":"1/2 onion, cut into 1-inch pieces","source_pdf_page":80,"section":null,"position":3,"match_options":["onion"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2","related_recipe_id":null},{"source_text":"1 (1-inch) piece fresh ginger, peeled and cut into strips","source_pdf_page":80,"section":null,"position":4,"match_options":["ginger"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 (1-inch) piece","related_recipe_id":null},{"source_text":"2 garlic cloves, coarsely chopped","source_pdf_page":80,"section":null,"position":5,"match_options":["garlic"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2","related_recipe_id":null},{"source_text":"2 tablespoons yellow curry powder","source_pdf_page":80,"section":null,"position":6,"match_options":["yellow curry powder"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 tablespoons","related_recipe_id":null},{"source_text":"2 medium potatoes, cut into 1-inch cubes","source_pdf_page":80,"section":null,"position":7,"match_options":["potato"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2","related_recipe_id":null},{"source_text":"1 1/2 cups coconut milk","source_pdf_page":80,"section":null,"position":8,"match_options":["coconut milk"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 1/2 cups","related_recipe_id":null},{"source_text":"1 cup water","source_pdf_page":80,"section":null,"position":9,"match_options":["water"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 cup","related_recipe_id":null},{"source_text":"3 tablespoons vinegar","source_pdf_page":80,"section":null,"position":10,"match_options":["vinegar"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3 tablespoons","related_recipe_id":null},{"source_text":"1 tablespoon salt","source_pdf_page":80,"section":null,"position":11,"match_options":["salt"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 tablespoon","related_recipe_id":null},{"source_text":"1/2 red bell pepper, cut into 1-inch cubes","source_pdf_page":80,"section":null,"position":12,"match_options":["red bell pepper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2","related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"In a wok or large sauté pan, heat the oil over medium-high heat. Add the chicken and brown on all sides. Remove the chicken from pan and set aside."},{"step":2,"source_step":2,"section":null,"text":"In the same pan, sauté the onion, ginger, and garlic for 3 to 5 minutes, or until translucent and fragrant."},{"step":3,"source_step":3,"section":null,"text":"Add the curry powder and stir. Add the chicken, potatoes, coconut milk, water, vinegar, and salt. Reduce the heat to medium-low and simmer until the chicken is tender and cooked through, about 30 minutes."},{"step":4,"source_step":4,"section":null,"text":"Turn off the heat, add the red bell pepper, and stir to combine before serving."}],"source_tips":["SUBSTITUTION TIP: This can also be made using chopped boneless chicken breasts or thighs or a whole chicken. If using a whole chicken, cut it into 8 pieces."],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[80],"printed_pages":[72]},"review_flags":[],"prep_minutes":15,"cook_minutes":40,"additional_time_text":null,"default_image":null,"slug":"chicken-curry"},
{"id":41,"name":"Chicken Afritada","filipino_name":"Afritadang Manok","category":"Chicken","prep_time_text":"15 minutes","cook_time_text":"55 minutes","yield_type":"serves","yield_text":"4 to 6","ingredients":[{"source_text":"3 tablespoons canola oil","source_pdf_page":81,"section":null,"position":1,"match_options":["canola oil"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3 tablespoons","related_recipe_id":null},{"source_text":"4 pounds whole chicken legs, cut into drumsticks and thighs","source_pdf_page":81,"section":null,"position":2,"match_options":["chicken"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"4 pounds","related_recipe_id":null},{"source_text":"1/2 onion, sliced into 2-inch cubes","source_pdf_page":81,"section":null,"position":3,"match_options":["onion"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2","related_recipe_id":null},{"source_text":"3 garlic cloves, crushed","source_pdf_page":81,"section":null,"position":4,"match_options":["garlic"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3","related_recipe_id":null},{"source_text":"2 tomatoes, sliced into 2-inch cubes","source_pdf_page":81,"section":null,"position":5,"match_options":["tomato"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2","related_recipe_id":null},{"source_text":"2 cups water","source_pdf_page":81,"section":null,"position":6,"match_options":["water"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 cups","related_recipe_id":null},{"source_text":"1 bay leaf","source_pdf_page":81,"section":null,"position":7,"match_options":["bay leaf"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"2 cups tomato sauce","source_pdf_page":81,"section":null,"position":8,"match_options":["tomato sauce"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 cups","related_recipe_id":null},{"source_text":"2 medium potatoes, cut into 2-inch cubes","source_pdf_page":81,"section":null,"position":9,"match_options":["potato"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2","related_recipe_id":null},{"source_text":"1 medium carrot, cut into 2-inch cubes","source_pdf_page":81,"section":null,"position":10,"match_options":["carrot"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"1/2 cup green peas","source_pdf_page":81,"section":null,"position":11,"match_options":["green pea"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2 cup","related_recipe_id":null},{"source_text":"1/2 cup grated cheddar cheese (optional)","source_pdf_page":81,"section":null,"position":12,"match_options":["cheddar cheese"],"match_rule":"single","role":"optional","required_for_matching":false,"quantity_prefix_text":"1/2 cup","related_recipe_id":null},{"source_text":"Salt","source_pdf_page":81,"section":null,"position":13,"match_options":["salt"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":null,"related_recipe_id":null},{"source_text":"Freshly ground black pepper","source_pdf_page":81,"section":null,"position":14,"match_options":["black pepper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":null,"related_recipe_id":null},{"source_text":"1 red bell pepper, cut into 2-inch pieces","source_pdf_page":81,"section":null,"position":15,"match_options":["red bell pepper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"In a large sauté pan or skillet, heat the oil over medium-high heat. Working in batches, place the chicken in the pan skin-side down and panfry until lightly browned, about 5 minutes. Remove from the pan and set aside."},{"step":2,"source_step":2,"section":null,"text":"Add the onion and cook for 3 to 5 minutes, or until translucent. Add the garlic and sauté until fragrant, about 30 seconds. Add the tomatoes and sauté for 2 minutes, or until they begin to soften."},{"step":3,"source_step":3,"section":null,"text":"Add the water and bay leaf. Turn the heat to medium and simmer the chicken for 20 minutes. Stir in the tomato sauce, potatoes, and carrot and cook for 10 minutes."},{"step":4,"source_step":4,"section":null,"text":"Stir in the green peas. Cook for 10 more minutes, until reduced to the consistency of stew. Stir in the cheese, if using, until it melts."},{"step":5,"source_step":5,"section":null,"text":"Taste, and adjust seasoning with salt and pepper. Turn off the heat and stir in the red bell peppers before serving."}],"source_tips":["INGREDIENT TIP: To speed up cooking time, substitute boneless breasts or thighs cut into serving-size pieces."],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[81],"printed_pages":[73]},"review_flags":[],"prep_minutes":15,"cook_minutes":55,"additional_time_text":null,"default_image":null,"slug":"chicken-afritada"},
{"id":42,"name":"Chicken Pastel","filipino_name":null,"category":"Chicken","prep_time_text":"15 minutes, plus 15 minutes to marinate","cook_time_text":"1 hour","yield_type":"serves","yield_text":"4 to 6","ingredients":[{"source_text":"2 pounds boneless skinless chicken thighs, cut into 1/4-inch cubes","source_pdf_page":82,"section":null,"position":1,"match_options":["chicken"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 pounds","related_recipe_id":null},{"source_text":"3 tablespoons freshly squeezed calamansi juice or lemon juice","source_pdf_page":82,"section":null,"position":2,"match_options":["calamansi","lemon"],"match_rule":"any_of","role":"main","required_for_matching":true,"quantity_prefix_text":"3 tablespoons","related_recipe_id":null},{"source_text":"3 tablespoons soy sauce","source_pdf_page":82,"section":null,"position":3,"match_options":["soy sauce"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3 tablespoons","related_recipe_id":null},{"source_text":"3 tablespoons butter","source_pdf_page":82,"section":null,"position":4,"match_options":["butter"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3 tablespoons","related_recipe_id":null},{"source_text":"1 shallot, minced","source_pdf_page":82,"section":null,"position":5,"match_options":["shallot"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"2 garlic cloves, minced","source_pdf_page":82,"section":null,"position":6,"match_options":["garlic"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2","related_recipe_id":null},{"source_text":"1 chorizo sausage, cut into 1/3-inch slices","source_pdf_page":82,"section":null,"position":7,"match_options":["chorizo"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"1 cup chicken stock","source_pdf_page":82,"section":null,"position":8,"match_options":["chicken stock"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 cup","related_recipe_id":null},{"source_text":"1/4 cup finely chopped potatoes","source_pdf_page":82,"section":null,"position":9,"match_options":["potato"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/4 cup","related_recipe_id":null},{"source_text":"1/4 cup finely chopped carrots","source_pdf_page":82,"section":null,"position":10,"match_options":["carrot"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/4 cup","related_recipe_id":null},{"source_text":"1/4 cup frozen green peas","source_pdf_page":82,"section":null,"position":11,"match_options":["green pea"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/4 cup","related_recipe_id":null},{"source_text":"1/4 cup finely chopped red bell pepper","source_pdf_page":82,"section":null,"position":12,"match_options":["red bell pepper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/4 cup","related_recipe_id":null},{"source_text":"1 cup heavy cream","source_pdf_page":82,"section":null,"position":13,"match_options":["heavy cream"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 cup","related_recipe_id":null},{"source_text":"1/2 cup shredded Edam cheese (see tip)","source_pdf_page":82,"section":null,"position":14,"match_options":["edam cheese"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2 cup","related_recipe_id":null},{"source_text":"Salt","source_pdf_page":82,"section":null,"position":15,"match_options":["salt"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":null,"related_recipe_id":null},{"source_text":"Freshly ground black pepper","source_pdf_page":82,"section":null,"position":16,"match_options":["black pepper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":null,"related_recipe_id":null},{"source_text":"1 frozen piecrust, thawed","source_pdf_page":82,"section":null,"position":17,"match_options":["piecrust"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"In a medium bowl, marinate the chicken in calamansi juice and soy sauce for 15 minutes."},{"step":2,"source_step":2,"section":null,"text":"In a large sauté pan or skillet, melt the butter over medium-high heat and sauté the shallot and garlic in butter for 3 to 5 minutes, or until translucent and fragrant."},{"step":3,"source_step":3,"section":null,"text":"Stir in the chicken and sauté for 5 to 6 minutes, or until the meat is no longer pink. Stir in the chorizo. Pour in the chicken stock, reduce the heat to medium-low, and simmer for 20 minutes."},{"step":4,"source_step":4,"section":null,"text":"Preheat the oven to 350°F."},{"step":5,"source_step":5,"section":null,"text":"Add the potatoes, carrots, peas, and bell pepper, and cook for 5 to 7 minutes, until the chicken and vegetables are fork-tender."},{"step":6,"source_step":6,"section":null,"text":"Stir in the cream and cheese, and cook until the mixture has reduced to consistency of potpie filling, about 5 minutes. Season with salt and pepper."},{"step":7,"source_step":7,"section":null,"text":"Transfer the mixture to a 9-inch round baking dish. Cover with the piecrust and press edges of the crust around the baking dish to seal. Cut three slits in the crust to let steam out."},{"step":8,"source_step":8,"section":null,"text":"Bake for 25 minutes, or until browned. Let cool for 5 minutes before serving."}],"source_tips":["INGREDIENT TIP: Edam cheese is a semi-hard cheese from Holland. If Edam cheese is unavailable at your local grocery, Parmesan cheese or cheddar cheese may be used instead."],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[82,83],"printed_pages":[74,75]},"review_flags":["Additional waiting time is retained as text; do not display prep + cook as total elapsed time."],"prep_minutes":15,"cook_minutes":60,"additional_time_text":"15 minutes to marinate","default_image":null,"slug":"chicken-pastel"},
{"id":43,"name":"Pineapple Chicken","filipino_name":"Pininyahang Manok","category":"Chicken","prep_time_text":"10 minutes, plus 30 minutes to marinate","cook_time_text":"40 minutes","yield_type":"serves","yield_text":"4 to 6","ingredients":[{"source_text":"2 pounds boneless, skinless chicken thighs, cut into 2-inch cubes","source_pdf_page":84,"section":null,"position":1,"match_options":["chicken"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 pounds","related_recipe_id":null},{"source_text":"2 cups pineapple juice","source_pdf_page":84,"section":null,"position":2,"match_options":["pineapple juice"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 cups","related_recipe_id":null},{"source_text":"3 tablespoons canola oil","source_pdf_page":84,"section":null,"position":3,"match_options":["canola oil"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3 tablespoons","related_recipe_id":null},{"source_text":"1/2 onion, cut into 1-inch cubes","source_pdf_page":84,"section":null,"position":4,"match_options":["onion"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2","related_recipe_id":null},{"source_text":"2 garlic cloves, crushed","source_pdf_page":84,"section":null,"position":5,"match_options":["garlic"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2","related_recipe_id":null},{"source_text":"2 cups water","source_pdf_page":84,"section":null,"position":6,"match_options":["water"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 cups","related_recipe_id":null},{"source_text":"1 medium carrot, cut into 1-inch cubes","source_pdf_page":84,"section":null,"position":7,"match_options":["carrot"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"1/2 pineapple, cut into chunks (see tips)","source_pdf_page":84,"section":null,"position":8,"match_options":["pineapple"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2","related_recipe_id":null},{"source_text":"1/2 cup evaporated milk","source_pdf_page":84,"section":null,"position":9,"match_options":["evaporated milk"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2 cup","related_recipe_id":null},{"source_text":"Salt","source_pdf_page":84,"section":null,"position":10,"match_options":["salt"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":null,"related_recipe_id":null},{"source_text":"Freshly ground black pepper","source_pdf_page":84,"section":null,"position":11,"match_options":["black pepper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":null,"related_recipe_id":null},{"source_text":"1/2 green bell pepper, cut into 1-inch pieces","source_pdf_page":84,"section":null,"position":12,"match_options":["green bell pepper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2","related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"In a medium bowl, combine the chicken and pineapple juice, cover, and place in the refrigerator to marinate for 30 minutes."},{"step":2,"source_step":2,"section":null,"text":"Remove the chicken from the marinade, discarding the marinade, and pat the chicken dry with paper towels. Set aside."},{"step":3,"source_step":3,"section":null,"text":"In a large skillet, heat the oil over medium-high heat and cook the onion for 3 to 5 minutes, or until translucent. Add the garlic and sauté until fragrant, about 30 seconds."},{"step":4,"source_step":4,"section":null,"text":"Add the chicken and sauté, stirring regularly, for 3 to 4 minutes, or until lightly browned. Add the water and cook for 20 minutes."},{"step":5,"source_step":5,"section":null,"text":"Turn the heat to medium, stir in the carrot, and cook for 10 minutes, until both the chicken and carrot are tender."},{"step":6,"source_step":6,"section":null,"text":"Stir in the pineapple chunks and evaporated milk and let it simmer, reducing the liquid to a consistency of light stew, about 5 minutes."},{"step":7,"source_step":7,"section":null,"text":"Season with salt and pepper. Turn off the heat and stir in the bell pepper. LEFTOVERS TIP: To use the other half of the pineapple, carefully scoop out the flesh, leaving the outer skin intact to use as a serving bowl. Remove the core and place the pineapple flesh in a blender. Process the pineapple along with ice, 2 cups of orange juice, and 1/2 cup of simple syrup made using equal parts sugar and water. Serve in a medium-size drinking glass along with the pineapple chicken served in the pineapple bowl."}],"source_tips":["SUBSTITUTION TIP: 1 (20-ounce) can of pineapple chunks can be drained and used in place of the fresh pineapple."],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[84,85],"printed_pages":[76,77]},"review_flags":["Additional waiting time is retained as text; do not display prep + cook as total elapsed time."],"prep_minutes":10,"cook_minutes":40,"additional_time_text":"30 minutes to marinate","default_image":null,"slug":"pineapple-chicken"},
{"id":44,"name":"Salt-Steamed Chicken","filipino_name":"Pinaupong Manok","category":"Chicken","prep_time_text":"10 minutes","cook_time_text":"1 hour 30 minutes","yield_type":"serves","yield_text":"4 to 6","ingredients":[{"source_text":"2 tablespoons coarse salt","source_pdf_page":86,"section":null,"position":1,"match_options":["salt"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 tablespoons","related_recipe_id":null},{"source_text":"1 teaspoon freshly ground black pepper","source_pdf_page":86,"section":null,"position":2,"match_options":["black pepper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 teaspoon","related_recipe_id":null},{"source_text":"1 whole chicken, washed and patted dry","source_pdf_page":86,"section":null,"position":3,"match_options":["chicken"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"3 lemongrass stalks, trimmed and outer layer removed","source_pdf_page":86,"section":null,"position":4,"match_options":["lemongrass"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3","related_recipe_id":null},{"source_text":"5 scallions, trimmed and outer layer removed","source_pdf_page":86,"section":null,"position":5,"match_options":["scallion"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"5","related_recipe_id":null},{"source_text":"1 onion, peeled and root end cut off","source_pdf_page":86,"section":null,"position":6,"match_options":["onion"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"32 ounces rock salt","source_pdf_page":86,"section":null,"position":7,"match_options":["salt"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"32 ounces","related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"Rub salt and pepper all over the chicken, including inside the cavity."},{"step":2,"source_step":2,"section":null,"text":"Pound the lemongrass to release flavor and place it in the chicken cavity along with the scallions."},{"step":3,"source_step":3,"section":null,"text":"Insert the onion inside the cavity of the chicken, making sure the flat side is facing the mouth of the cavity to help chicken sit upright."},{"step":4,"source_step":4,"section":null,"text":"In a pot deep enough to hold the whole chicken upright, pour the rock salt. Place the pot on the stove burner."},{"step":5,"source_step":5,"section":null,"text":"Inside the pot, arrange the chicken in an upright position with the cavity facing down on top of the salt in the middle of pot and cover tightly."},{"step":6,"source_step":6,"section":null,"text":"Turn the heat to medium and let the chicken steam for 90 minutes, until the internal temperature is 165°F or the juices run clear."},{"step":7,"source_step":7,"section":null,"text":"Remove the chicken from the pot and let it rest for 5 to 10 minutes. Remove the onions and lemongrass from the cavity and discard. LEFTOVERS TIP: Leftovers are great in fried rice. In a large sauté pan or skillet, heat 2 tablespoons of canola oil over medium-high heat. Add 1/2 cup of diced onions and 1 minced garlic clove and sauté until translucent, or 3 to 5 minutes. Add 2 beaten eggs and cook until set, then stir in 2 cups of cooked rice, 1/4 cup of frozen green peas, the leftover chicken, and 1/4 cup of shredded carrots."}],"source_tips":[],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[86,87],"printed_pages":[78,79]},"review_flags":[],"prep_minutes":10,"cook_minutes":90,"additional_time_text":null,"default_image":null,"slug":"salt-steamed-chicken"},
{"id":45,"name":"Chicken Asado","filipino_name":"Asadong Manok","category":"Chicken","prep_time_text":"15 minutes","cook_time_text":"25 minutes","yield_type":"serves","yield_text":"4","ingredients":[{"source_text":"3 tablespoons canola oil","source_pdf_page":88,"section":null,"position":1,"match_options":["canola oil"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3 tablespoons","related_recipe_id":null},{"source_text":"1/2 onion, thinly sliced","source_pdf_page":88,"section":null,"position":2,"match_options":["onion"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2","related_recipe_id":null},{"source_text":"2 garlic cloves, crushed","source_pdf_page":88,"section":null,"position":3,"match_options":["garlic"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2","related_recipe_id":null},{"source_text":"2 pounds boneless, skinless chicken thighs, cut into 2-inch cubes","source_pdf_page":88,"section":null,"position":4,"match_options":["chicken"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 pounds","related_recipe_id":null},{"source_text":"2 cups water","source_pdf_page":88,"section":null,"position":5,"match_options":["water"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 cups","related_recipe_id":null},{"source_text":"1/2 cup soy sauce","source_pdf_page":88,"section":null,"position":6,"match_options":["soy sauce"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2 cup","related_recipe_id":null},{"source_text":"2 tablespoons sugar","source_pdf_page":88,"section":null,"position":7,"match_options":["sugar"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 tablespoons","related_recipe_id":null},{"source_text":"2 bay leaves","source_pdf_page":88,"section":null,"position":8,"match_options":["bay leaf"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2","related_recipe_id":null},{"source_text":"Pinch freshly ground black pepper","source_pdf_page":88,"section":null,"position":9,"match_options":["black pepper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"Pinch","related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"In a large sauté pan or skillet, heat the oil over medium-high heat and sauté the onion for 3 to 5 minutes, or until transparent. Add the garlic and sauté until fragrant, about 30 seconds."},{"step":2,"source_step":2,"section":null,"text":"Add the chicken and continue to sauté for 3 to 4 minutes, or until the chicken is no longer pink."},{"step":3,"source_step":3,"section":null,"text":"Add the water, soy sauce, sugar, bay leaves, and pepper. Simmer for 10 to 20 minutes, until the chicken is tender and the sauce has reduced to the consistency of thick stew. Taste and adjust the seasoning as desired before serving."}],"source_tips":[],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[88],"printed_pages":[80]},"review_flags":[],"prep_minutes":15,"cook_minutes":25,"additional_time_text":null,"default_image":null,"slug":"chicken-asado"},
{"id":46,"name":"Sweet And Savory Pork","filipino_name":"Tocino","category":"Meat","prep_time_text":"5 minutes, plus 20 minutes (or overnight) to marinate","cook_time_text":"30 minutes","yield_type":"serves","yield_text":"4 to 6","ingredients":[{"source_text":"2 pounds pork shoulder, thinly sliced","source_pdf_page":92,"section":null,"position":1,"match_options":["pork"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 pounds","related_recipe_id":null},{"source_text":"1 1/2 cups sugar","source_pdf_page":92,"section":null,"position":2,"match_options":["sugar"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 1/2 cups","related_recipe_id":null},{"source_text":"1 tablespoon salt","source_pdf_page":92,"section":null,"position":3,"match_options":["salt"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 tablespoon","related_recipe_id":null},{"source_text":"1 tablespoon paprika","source_pdf_page":92,"section":null,"position":4,"match_options":["paprika"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 tablespoon","related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"In a large bowl, combine the pork, sugar, salt, and paprika and mix well. Cover and refrigerate for at least 20 minutes or up to 24 hours."},{"step":2,"source_step":2,"section":null,"text":"In a wok or large sauté pan, place the pork and cover with water. Heat over medium-high heat, stirring occasionally until it cooks through and is almost dry, about 30 minutes."}],"source_tips":["SUBSTITUTION TIP: You can use 1 tablespoon of ground annatto in place of paprika, if you have it available."],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[92],"printed_pages":[84]},"review_flags":["Additional waiting time is retained as text; do not display prep + cook as total elapsed time.","Instructions mention water outside the ingredient list; source list retained. Review cooking/soaking water handling in the app."],"prep_minutes":5,"cook_minutes":30,"additional_time_text":"20 minutes (or overnight) to marinate","default_image":null,"slug":"sweet-and-savory-pork"},
{"id":47,"name":"Tamarind And Pork Sour Soup","filipino_name":"Sinigang Baboy","category":"Meat","prep_time_text":"15 minutes","cook_time_text":"40 minutes","yield_type":"serves","yield_text":"4 to 6","ingredients":[{"source_text":"16 cups water","source_pdf_page":93,"section":null,"position":1,"match_options":["water"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"16 cups","related_recipe_id":null},{"source_text":"2 pounds bone-in pork belly or pork spareribs, cut into 1-inch pieces","source_pdf_page":93,"section":null,"position":2,"match_options":["pork"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 pounds","related_recipe_id":null},{"source_text":"2 pounds unripe whole tamarind (see tip)","source_pdf_page":93,"section":null,"position":3,"match_options":["tamarind"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 pounds","related_recipe_id":null},{"source_text":"4 small taro roots, peeled and cut in half","source_pdf_page":93,"section":null,"position":4,"match_options":["taro root"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"4","related_recipe_id":null},{"source_text":"2 tomatoes, quartered","source_pdf_page":93,"section":null,"position":5,"match_options":["tomato"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2","related_recipe_id":null},{"source_text":"1 yellow onion, quartered","source_pdf_page":93,"section":null,"position":6,"match_options":["yellow onion"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"1 Filipino or Chinese or Japanese eggplant, cut into 1/4-inch-thick diagonal slices","source_pdf_page":93,"section":null,"position":7,"match_options":["eggplant"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"1 cup okra, stems removed","source_pdf_page":93,"section":null,"position":8,"match_options":["okra"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 cup","related_recipe_id":null},{"source_text":"2 cups long beans or green beans, cut into 2- to 3-inch pieces","source_pdf_page":93,"section":null,"position":9,"match_options":["long bean","green bean"],"match_rule":"any_of","role":"main","required_for_matching":true,"quantity_prefix_text":"2 cups","related_recipe_id":null},{"source_text":"1 radish, peeled and cut into 1/4-inch-thick diagonal slices (optional)","source_pdf_page":93,"section":null,"position":10,"match_options":["radish"],"match_rule":"single","role":"optional","required_for_matching":false,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"1 tablespoon salt","source_pdf_page":93,"section":null,"position":11,"match_options":["salt"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 tablespoon","related_recipe_id":null},{"source_text":"3 cayenne peppers or banana peppers","source_pdf_page":93,"section":null,"position":12,"match_options":["cayenne pepper","banana pepper"],"match_rule":"any_of","role":"main","required_for_matching":true,"quantity_prefix_text":"3","related_recipe_id":null},{"source_text":"2 cups spinach","source_pdf_page":93,"section":null,"position":13,"match_options":["spinach"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 cups","related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"In a large pot, bring the water, pork, and tamarind to a boil over medium-high heat. Cook until the meat is tender, about 30 minutes, skimming the foam and fat off the surface as it cooks."},{"step":2,"source_step":2,"section":null,"text":"Remove the tamarind pods and discard. Add the taro roots, tomatoes, and onion, and continue to cook for 3 minutes, or until the onions and tomatoes are softened."},{"step":3,"source_step":3,"section":null,"text":"Add the eggplant and cook for about 3 minutes, or until just fork-tender. Add okra, long beans, and radish, if using. Cook for about 3 more minutes, or until all the vegetables are fork-tender."},{"step":4,"source_step":4,"section":null,"text":"Add salt, peppers, and spinach and stir to combine. Taste, and adjust the seasoning before serving."}],"source_tips":["SUBSTITUTION TIP: Substitute 2 packs of Sinigang Sampalok, a packaged tamarind soup mix, if whole tamarind pods are unavailable. Follow package directions for mixing with water and add to the soup in step 2."],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[93],"printed_pages":[85]},"review_flags":[],"prep_minutes":15,"cook_minutes":40,"additional_time_text":null,"default_image":null,"slug":"tamarind-and-pork-sour-soup"},
{"id":48,"name":"Steamed Meat Loaf","filipino_name":"Embotido","category":"Meat","prep_time_text":"20 minutes","cook_time_text":"55 minutes","yield_type":"serves","yield_text":"4 to 6","ingredients":[{"source_text":"2 tablespoons canola oil","source_pdf_page":94,"section":null,"position":1,"match_options":["canola oil"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 tablespoons","related_recipe_id":null},{"source_text":"1 onion, finely minced","source_pdf_page":94,"section":null,"position":2,"match_options":["onion"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"1 tablespoon finely minced garlic","source_pdf_page":94,"section":null,"position":3,"match_options":["garlic"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 tablespoon","related_recipe_id":null},{"source_text":"1 pound ground pork","source_pdf_page":94,"section":null,"position":4,"match_options":["ground pork"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 pound","related_recipe_id":null},{"source_text":"1 pound ground chicken","source_pdf_page":94,"section":null,"position":5,"match_options":["ground chicken"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 pound","related_recipe_id":null},{"source_text":"1 cup finely minced carrot","source_pdf_page":94,"section":null,"position":6,"match_options":["carrot"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 cup","related_recipe_id":null},{"source_text":"1 cup bread crumbs","source_pdf_page":94,"section":null,"position":7,"match_options":["bread crumb"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 cup","related_recipe_id":null},{"source_text":"2 hot dogs, cut into 1/4-inch cubes","source_pdf_page":94,"section":null,"position":8,"match_options":["hot dog"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2","related_recipe_id":null},{"source_text":"1/2 cup green peas","source_pdf_page":94,"section":null,"position":9,"match_options":["green pea"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2 cup","related_recipe_id":null},{"source_text":"1/2 cup minced red bell pepper","source_pdf_page":94,"section":null,"position":10,"match_options":["red bell pepper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2 cup","related_recipe_id":null},{"source_text":"1/2 cup sugar","source_pdf_page":94,"section":null,"position":11,"match_options":["sugar"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2 cup","related_recipe_id":null},{"source_text":"2 large eggs, beaten","source_pdf_page":94,"section":null,"position":12,"match_options":["egg"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2","related_recipe_id":null},{"source_text":"1/4 cup raisins","source_pdf_page":94,"section":null,"position":13,"match_options":["raisin"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/4 cup","related_recipe_id":null},{"source_text":"2 tablespoons pickle relish","source_pdf_page":94,"section":null,"position":14,"match_options":["pickle relish"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 tablespoons","related_recipe_id":null},{"source_text":"1 tablespoon salt","source_pdf_page":94,"section":null,"position":15,"match_options":["salt"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 tablespoon","related_recipe_id":null},{"source_text":"1/4 teaspoon freshly ground black pepper","source_pdf_page":94,"section":null,"position":16,"match_options":["black pepper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/4 teaspoon","related_recipe_id":null},{"source_text":"4 hardboiled eggs, quartered","source_pdf_page":94,"section":null,"position":17,"match_options":["hardboiled egg"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"4","related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"In a large sauté pan or skillet, heat the oil over medium heat. Add the onion and garlic and sauté for 3 to 5 minutes, or until translucent and fragrant. Set aside to cool before mixing with the other ingredients."},{"step":2,"source_step":2,"section":null,"text":"In a large mixing bowl, combine the pork, chicken, carrot, bread crumbs, hot dogs, peas, bell pepper, sugar, eggs, raisins, relish, salt, and pepper. Stir in the cooled onion and garlic mixture."},{"step":3,"source_step":3,"section":null,"text":"Cut 2 (12-by-12-inch) pieces of aluminum foil and lay them on a flat surface."},{"step":4,"source_step":4,"section":null,"text":"Scoop 2 cups of the meat loaf mixture onto the center of one piece of foil. Spread to form a rectangular shape, and arrange half the egg quarters in the center. Use the foil to roll the meat into a tight log surrounding the eggs. Make sure the foil is wrapped tightly around the meat, then crimp both ends of the foil to secure. Repeat with remaining meat and eggs. Set aside."},{"step":5,"source_step":5,"section":null,"text":"Boil a few inches of water in a steamer pan over medium heat. Arrange the meat loaf in a steamer rack set over the water and cover. Steam for 45 minutes or until the meat is no longer pink and the juices run clear when pierced."},{"step":6,"source_step":6,"section":null,"text":"Remove from the heat and let the meat rest for 10 minutes. Remove the foil and cut into 1/2-inch-thick slices and arrange on a platter."}],"source_tips":["COOKING TIP: This meat loaf can be baked in a 350°F oven for 45 to 60 minutes. Set it on a roasting rack over a roasting pan of water."],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[94,95],"printed_pages":[86,87]},"review_flags":["Instructions mention water outside the ingredient list; source list retained. Review cooking/soaking water handling in the app."],"prep_minutes":20,"cook_minutes":55,"additional_time_text":null,"default_image":null,"slug":"steamed-meat-loaf"},
{"id":49,"name":"Pork Menudo","filipino_name":"Menudong Baboy","category":"Meat","prep_time_text":"20 minutes","cook_time_text":"45 minutes","yield_type":"serves","yield_text":"4 to 6","ingredients":[{"source_text":"1/4 cup canola oil","source_pdf_page":96,"section":null,"position":1,"match_options":["canola oil"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/4 cup","related_recipe_id":null},{"source_text":"3 cups finely chopped tomatoes","source_pdf_page":96,"section":null,"position":2,"match_options":["tomato"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3 cups","related_recipe_id":null},{"source_text":"1/2 onion, finely chopped","source_pdf_page":96,"section":null,"position":3,"match_options":["onion"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2","related_recipe_id":null},{"source_text":"2 garlic cloves, minced","source_pdf_page":96,"section":null,"position":4,"match_options":["garlic"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2","related_recipe_id":null},{"source_text":"2 pounds pork, cut into 1/2-inch cubes","source_pdf_page":96,"section":null,"position":5,"match_options":["pork"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 pounds","related_recipe_id":null},{"source_text":"1 cup beef or pork liver, cut into 1/2-inch cubes","source_pdf_page":96,"section":null,"position":6,"match_options":["beef liver","pork liver"],"match_rule":"any_of","role":"main","required_for_matching":true,"quantity_prefix_text":"1 cup","related_recipe_id":null},{"source_text":"1 bay leaf","source_pdf_page":96,"section":null,"position":7,"match_options":["bay leaf"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"4 cups tomato sauce","source_pdf_page":96,"section":null,"position":8,"match_options":["tomato sauce"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"4 cups","related_recipe_id":null},{"source_text":"3 thinly sliced hot dogs (about 1 cup) (see tip)","source_pdf_page":96,"section":null,"position":9,"match_options":["hot dog"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3","related_recipe_id":null},{"source_text":"1 cup peeled and finely chopped potatoes","source_pdf_page":96,"section":null,"position":10,"match_options":["potato"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 cup","related_recipe_id":null},{"source_text":"1/2 cup finely chopped carrots","source_pdf_page":96,"section":null,"position":11,"match_options":["carrot"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2 cup","related_recipe_id":null},{"source_text":"1/2 cup green peas","source_pdf_page":96,"section":null,"position":12,"match_options":["green pea"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2 cup","related_recipe_id":null},{"source_text":"1/2 red bell pepper, finely chopped","source_pdf_page":96,"section":null,"position":13,"match_options":["red bell pepper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2","related_recipe_id":null},{"source_text":"1/4 cup raisins","source_pdf_page":96,"section":null,"position":14,"match_options":["raisin"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/4 cup","related_recipe_id":null},{"source_text":"Salt","source_pdf_page":96,"section":null,"position":15,"match_options":["salt"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":null,"related_recipe_id":null},{"source_text":"Freshly ground black pepper","source_pdf_page":96,"section":null,"position":16,"match_options":["black pepper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":null,"related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"In a wok or large sauté pan, heat the oil over medium heat. Sauté the tomatoes, onions, and garlic for 3 to 5 minutes, or until the onions are translucent."},{"step":2,"source_step":2,"section":null,"text":"Add the pork and liver and stir well. Add enough cold water to cover the pork and add the bay leaf. Simmer for 30 minutes, skimming the foam off the surface as it cooks."},{"step":3,"source_step":3,"section":null,"text":"Add the tomato sauce, hot dogs, potatoes, carrots, peas, bell pepper, and raisins. Simmer for 5 minutes, until the potatoes are fork-tender."},{"step":4,"source_step":4,"section":null,"text":"Season with salt and pepper to taste. Continue to simmer for about 5 minutes, to reduce the liquid to the consistency of a stew."}],"source_tips":["INGREDIENT TIP: Make sure to check the packaging for your hot dogs to ensure they are gluten- and soy-free."],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[96],"printed_pages":[88]},"review_flags":["Instructions mention water outside the ingredient list; source list retained. Review cooking/soaking water handling in the app."],"prep_minutes":20,"cook_minutes":45,"additional_time_text":null,"default_image":null,"slug":"pork-menudo"},
{"id":50,"name":"Savory Pork Barbecue","filipino_name":"Inihaw Na Baboy","category":"Meat","prep_time_text":"15 minutes, plus 3 hours (or overnight) to marinate and 20 minutes to rest COOK TIME: 10 minutes","cook_time_text":null,"yield_type":"serves","yield_text":"10 to 12","ingredients":[{"source_text":"5 pounds pork shoulder, cut into 1/4-inch-thick slices","source_pdf_page":97,"section":null,"position":1,"match_options":["pork"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"5 pounds","related_recipe_id":null},{"source_text":"2 cups soy sauce","source_pdf_page":97,"section":null,"position":2,"match_options":["soy sauce"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 cups","related_recipe_id":null},{"source_text":"1 1/2 cups lemon-lime soda","source_pdf_page":97,"section":null,"position":3,"match_options":["lemon-lime soda"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 1/2 cups","related_recipe_id":null},{"source_text":"1/2 cup freshly squeezed calamansi juice or lemon juice","source_pdf_page":97,"section":null,"position":4,"match_options":["calamansi","lemon"],"match_rule":"any_of","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2 cup","quantity_note":"Display source_text to preserve compound quantities and/or alternative amounts; quantity_prefix_text is only the leading amount.","related_recipe_id":null},{"source_text":"1/2 cup minced garlic","source_pdf_page":97,"section":null,"position":5,"match_options":["garlic"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2 cup","related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"In a mixing bowl, combine the pork shoulder, soy sauce, soda, calamansi juice, and garlic. Cover the bowl, refrigerate, and marinate for at least 3 hours or as long as overnight."},{"step":2,"source_step":2,"section":null,"text":"When ready to cook, remove the pork from the refrigerator and let it sit for 20 minutes to come to room temperature."},{"step":3,"source_step":3,"section":null,"text":"Preheat the grill to medium-high. Thread the pork on wooden skewers."},{"step":4,"source_step":4,"section":null,"text":"Grill the pork for 3 to 5 minutes each side, turning a couple of times to ensure even cooking, until cooked through."}],"source_tips":["COOKING TIP: To make this in the oven, preheat the oven to 450°F. Cook for 25 minutes, turning once halfway through the cooking time."],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[97],"printed_pages":[89]},"review_flags":["Additional waiting time is retained as text; do not display prep + cook as total elapsed time."],"prep_minutes":15,"cook_minutes":null,"additional_time_text":"3 hours (or overnight) to marinate and 20 minutes to rest COOK TIME: 10 minutes","default_image":null,"slug":"savory-pork-barbecue"},
