xt":"1/4 cup finely chopped garlic","source_pdf_page":98,"section":"FOR THE PORK BARBECUE","position":13,"match_options":["garlic"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/4 cup","related_recipe_id":null},{"source_text":"1 teaspoon freshly ground black pepper","source_pdf_page":98,"section":"FOR THE PORK BARBECUE","position":14,"match_options":["black pepper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 teaspoon","related_recipe_id":null}],"instructions":[{"step":1,"source_step":null,"section":"TO MAKE THE BASTING SAUCE","text":"In a bowl, combine the ketchup, soy sauce, vinegar, calamansi juice, sugar, garlic powder, and pepper. Mix to dissolve the sugar. Refrigerate until ready to use."},{"step":2,"source_step":1,"section":"TO MAKE THE PORK BARBECUE","text":"In a glass bowl, combine the pork, sugar, soy sauce, calamansi juice, vinegar, garlic, and pepper. Toss to coat. Transfer to a shallow glass baking dish and cover with plastic wrap and refrigerate. Marinate for at least 3 hours or as long as overnight."},{"step":3,"source_step":2,"section":"TO MAKE THE PORK BARBECUE","text":"When ready to cook, remove the pork from refrigerator and let it sit at room temperature at least 20 minutes."},{"step":4,"source_step":3,"section":"TO MAKE THE PORK BARBECUE","text":"Preheat a grill to medium-high. Thread the pork onto the skewers."},{"step":5,"source_step":4,"section":"TO MAKE THE PORK BARBECUE","text":"Grill the pork skewers for 3 to 5 minutes on each side, flipping once, before basting with barbecue sauce."},{"step":6,"source_step":5,"section":"TO MAKE THE PORK BARBECUE","text":"Continue cooking for 7 to 10 minutes, flipping and basting the pork with the sauce, until the pork is cooked through and no longer pink."}],"source_tips":["COOKING TIP: To make this in the oven, preheat the oven to 450°F. Cook for 25 minutes, flipping once halfway through."],"source":{"title":"The 