{"id":52,"name":"Simple Pork Chops","filipino_name":null,"category":"Meat","prep_time_text":"5 minutes, plus 30 minutes (or overnight) to marinate","cook_time_text":"15 minutes","yield_type":"serves","yield_text":"4","ingredients":[{"source_text":"1 cup soy sauce","source_pdf_page":99,"section":null,"position":1,"match_options":["soy sauce"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 cup","related_recipe_id":null},{"source_text":"1 cup freshly squeezed calamansi juice or lemon juice","source_pdf_page":99,"section":null,"position":2,"match_options":["calamansi","lemon"],"match_rule":"any_of","role":"main","required_for_matching":true,"quantity_prefix_text":"1 cup","related_recipe_id":null},{"source_text":"3 garlic cloves, crushed","source_pdf_page":99,"section":null,"position":3,"match_options":["garlic"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3","related_recipe_id":null},{"source_text":"Pinch freshly ground black pepper","source_pdf_page":99,"section":null,"position":4,"match_options":["black pepper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"Pinch","related_recipe_id":null},{"source_text":"4 center-cut pork chops","source_pdf_page":99,"section":null,"position":5,"match_options":["pork"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"4","related_recipe_id":null},{"source_text":"1 1/2 cups canola oil","source_pdf_page":99,"section":null,"position":6,"match_options":["canola oil"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 1/2 cups","related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"In a large bowl, combine the soy sauce, calamansi juice, garlic, and pepper. Place the pork chops in the marinade for at least 30 minutes or as long as overnight for more flavor."},{"step":2,"source_step":2,"section":null,"text":"In a frying pan, heat the oil over medium heat. Arrange the pork chops in the pan and avoid overcrowding so that they brown properly. Discard the marinade."},{"step":3,"source_step":3,"section":null,"text":"Fry each side until the surface is brown and the juices run clear, 5 to 8 minutes per side, or until a food thermometer inserted into the thickest part of a chop reads 145°F."},{"step":4,"source_step":4,"section":null,"text":"Remove the pork chops from the heat and transfer to a paper-towel-lined plate to rest before serving."}],"source_tips":["SUBSTITUTION TIP: For a sweeter marinade, use orange juice instead of calamansi juice.","COOKING TIP: These pork chops are also great baked. For bone-in chops, cook for 25 minutes in a 450°F oven. For boneless chops, cook in a 400°F oven for 25 minutes."],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[99],"printed_pages":[91]},"review_flags":["Additional waiting time is retained as text; do not display prep + cook as total elapsed time."],"prep_minutes":5,"cook_minutes":15,"additional_time_text":"30 minutes (or overnight) to marinate","default_image":null,"slug":"simple-pork-chops"},
{"id":53,"name":"Braised Pork Shank With Banana Flower","filipino_name":"Paksiw Na Pata","category":"Meat","prep_time_text":"10 minutes","cook_time_text":"1 hour 45 minutes","yield_type":"serves","yield_text":"4 to 6","ingredients":[{"source_text":"3 tablespoons canola oil","source_pdf_page":100,"section":null,"position":1,"match_options":["canola oil"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3 tablespoons","related_recipe_id":null},{"source_text":"1 shallot, minced","source_pdf_page":100,"section":null,"position":2,"match_options":["shallot"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"5 garlic cloves, minced","source_pdf_page":100,"section":null,"position":3,"match_options":["garlic"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"5","related_recipe_id":null},{"source_text":"2 pounds pork shank, cut into 2-inch pieces","source_pdf_page":100,"section":null,"position":4,"match_options":["pork shank"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 pounds","related_recipe_id":null},{"source_text":"1 cup vinegar","source_pdf_page":100,"section":null,"position":5,"match_options":["vinegar"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 cup","related_recipe_id":null},{"source_text":"1 cup soy sauce","source_pdf_page":100,"section":null,"position":6,"match_options":["soy sauce"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 cup","related_recipe_id":null},{"source_text":"10 whole black peppercorns","source_pdf_page":100,"section":null,"position":7,"match_options":["black peppercorn"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"10","related_recipe_id":null},{"source_text":"3 bay leaves","source_pdf_page":100,"section":nu