pressure to naturally release and serve as directed above."],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[100],"printed_pages":[92]},"review_flags":[],"prep_minutes":10,"cook_minutes":105,"additional_time_text":null,"default_image":null,"slug":"braised-pork-shank-with-banana-flower"},
{"id":54,"name":"Adobo Pork And Chicken In Coconut Milk","filipino_name":"Ginataang Adobo Baboy At Manok","category":"Meat","prep_time_text":"15 minutes","cook_time_text":"30 minutes","yield_type":"serves","yield_text":"6 to 8","ingredients":[{"source_text":"2 pounds pork shoulder, cut into 1-inch pieces","source_pdf_page":101,"section":null,"position":1,"match_options":["pork"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 pounds","related_recipe_id":null},{"source_text":"2 pounds chicken wings, split","source_pdf_page":101,"section":null,"position":2,"match_options":["chicken"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 pounds","related_recipe_id":null},{"source_text":"4 cups water","source_pdf_page":101,"section":null,"position":3,"match_options":["water"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"4 cups","related_recipe_id":null},{"source_text":"1 cup white vinegar","source_pdf_page":101,"section":null,"position":4,"match_options":["white vinegar"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 cup","related_recipe_id":null},{"source_text":"3 tablespoons fish sauce","source_pdf_page":101,"section":null,"position":5,"match_options":["fish sauce"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3 tablespoons","related_recipe_id":null},{"source_text":"5 garlic cloves, crushed","source_pdf_page":101,"section":null,"position":6,"match_options":["garlic"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"5","related_recipe_id":null},{"source_text":"1 tablespoon salt","source_pdf_page":101,"section":null,"position":7,"match_options":["salt"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 tablespoon","related_recipe_id":null},{"source_text":"1/4 teaspoon freshly ground black pepper","source_pdf_page":101,"section":null,"position":8,"match_options":["black pepper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/4 teaspoon","related_recipe_id":null},{"source_text":"2 bay leaves","source_pdf_page":101,"section":null,"position":9,"match_options":["bay leaf"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2","related_recipe_id":null},{"source_text":"2 cups coconut milk","source_pdf_page":101,"section":null,"position":10,"match_options":["coconut milk"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 cups","related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"In the bottom of a large pot, arrange the pork and chicken and cover with the water, vinegar, fish sauce, garlic, salt, pepper, and bay leaves."},{"step":2,"source_step":2,"section":null,"text":"Cook over medium-high heat and boil for 10 minutes, skimming the foam off the surface as it cooks. Lower the heat to medium and simmer for 20 minutes, or until the pork and chicken are tender."},{"step":3,"source_step":3,"section":null,"text":"Stir in the coconut milk and continue to simmer for 10 minutes. Taste and adjust the seasoning as desired."}],"source_tips":["VARIATION TIP: If you prefer to serve with a dipping sauce, don’t add the fish sauce during the cooking process and instead use it for dipping alongside the rice."],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[101],"printed_pages":[93]},"review_flags":[],"prep_minutes":15,"cook_minutes":30,"additional_time_text":null,"default_image":null,"slug":"adobo-pork-and-chicken-in-coconut-milk"},
{"id":55,"name":"Spicy Shrimp-Paste Pork","filipino_name":"Bicol Express","category":"Meat","prep_time_text":"10 minutes","cook_time_text":"40 minutes","yield_type":"serves","yield_text":"4 to 6","ingredients":[{"source_text":"3 tablespoons canola oil","source_pdf_page":102,"section":null,"position":1,"match_options":["canola oil"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3 tablespoons","related_recipe_id":null},{"source_text":"1/2 cup finely chopped onions","source_pdf_page":102,"section":null,"position":2,"match_options":["onion"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2 cup","related_recipe_id":null},{"source_text":"5 garlic cloves, coarsely chopped","source_pdf_page":102,"section":null,"position":3,"match_options":["garlic"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"5","related_recipe_id":null},{"source_text":"2 pounds pork shoulder, cut into 1/2-inch cubes","source_pdf_page":102,"section":null,"position":4,"match_options":["pork"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 pounds","related_recipe_id":null},{"source_text":"3 tablespoons shrimp paste (see tip)","source_pdf_page":102,"section":null,"position":5,"match_options":["shrimp paste"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3 tablespoons","related_recipe_id":null},{"source_text":"4 cups coconut milk","source_pdf_page":102,"section":null,"position":6,"match_options":["coconut milk"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"4 cups","related_recipe_id":null},{"source_text":"2 tablespoons red pepper flakes","source_pdf_page":102,"section":null,"position":7,"match_options":["red pepper flake"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 tablespoons","related_recipe_id":null},{"source_text":"Pinch freshly ground black pepper","source_pdf_page":102,"section":null,"position":8,"match_options":["black pepper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"Pinch","related_recipe_id":null},{"source_text":"5 serrano peppers, sliced, for serving","source_pdf_page":102,"section":null,"position":9,"match_options":["serrano pepper"],"match_rule":"single","role":"serving","required_for_matching":false,"quantity_prefix_text":"5","related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"In a wok or large pot, heat the oil over medium-high heat and sauté the onions for about 3 minutes, or until translucent. Add the garlic and continue to sauté for about 30 seconds, or until fragrant."},{"step":2,"source_step":2,"section":null,"text":"Add the pork, stirring to combine, and cook until the meat turns white, about 5 minutes."},{"step":3,"source_step":3,"section":null,"text":"Add the shrimp paste and stir until all the meat is well coated. Add the coconut milk and simmer for 30 minutes, or until the meat is tender, skimming the foam off the surface as it cooks."},{"step":4,"source_step":4,"section":null,"text":"Add the red pepper flakes and cook for about 10 minutes to reduce to the consistency of a stew. Add the pepper and adjust seasoning to taste."},{"step":5,"source_step":5,"section":null,"text":"Serve on a platter topped with the serrano peppers."}],"source_tips":["INGREDIENT TIP: Shrimp paste is made from fermented shrimp and salt. Because of its high salt content, you rarely need to season a dish with additional salt when using it. Look for it in the Asian section of your supermarket or at an Asian specialty market."],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[102],"printed_pages":[94]},"review_flags":[],"prep_minutes":10,"cook_minutes":40,"additional_time_text":null,"default_image":null,"slug":"spicy-shrimp-paste-pork"},
{"id":56,"name":"Roasted Pork Stew","filipino_name":"Paksiw Na Lechon","category":"Meat","prep_time_text":"10 minutes","cook_time_text":"35 minutes","yield_type":"serves","yield_text":"4 to 6","ingredients":[{"source_text":"3 tablespoons canola oil","source_pdf_page":103,"section":null,"position":1,"match_options":["canola oil"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3 tablespoons","related_recipe_id":null},{"source_text":"1 onion, minced","source_pdf_page":103,"section":null,"position":2,"match_options":["onion"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"5 garlic cloves, crushed","source_pdf_page":103,"section":null,"position":3,"match_options":["garlic"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"5","related_recipe_id":null},{"source_text":"2 pounds chopped roasted pork, such as Roasted Pork Belly (page 98) or Crispy Pork Belly with Sweet Vinegar Dipping Sauce (page 14)","source_pdf_page":103,"section":null,"position":4,"match_options":["roasted pork"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 pounds","related_recipe_id":58},{"source_text":"4 cups beef stock","source_pdf_page":103,"section":null,"position":5,"match_options":["beef stock"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"4 cups","related_recipe_id":null},{"source_text":"1 cup sugar","source_pdf_page":103,"section":null,"position":6,"match_options":["sugar"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 cup","related_recipe_id":null},{"source_text":"1 cup vinegar","source_pdf_page":103,"section":null,"position":7,"match_options":["vinegar"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 cup","related_recipe_id":null},{"source_text":"1 cup liver pâté (optional)","source_pdf_page":103,"section":null,"position":8,"match_options":["liver pate"],"match_rule":"single","role":"optional","required_for_matching":false,"quantity_prefix_text":"1 cup","related_recipe_id":null},{"source_text":"1 teaspoon whole peppercorns","source_pdf_page":103,"section":null,"position":9,"match_options":["black peppercorn"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 teaspoon","related_recipe_id":null},{"source_text":"3 bay leaves","source_pdf_page":103,"section":null,"position":10,"match_options":["bay leaf"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3","related_recipe_id":null},{"source_text":"1 cup bread crumbs","source_pdf_page":103,"section":null,"position":11,"match_options":["bread crumb"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 cup","related_recipe_id":null},{"source_text":"1 tablespoon salt","source_pdf_page":103,"section":null,"position":12,"match_options":["salt"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 tablespoon","related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"In a large pot, heat the oil over medium heat and sauté the onion and garlic for 3 to 5 minutes, or until translucent and fragrant."},{"step":2,"source_step":2,"section":null,"text":"Stir in the pork, beef stock, sugar, vinegar, liver pâté (if using), peppercorns, and bay leaves. Reduce the heat to medium-low and simmer for about 30 minutes, or until the liquid has reduced to the consistency of a stew. Stir in the bread crumbs and salt."},{"step":3,"source_step":3,"section":null,"text":"Transfer to a large bowl and serve family style."}],"source_tips":[],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[103],"printed_pages":[95]},"review_flags":[],"prep_minutes":10,"cook_minutes":35,"additional_time_text":null,"default_image":null,"slug":"roasted-pork-stew"},
{"id":57,"name":"Pork Afritada","filipino_name":"Afritadang Baboy","category":"Meat","prep_time_text":"15 minutes","cook_time_text":"50 minutes","yield_type":"serves","yield_text":"4 to 6","ingredients":[{"source_text":"3 tablespoons canola oil","source_pdf_page":104,"section":null,"position":1,"match_options":["canola oil"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3 tablespoons","related_recipe_id":null},{"source_text":"1 onion, diced","source_pdf_page":104,"section":null,"position":2,"match_options":["onion"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"3 garlic cloves, minced","source_pdf_page":104,"section":null,"position":3,"match_options":["garlic"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3","related_recipe_id":null},{"source_text":"1 tomato, diced","source_pdf_page":104,"section":null,"position":4,"match_options":["tomato"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"2 bay leaves","source_pdf_page":104,"section":null,"position":5,"match_options":["bay leaf"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2","related_recipe_id":null},{"source_text":"2 pounds pork shoulder, cut into 1-inch cubes","source_pdf_page":104,"section":null,"position":6,"match_options":["pork"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 pounds","related_recipe_id":null},{"source_text":"2 cups tomato sauce","source_pdf_page":104,"section":null,"position":7,"match_options":["tomato sauce"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 cups","related_recipe_id":null},{"source_text":"1 medium potato, cut into 1-inch cubes","source_pdf_page":104,"section":null,"position":8,"match_options":["potato"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"1 medium carrot, cut into 1-inch cubes","source_pdf_page":104,"section":null,"position":9,"match_options":["carrot"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"1/2 red bell pepper, cut into 1-inch pieces","source_pdf_page":104,"section":null,"position":10,"match_options":["red bell pepper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2","related_recipe_id":null},{"source_text":"Salt","source_pdf_page":104,"section":null,"position":11,"match_options":["salt"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":null,"related_recipe_id":null},{"source_text":"Freshly ground black pepper","source_pdf_page":104,"section":null,"position":12,"match_options":["black pepper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":null,"related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"In a medium pot, heat the oil over medium heat. Add the onion and garlic and sauté for 3 to 5 minutes, or until translucent and fragrant."},{"step":2,"source_step":2,"section":null,"text":"Stir in the tomato and bay leaves and sauté until the tomato is just soft."},{"step":3,"source_step":3,"section":null,"text":"Add the pork and cook for 5 to 6 minutes, stirring regularly, until browned on all sides."},{"step":4,"source_step":4,"section":null,"text":"Add enough water to just cover the pork. Reduce the heat to medium-low and simmer for 30 minutes, or until the pork is tender, skimming the foam off the surface as it cooks."},{"step":5,"source_step":5,"section":null,"text":"Add the tomato sauce, potato, and carrot and cook for 7 to 8 minutes. Stir in the bell pepper and season with salt and pepper."},{"step":6,"source_step":6,"section":null,"text":"Simmer until the liquid has reduced to the consistency of a thick stew. Taste and adjust the seasoning as desired before serving."}],"source_tips":["COOKING TIP: To cook this in an electric pressure cooker, use the sauté function to complete steps 1 through 3. Close the lid and cook on high pressure for 25 minutes. Quick release the pressure, then adjust the cooker to sauté and complete the recipe as it is written."],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[104,105],"printed_pages":[96,97]},"review_flags":["Instructions mention water outside the ingredient list; source list retained. Review cooking/soaking water handling in the app."],"prep_minutes":15,"cook_minutes":50,"additional_time_text":null,"default_image":null,"slug":"pork-afritada"},
{"id":58,"name":"Roasted Pork Belly","filipino_name":"Lechon Liempo","category":"Meat","prep_time_text":"30 minutes","cook_time_text":"5 hours","yield_type":"serves","yield_text":"20","ingredients":[{"source_text":"2 tablespoons salt","source_pdf_page":106,"section":null,"position":1,"match_options":["salt"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 tablespoons","related_recipe_id":null},{"source_text":"1 (10-pound) whole skin-on pork belly","source_pdf_page":106,"section":null,"position":2,"match_options":["pork"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 (10-pound)","related_recipe_id":null},{"source_text":"2 tablespoons garlic powder","source_pdf_page":106,"section":null,"position":3,"match_options":["garlic powder"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 tablespoons","related_recipe_id":null},{"source_text":"1 tablespoon freshly ground black pepper","source_pdf_page":106,"section":null,"position":4,"match_options":["black pepper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 tablespoon","related_recipe_id":null},{"source_text":"5 bay leaves","source_pdf_page":106,"section":null,"position":5,"match_options":["bay leaf"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"5","related_recipe_id":null},{"source_text":"6 scallions, root ends cut off","source_pdf_page":106,"section":null,"position":6,"match_options":["scallion"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"6","related_recipe_id":null},{"source_text":"1 bunch fresh rosemary","source_pdf_page":106,"section":null,"position":7,"match_options":["rosemary"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 bunch","related_recipe_id":null},{"source_text":"2 lemongrass stalks, trimmed and outer layers removed","source_pdf_page":106,"section":null,"position":8,"match_options":["lemongrass"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2","related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"Preheat the oven to 350°F. Cut several pieces of kitchen twine 4 inches longer than the width of the pork belly."},{"step":2,"source_step":2,"section":null,"text":"Rub the salt on the skin and the meat of the pork belly. Place the pork skin-side down on a cutting board. Then sprinkle the garlic powder and pepper over the pork and massage them into the meat."},{"step":3,"source_step":3,"section":null,"text":"In the center of the pork belly, lay the bay leaves, scallions, rosemary, and lemongrass horizontally."},{"step":4,"source_step":4,"section":null,"text":"Slide the pieces of twine under the pork skin horizontally at 1-inch intervals so that 2 inches of twine extend past the edge of the pork on either side."},{"step":5,"source_step":5,"section":null,"text":"Roll the left and right sides of the pork belly toward the middle so that the pork belly surrounds the herbs, the sides overlap slightly, and the skin is facing out."},{"step":6,"source_step":6,"section":null,"text":"Wrap each piece of twine around the pork roll and knot it tight enough to hold the pork roll together, but not too tight, as the skin will expand a bit during cooking. Cut off any loose ends of twine."},{"step":7,"source_step":7,"section":null,"text":"In a large roasting pan, place a raised roasting rack. Place the pork seam-side down on the rack and cook for about 5 hours, or until the pork is browned and cooked to an internal temperature of 145°F."},{"step":8,"source_step":8,"section":null,"text":"Remove the twine and herbs. Slice and serve."}],"source_tips":["SUBSTITUTION TIP: If lemongrass is not available, you can use thyme, leeks, or onions in its place.","COOKING TIP: For a crispier skin, turn the heat up to 450°F for the last 30 minutes of the cooking time."],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[106,107],"printed_pages":[98,99]},"review_flags":[],"prep_minutes":30,"cook_minutes":300,"additional_time_text":null,"default_image":null,"slug":"roasted-pork-belly"},
{"id":59,"name":"Beef Tapa","filipino_name":null,"category":"Meat","prep_time_text":"10 minutes, plus 1 hour (or overnight) to marinate and 20 minutes to rest COOK TIME: 20 minutes","cook_time_text":null,"yield_type":"serves","yield_text":"4 to 6","ingredients":[{"source_text":"2 pounds beef sirloin, thinly sliced against the grain (see tip)","source_pdf_page":108,"section":null,"position":1,"match_options":["beef"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 pounds","related_recipe_id":null},{"source_text":"1 cup freshly squeezed calamansi juice or lemon juice","source_pdf_page":108,"section":null,"position":2,"match_options":["calamansi","lemon"],"match_rule":"any_of","role":"main","required_for_matching":true,"quantity_prefix_text":"1 cup","related_recipe_id":null},{"source_text":"1/4 cup brown sugar","source_pdf_page":108,"section":null,"position":3,"match_options":["brown sugar"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/4 cup","related_recipe_id":null},{"source_text":"1/4 cup salt","source_pdf_page":108,"section":null,"position":4,"match_options":["salt"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/4 cup","related_recipe_id":null},{"source_text":"1 tablespoon finely chopped garlic","source_pdf_page":108,"section":null,"position":5,"match_options":["garlic"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 tablespoon","related_recipe_id":null},{"source_text":"1/4 teaspoon freshly ground black pepper","source_pdf_page":108,"section":null,"position":6,"match_options":["black pepper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/4 teaspoon","related_recipe_id":null},{"source_text":"1/4 cup vegetable oil","source_pdf_page":108,"section":null,"position":7,"match_options":["vegetable oil"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/4 cup","related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"In a large bowl, combine the beef sirloin, calamansi juice, brown sugar, salt, garlic, and pepper. Cover, refrigerate, and marinate for 1 hour or as long as overnight."},{"step":2,"source_step":2,"section":null,"text":"Remove the meat from the refrigerator and let it sit at room temperature for about 20 minutes prior to cooking."},{"step":3,"source_step":3,"section":null,"text":"In a large sauté pan or skillet, heat the oil over high heat and, using tongs, lay the beef in a single layer, working in batches to prevent overcrowding. Cook the pieces for about 2 minutes on each side, flipping once, until dark brown but not burned."},{"step":4,"source_step":4,"section":null,"text":"Once browned, transfer the pieces to a paper-towel-lined plate to drain and repeat with remaining beef."},{"step":5,"source_step":5,"section":null,"text":"Taste and adjust the seasoning as desired before serving."}],"source_tips":["INGREDIENT TIP: Have a butcher slice the beef thinly for you or place the sirloin in the freezer for about 30 minutes before slicing to firm it up and make it easier to slice."],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[108],"printed_pages":[100]},"review_flags":["Additional waiting time is retained as text; do not display prep + cook as total elapsed time."],"prep_minutes":10,"cook_minutes":null,"additional_time_text":"1 hour (or overnight) to marinate and 20 minutes to rest COOK TIME: 20 minutes","default_image":null,"slug":"beef-tapa"},
{"id":60,"name":"Hearty Vegetable And Beef Soup","filipino_name":"Baka Nilaga","category":"Meat","prep_time_text":"15 minutes","cook_time_text":"2 hours 10 minutes","yield_type":"serves","yield_text":"4 to 6","ingredients":[{"source_text":"2 pounds beef shank with marrow, cut into 2-inch pieces","source_pdf_page":109,"section":null,"position":1,"match_options":["beef shank"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 pounds","related_recipe_id":null},{"source_text":"2 celery stalks, cut into 2-inch pieces","source_pdf_page":109,"section":null,"position":2,"match_options":["celery"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2","related_recipe_id":null},{"source_text":"1 teaspoon whole black peppercorns","source_pdf_page":109,"section":null,"position":3,"match_options":["black peppercorn"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 teaspoon","related_recipe_id":null},{"source_text":"2 Yukon Gold potatoes, quartered","source_pdf_page":109,"section":null,"position":4,"match_options":["potato"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2","related_recipe_id":null},{"source_text":"2 medium carrots, peeled and cut into 2-inch pieces","source_pdf_page":109,"section":null,"position":5,"match_options":["carrot"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2","related_recipe_id":null},{"source_text":"1 onion, quartered","source_pdf_page":109,"section":null,"position":6,"match_options":["onion"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"1 small cabbage, cored and cut into 8 wedges","source_pdf_page":109,"section":null,"position":7,"match_options":["cabbage"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"4 baby bok choy, cut in half lengthwise (see Prep Tip)","source_pdf_page":109,"section":null,"position":8,"match_options":["bok choy"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"4","related_recipe_id":null},{"source_text":"1 cup green beans, trimmed","source_pdf_page":109,"section":null,"position":9,"match_options":["green bean"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 cup","related_recipe_id":null},{"source_text":"Salt","source_pdf_page":109,"section":null,"position":10,"match_options":["salt"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":null,"related_recipe_id":null},{"source_text":"1 calamansi or lemon, cut into wedges, for serving","source_pdf_page":109,"section":null,"position":11,"match_options":["calamansi","lemon"],"match_rule":"any_of","role":"serving","required_for_matching":false,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"Fish sauce, for serving","source_pdf_page":109,"section":null,"position":12,"match_options":["fish sauce"],"match_rule":"single","role":"serving","required_for_matching":false,"quantity_prefix_text":null,"related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"In a large pot, combine the beef shank, celery, and pepper corns and cover with cold water by a few inches. Bring to a boil over high heat, skimming the foam off the surface as it cooks."},{"step":2,"source_step":2,"section":null,"text":"Lower the heat and simmer for 2 hours, regularly skimming off foam and excess fat, until the meat becomes tender."},{"step":3,"source_step":3,"section":null,"text":"Add the potatoes, carrots, and onion, and cook until potatoes and carrots are soft but not mushy, about 5 minutes."},{"step":4,"source_step":4,"section":null,"text":"Add the cabbage, bok choy, and green beans and cook for about 3 minutes. Season with salt. Serve with the calamansi wedges and fish sauce."}],"source_tips":["PREP TIP: To clean bok choy, soak in a bowl of water to dislodge any particles and drain before using.","COOKING TIP: To use an electric pressure cooker for this recipe, follow step 1 and cook on high pressure for 35 minutes. Allow the pressure to release naturally, open the lid, adjust the pressure cooker to sauté, and continue with step 3."],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[109],"printed_pages":[101]},"review_flags":["Instructions mention water outside the ingredient list; source list retained. Review cooking/soaking water handling in the app."],"prep_minutes":15,"cook_minutes":130,"additional_time_text":null,"default_image":null,"slug":"hearty-vegetable-and-beef-soup"},
{"id":61,"name":"Ground Beef Omelet","filipino_name":"Tortang Itlog At Giniling","category":"Meat","prep_time_text":"10 minutes","cook_time_text":"25 minutes","yield_type":"serves","yield_text":"2 to 4","ingredients":[{"source_text":"2 tablespoons canola oil","source_pdf_page":110,"section":null,"position":1,"match_options":["canola oil"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 tablespoons","related_recipe_id":null},{"source_text":"1/2 cup finely diced potatoes","source_pdf_page":110,"section":null,"position":2,"match_options":["potato"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2 cup","related_recipe_id":null},{"source_text":"1 shallot, minced","source_pdf_page":110,"section":null,"position":3,"match_options":["shallot"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"2 garlic cloves, minced","source_pdf_page":110,"section":null,"position":4,"match_options":["garlic"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2","related_recipe_id":null},{"source_text":"8 ounces ground beef or pork","source_pdf_page":110,"section":null,"position":5,"match_options":["ground beef","ground pork"],"match_rule":"any_of","role":"main","required_for_matching":true,"quantity_prefix_text":"8 ounces","related_recipe_id":null},{"source_text":"6 large eggs, beaten","source_pdf_page":110,"section":null,"position":6,"match_options":["egg"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"6","related_recipe_id":null},{"source_text":"6 tablespoons water","source_pdf_page":110,"section":null,"position":7,"match_options":["water"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"6 tablespoons","related_recipe_id":null},{"source_text":"1 teaspoon salt","source_pdf_page":110,"section":null,"position":8,"match_options":["salt"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 teaspoon","related_recipe_id":null},{"source_text":"1/4 teaspoon freshly ground black pepper","source_pdf_page":110,"section":null,"position":9,"match_options":["black pepper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/4 teaspoon","related_recipe_id":null},{"source_text":"3 tablespoons butter, plus more as needed","source_pdf_page":110,"section":null,"position":10,"match_options":["butter"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3 tablespoons","quantity_note":"Display source_text to preserve compound quantities and/or alternative amounts; quantity_prefix_text is only the leading amount.","related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"In a large sauté pan or skillet, heat the oil over medium heat. Cook the potatoes for 2 to 3 minutes, or until softened, then transfer to a small bowl."},{"step":2,"source_step":2,"section":null,"text":"In the same pan, sauté the shallot and garlic for 3 to 5 minutes, or until translucent and fragrant. Stir in the ground beef and sauté for 5 to 6 minutes, or until lightly browned. Transfer to a separate small bowl and cool to room temperature."},{"step":3,"source_step":3,"section":null,"text":"In a large bowl, combine the eggs and water and beat lightly. Mix in the cooked potatoes and ground meat. Season with salt and pepper."},{"step":4,"source_step":4,"section":null,"text":"Wipe the pan clean with paper towels. Heat the butter in the pan over medium heat. Scoop 1 cup of the mixture into the pan. Cook for 3 to 4 minutes. Using a wide spatula, loosen the edges before flipping."},{"step":5,"source_step":5,"section":null,"text":"Turn over the omelet and cook until it is slightly firm, another 3 to 4 minutes. Repeat with remaining batter, adding more butter as needed when frying."}],"source_tips":["VARIATION TIP: If you wish to include vegetables, tomatoes, broccoli, spinach, mushrooms, and green peas are my favorites."],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[110],"printed_pages":[102]},"review_flags":[],"prep_minutes":10,"cook_minutes":25,"additional_time_text":null,"default_image":null,"slug":"ground-beef-omelet"},
{"id":62,"name":"Steak And Onions","filipino_name":"Bistek Tagalog","category":"Meat","prep_time_text":"15 minutes, plus 30 minutes (or overnight) to marinate and 20 minutes to rest COOK TIME: 20 minutes","cook_time_text":null,"yield_type":"serves","yield_text":"4 to 6","ingredients":[{"source_text":"2 pounds beef tenderloin, thinly sliced into 2-inch strips","source_pdf_page":111,"section":null,"position":1,"match_options":["beef"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 pounds","related_recipe_id":null},{"source_text":"1 cup freshly squeezed calamansi juice or lemon juice","source_pdf_page":111,"section":null,"position":2,"match_options":["calamansi","lemon"],"match_rule":"any_of","role":"main","required_for_matching":true,"quantity_prefix_text":"1 cup","related_recipe_id":null},{"source_text":"1/2 cup soy sauce","source_pdf_page":111,"section":null,"position":3,"match_options":["soy sauce"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2 cup","related_recipe_id":null},{"source_text":"1/2 cup oyster sauce","source_pdf_page":111,"section":null,"position":4,"match_options":["oyster sauce"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2 cup","related_recipe_id":null},{"source_text":"Pinch fresh ground black pepper","source_pdf_page":111,"section":null,"position":5,"match_options":["black pepper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"Pinch","related_recipe_id":null},{"source_text":"5 tablespoons canola or vegetable oil","source_pdf_page":111,"section":null,"position":6,"match_options":["canola oil","vegetable oil"],"match_rule":"any_of","role":"main","required_for_matching":true,"quantity_prefix_text":"5 tablespoons","related_recipe_id":null},{"source_text":"1 onion, thinly sliced","source_pdf_page":111,"section":null,"position":7,"match_options":["onion"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"In a medium bowl, combine the beef, calamansi juice, soy sauce, oyster sauce, and pepper. Cover with plastic wrap and marinate 30 minutes or as long as overnight in the refrigerator."},{"step":2,"source_step":2,"section":null,"text":"Remove the meat from the refrigerator and let it sit at room temperature for about 20 minutes prior to cooking."},{"step":3,"source_step":3,"section":null,"text":"In a wok or large sauté pan, heat the canola oil over medium-high heat. Pour in the beef and the marinade, stirring regularly, and cook for 10 to 15 minutes, being careful not to overcook, until the beef is no longer pink."},{"step":4,"source_step":4,"section":null,"text":"Using a slotted spoon, transfer the beef to a serving plate and set aside, leaving the sauce in the pan."},{"step":5,"source_step":5,"section":null,"text":"Add the onion to the pan and cook over high heat for about 15 minutes, constantly stirring, until the sauce thickens and the onions are caramelized. Taste and adjust the seasoning as desired."},{"step":6,"source_step":6,"section":null,"text":"Arrange the onions on top of the beef and top with the sauce. Serve this dish family style while it is still hot."}],"source_tips":["PREP TIP: Sirloin or skirt steak work as substitutes for the tenderloin. Cut the beef against the grain to ensure it’s tender."],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[111],"printed_pages":[103]},"review_flags":["Additional waiting time is retained as text; do not display prep + cook as total elapsed time."],"prep_minutes":15,"cook_minutes":null,"additional_time_text":"30 minutes (or overnight) to marinate and 20 minutes to rest COOK TIME: 20 minutes","default_image":null,"slug":"steak-and-onions"},
{"id":63,"name":"Breaded Beefsteak","filipino_name":"Piniritong Baka","category":"Meat","prep_time_text":"10 minutes, plus 30 minutes to marinate","cook_time_text":"20 minutes","yield_type":"serves","yield_text":"4","ingredients":[{"source_text":"1 pound beef tenderloin, sliced thin and pounded","source_pdf_page":112,"section":null,"position":1,"match_options":["beef"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 pound","related_recipe_id":null},{"source_text":"Salt","source_pdf_page":112,"section":null,"position":2,"match_options":["salt"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":null,"related_recipe_id":null},{"source_text":"Freshly ground black pepper","source_pdf_page":112,"section":null,"position":3,"match_options":["black pepper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":null,"related_recipe_id":null},{"source_text":"1/2 cup calamansi juice or lemon juice","source_pdf_page":112,"section":null,"position":4,"match_options":["calamansi","lemon"],"match_rule":"any_of","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2 cup","quantity_note":"Display source_text to preserve compound quantities and/or alternative amounts; quantity_prefix_text is only the leading amount.","related_recipe_id":null},{"source_text":"1/4 cup butter","source_pdf_page":112,"section":null,"position":5,"match_options":["butter"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/4 cup","related_recipe_id":null},{"source_text":"1 1/4 cups all-purpose flour, divided","source_pdf_page":112,"section":null,"position":6,"match_options":["flour"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 1/4 cups","related_recipe_id":null},{"source_text":"1 1/2 cups beef stock","source_pdf_page":112,"section":null,"position":7,"match_options":["beef stock"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 1/2 cups","related_recipe_id":null},{"source_text":"1 cup sliced button mushrooms","source_pdf_page":112,"section":null,"position":8,"match_options":["button mushroom"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 cup","related_recipe_id":null},{"source_text":"2 large eggs","source_pdf_page":112,"section":null,"position":9,"match_options":["egg"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2","related_recipe_id":null},{"source_text":"1 cup bread crumbs","source_pdf_page":112,"section":null,"position":10,"match_options":["bread crumb"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 cup","related_recipe_id":null},{"source_text":"1 cup canola oil","source_pdf_page":112,"section":null,"position":11,"match_options":["canola oil"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 cup","related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"In a baking pan, season the beef with salt and pepper, then add the calamansi juice and marinate for 30 minutes."},{"step":2,"source_step":2,"section":null,"text":"In a small saucepan, heat the butter over medium heat until melted. Whisk in 1/4 cup flour and cook until well incorporated and lightly brown in color, about 2 minutes. Stir in the beef stock and continue to whisk until there are no lumps."},{"step":3,"source_step":3,"section":null,"text":"Add the mushrooms and season with salt and pepper. Turn the heat to low and simmer for 3 minutes, or until thickened. Set aside."},{"step":4,"source_step":4,"section":null,"text":"Take out three medium bowls. Place the remaining 1 cup flour in one bowl, beat the eggs in the next bowl, and place the bread crumbs in the last bowl. Remove the meat from the marinade and roll it in the flour, dip it in the egg, roll it in the bread crumbs, and place it on a plate. Repeat until all the meat is breaded."},{"step":5,"source_step":5,"section":null,"text":"In a large sauté pan or skillet, heat the oil over medium heat. Working in batches, fry the beef for 1 to 2 minutes on each side, until lightly browned."},{"step":6,"source_step":6,"section":null,"text":"Serve topped with the mushroom sauce."}],"source_tips":[],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[112],"printed_pages":[104]},"review_flags":["Additional waiting time is retained as text; do not display prep + cook as total elapsed time."],"prep_minutes":10,"cook_minutes":20,"additional_time_text":"30 minutes to marinate","default_image":null,"slug":"breaded-beefsteak"},
{"id":64,"name":"Beef Picadillo","filipino_name":"Giniling Na Baka","category":"Meat","prep_time_text":"15 minutes","cook_time_text":"35 minutes","yield_type":"serves","yield_text":"4","ingredients":[{"source_text":"3 tablespoons canola oil","source_pdf_page":113,"section":null,"position":1,"match_options":["canola oil"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3 tablespoons","related_recipe_id":null},{"source_text":"1 shallot, minced","source_pdf_page":113,"section":null,"position":2,"match_options":["shallot"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"3 garlic cloves, minced","source_pdf_page":113,"section":null,"position":3,"match_options":["garlic"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3","related_recipe_id":null},{"source_text":"1 tomato, cut into 1/2-inch cubes","source_pdf_page":113,"section":null,"position":4,"match_options":["tomato"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"1 pound ground beef","source_pdf_page":113,"section":null,"position":5,"match_options":["ground beef"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 pound","related_recipe_id":null},{"source_text":"1 1/2 cups beef stock or broth","source_pdf_page":113,"section":null,"position":6,"match_options":["beef stock"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 1/2 cups","quantity_note":"Display source_text to preserve compound quantities and/or alternative amounts; quantity_prefix_text is only the leading amount.","related_recipe_id":null},{"source_text":"2 cups tomato sauce","source_pdf_page":113,"section":null,"position":7,"match_options":["tomato sauce"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 cups","related_recipe_id":null},{"source_text":"1 medium potato, cut into 1/2-inch cubes","source_pdf_page":113,"section":null,"position":8,"match_options":["potato"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"1 medium carrot, cut into 1/2-inch cubes","source_pdf_page":113,"section":null,"position":9,"match_options":["carrot"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"1/2 cup green peas","source_pdf_page":113,"section":null,"position":10,"match_options":["green pea"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2 cup","related_recipe_id":null},{"source_text":"1/2 cup raisins","source_pdf_page":113,"section":null,"position":11,"match_options":["raisin"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2 cup","related_recipe_id":null},{"source_text":"Salt","source_pdf_page":113,"section":null,"position":12,"match_options":["salt"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":null,"related_recipe_id":null},{"source_text":"Freshly ground black pepper","source_pdf_page":113,"section":null,"position":13,"match_options":["black pepper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":null,"related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"In a large sauté pan or skillet, heat the oil over medium heat. Add the shallot and garlic and sauté for 3 to 5 minutes, or until translucent and fragrant."},{"step":2,"source_step":2,"section":null,"text":"Stir in the tomato and sauté for about 2 minutes, until just soft."},{"step":3,"source_step":3,"section":null,"text":"Crumble in the ground beef and continue to break it up while sautéing. Cook for about 2 minutes, or until just browned."},{"step":4,"source_step":4,"section":null,"text":"Pour in the beef stock and continue to cook until the meat is cooked through, about 4 to 5 minutes."},{"step":5,"source_step":5,"section":null,"text":"Add the tomato sauce, potato, carrot, green peas, and raisins. Reduce the heat to medium-low and simmer for 6 to 8 minutes, or until the vegetables are fork-tender."},{"step":6,"source_step":6,"section":null,"text":"Season with salt and pepper. Cook for 10 to 15 minutes, until the liquid is reduced to the consistency of pasta sauce."}],"source_tips":[],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[113],"printed_pages":[105]},"review_flags":[],"prep_minutes":15,"cook_minutes":35,"additional_time_text":null,"default_image":null,"slug":"beef-picadillo"},
{"id":65,"name":"Pochero Beef","filipino_name":"Pocherong Baka","category":"Meat","prep_time_text":"20 minutes","cook_time_text":"1 hour 20 minutes","yield_type":"serves","yield_text":"4 to 6","ingredients":[{"source_text":"5 tablespoons canola oil","source_pdf_page":114,"section":null,"position":1,"match_options":["canola oil"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"5 tablespoons","related_recipe_id":null},{"source_text":"1 chorizo sausage, cut into 1/4-inch rounds","source_pdf_page":114,"section":null,"position":2,"match_options":["chorizo"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"2 tomatoes, finely chopped","source_pdf_page":114,"section":null,"position":3,"match_options":["tomato"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2","related_recipe_id":null},{"source_text":"1 cup finely chopped onion","source_pdf_page":114,"section":null,"position":4,"match_options":["onion"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 cup","related_recipe_id":null},{"source_text":"3 garlic cloves, minced","source_pdf_page":114,"section":null,"position":5,"match_options":["garlic"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3","related_recipe_id":null},{"source_text":"2 pounds beef chuck, cut into 1 1/2-inch cubes","source_pdf_page":114,"section":null,"position":6,"match_options":["beef"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 pounds","related_recipe_id":null},{"source_text":"1 bay leaf","source_pdf_page":114,"section":null,"position":7,"match_options":["bay leaf"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"1 sweet potato, cut into 2-inch cubes","source_pdf_page":114,"section":null,"position":8,"match_options":["sweet potato"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"1 carrot, peeled and cut into 2-inch pieces","source_pdf_page":114,"section":null,"position":9,"match_options":["carrot"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"4 saba bananas or 2 plantains, peeled and halved","source_pdf_page":114,"section":null,"position":10,"match_options":["saba banana","plantain"],"match_rule":"any_of","role":"main","required_for_matching":true,"quantity_prefix_text":"4","quantity_note":"Display source_text to preserve compound quantities and/or alternative amounts; quantity_prefix_text is only the leading amount.","related_recipe_id":null},{"source_text":"1 small cabbage, cut into 8 wedges","source_pdf_page":114,"section":null,"position":11,"match_options":["cabbage"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"2 cups tomato sauce","source_pdf_page":114,"section":null,"position":12,"match_options":["tomato sauce"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 cups","related_recipe_id":null},{"source_text":"1/2 cup cooked chickpeas","source_pdf_page":114,"section":null,"position":13,"match_options":["chickpea"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2 cup","related_recipe_id":null},{"source_text":"1 tablespoon sugar (optional)","source_pdf_page":114,"section":null,"position":14,"match_options":["sugar"],"match_rule":"single","role":"optional","required_for_matching":false,"quantity_prefix_text":"1 tablespoon","related_recipe_id":null},{"source_text":"Salt","source_pdf_page":114,"section":null,"position":15,"match_options":["salt"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":null,"related_recipe_id":null},{"source_text":"Freshly ground black pepper","source_pdf_page":114,"section":null,"position":16,"match_options":["black pepper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":null,"related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"In a wok or large sauté pan, heat the oil over medium-high heat and sauté the chorizo, tomatoes, onion, and garlic for about 1 minute."},{"step":2,"source_step":2,"section":null,"text":"Add the beef and stir until well coated. Cover with cold water by several inches. Add the bay leaf and bring the stew to a boil over high heat."},{"step":3,"source_step":3,"section":null,"text":"Once the liquid reaches a boil, turn the heat to medium-low and simmer for 1 hour. Skim the foam off the surface as it cooks."},{"step":4,"source_step":4,"section":null,"text":"When the beef is tender, add the sweet potato and carrot and simmer for 5 minutes, until tender."},{"step":5,"source_step":5,"section":null,"text":"Add the bananas and cook for about 5 minutes, until the fruit is soft."},{"step":6,"source_step":6,"section":null,"text":"Add the cabbage, tomato sauce, and chickpeas, and let it simmer until the liquid has reduced to the consistency of a thin stew, about 10 minutes."},{"step":7,"source_step":7,"section":null,"text":"Add the sugar, if using, and season with salt and pepper before serving."}],"source_tips":["SUBSTITUTION TIP: Use 1 (12-ounce) can of pork and beans instead of the tomato sauce.","COOKING TIP: In an electric pressure cooker, use the sauté function to complete step 1. Cover the beef in water as instructed, seal, and cook at high pressure for 25 minutes. Quick release the pressure and continue with the recipe using the sauté function to simmer the sweet potatoes, carrots, banana, cabbage, tomato sauce, and chickpeas."],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[114,115],"printed_pages":[106,107]},"review_flags":["Instructions mention water outside the ingredient list; source list retained. Review cooking/soaking water handling in the app."],"prep_minutes":20,"cook_minutes":80,"additional_time_text":null,"default_image":null,"slug":"pochero-beef"},
{"id":66,"name":"Beef Mechado","filipino_name":"Mechadong Baka","category":"Meat","prep_time_text":"15 minutes","cook_time_text":"1 hour 20 minutes","yield_type":"serves","yield_text":"2 to 4","ingredients":[{"source_text":"3 tablespoons canola oil","source_pdf_page":116,"section":null,"position":1,"match_options":["canola oil"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3 tablespoons","related_recipe_id":null},{"source_text":"2 pounds beef chuck, cut into 1-inch cubes","source_pdf_page":116,"section":null,"position":2,"match_options":["beef"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 pounds","related_recipe_id":null},{"source_text":"1 onion, finely diced","source_pdf_page":116,"section":null,"position":3,"match_options":["onion"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"3 garlic cloves, crushed","source_pdf_page":116,"section":null,"position":4,"match_options":["garlic"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3","related_recipe_id":null},{"source_text":"1 tomato, finely diced","source_pdf_page":116,"section":null,"position":5,"match_options":["tomato"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"10 cups beef stock or water","source_pdf_page":116,"section":null,"position":6,"match_options":["beef stock","water"],"match_rule":"any_of","role":"main","required_for_matching":true,"quantity_prefix_text":"10 cups","quantity_note":"Display source_text to preserve compound quantities and/or alternative amounts; quantity_prefix_text is only the leading amount.","related_recipe_id":null},{"source_text":"3 cups tomato sauce","source_pdf_page":116,"section":null,"position":7,"match_options":["tomato sauce"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3 cups","related_recipe_id":null},{"source_text":"5 tablespoons calamansi juice or lemon juice","source_pdf_page":116,"section":null,"position":8,"match_options":["calamansi","lemon"],"match_rule":"any_of","role":"main","required_for_matching":true,"quantity_prefix_text":"5 tablespoons","related_recipe_id":null},{"source_text":"3 tablespoons soy sauce","source_pdf_page":116,"section":null,"position":9,"match_options":["soy sauce"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3 tablespoons","related_recipe_id":null},{"source_text":"1 bay leaf","source_pdf_page":116,"section":null,"position":10,"match_options":["bay leaf"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"1 potato, cut into 1-inch cubes","source_pdf_page":116,"section":null,"position":11,"match_options":["potato"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"Salt","source_pdf_page":116,"section":null,"position":12,"match_options":["salt"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":null,"related_recipe_id":null},{"source_text":"Freshly ground black pepper","source_pdf_page":116,"section":null,"position":13,"match_options":["black pepper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":null,"related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"In a large sauté pan or skillet, heat the oil over medium-high heat. Cook the beef for 2 to 3 minutes, or until the meat is browned on all sides."},{"step":2,"source_step":2,"section":null,"text":"Add the onion and garlic and sauté for 3 to 5 minutes, or until translucent and fragrant. Add the tomato and sauté until just soft, about 2 minutes more."},{"step":3,"source_step":3,"section":null,"text":"Pour in the beef stock, tomato sauce, calamansi juice, soy sauce, and bay leaf. Bring to a boil, then reduce the heat to low and simmer, skimming the foam off the surface as it cooks, for 1 hour, or until the meat is tender."},{"step":4,"source_step":4,"section":null,"text":"Adjust the heat to medium and add the potatoes. Cook the potatoes for 5 to 8 minutes, until they are fork-tender. Season with salt and pepper."},{"step":5,"source_step":5,"section":null,"text":"Continue to cook for 10 minutes more, until the liquid has reduced to the consistency of a stew. Taste and adjust the seasoning as desired."}],"source_tips":["COOKING TIP: To make this in an electric pressure cooker, use the sauté function and follow steps 1 through 3. After adding the ingredients in step 3, cover and lock the lid and cook on high pressure for 30 minutes. Quick release the pressure and open the cooker. Use the sauté function to cook the potatoes in step 4 and finish the recipe as directed."],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[116],"printed_pages":[108]},"review_flags":[],"prep_minutes":15,"cook_minutes":80,"additional_time_text":null,"default_image":null,"slug":"beef-mechado"},
