ity_note":"Display source_text to preserve compound quantities and/or alternative amounts; quantity_prefix_text is only the leading amount.","related_recipe_id":null},{"source_text":"5 labuyo chiles or Thai chiles","source_pdf_page":118,"section":null,"position":8,"match_options":["labuyo chili","thai chili"],"match_rule":"any_of","role":"main","required_for_matching":true,"quantity_prefix_text":"5","related_recipe_id":null},{"source_text":"6 cups beef stock or water","source_pdf_page":118,"section":null,"position":9,"match_options":["beef stock","water"],"match_rule":"any_of","role":"main","required_for_matching":true,"quantity_prefix_text":"6 cups","related_recipe_id":null},{"source_text":"2 bay leaves","source_pdf_page":118,"section":null,"position":10,"match_options":["bay leaf"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2","related_recipe_id":null},{"source_text":"2 medium potatoes, peeled and cut into 1-inch cubes and soaked in cold water","source_pdf_page":118,"section":null,"position":11,"match_options":["potato"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2","related_recipe_id":null},{"source_text":"1 medium carrot, peeled and cut into 1-inch pieces","source_pdf_page":118,"section":null,"position":12,"match_options":["carrot"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"1/2 cup pitted Spanish olives","source_pdf_page":118,"section":null,"position":13,"match_options":["spanish olive"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2 cup","related_recipe_id":null},{"source_text":"1/2 red bell pepper, cut into 1-inch cubes","source_pdf_page":118,"section":null,"position":14,"match_options":["red bell pepper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2","related_recipe_id":null},{"source_text":"1/2 green bell pepper, cut into 1-inch cubes","source_pdf_page":118,"section":null,"position":15,"match_options":["green bell pepper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2","related_recipe_id":null},{"source_text":"Salt","source_pdf_page":118,"section":null,"position":16,"match_options":["salt"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":null,"related_recipe_id":null},{"source_text":"Freshly ground black pepper","source_pdf_page":118,"section":null,"position":17,"match_options":["black pepper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":null,"related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"In a wok or deep pot, heat the canola oil over medium-high heat. Sauté the tomatoes, onion, and garlic for 3 to 5 minutes, or until translucent and fragrant."},{"step":2,"source_step":2,"section":null,"text":"Add the beef and continue to sauté, stirring, for about 5 minutes, until the meat is browned. Add the ground pork, tomato paste, and chiles and cook for 1 minute, stirring until incorporated."},{"step":3,"source_step":3,"section":null,"text":"Add the beef stock and bay leaves. Simmer until the beef is tender, about 1 hour, skimming the foam off the surface as it cooks."},{"step":4,"source_step":4,"section":null,"text":"Add the potatoes and carrot and cook until they are fork-tender, about 8 minutes. Add the olives and let simmer for about 10 minutes, or until the sauce thickens to a stew consistency. Add the bell peppers, and season with salt and pepper before serving."}],"source_tips":["COOKING TIP: To make this stew in an electric pressure cooker, use the sauté function to cook the tomatoes, onions, and garlic in the cooker. Follow steps 2 through 3 but stop after adding the bay leaves. Seal the lid of the pressure cooker and cook for 30 minutes on high pressure. Allow the pressure to release naturally for about 20 minutes, then quick release any remaining pressure. Open the cooker, and using the sauté function, continue with step 4.","SUBSTITUTION TIP: For 1 cup ground liver, process 4 ounces of liver in a food processor. If liver is unavailable, you can replace it with canned liver spread or omit it."],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[118,119],"printed_pages":[110,111]},"review_flags":["Source phrase \"ground pork or beef liver\" is ambiguous; retained ground pork and beef liver without assuming pork liver."],"prep_minutes":20,"cook_minutes":90,"additional_time_text":null,"default_image":null,"slug":"spicy-stew-pot-beef"},
{"id":69,"name":"Oxtail Kare Kare","filipino_name":"Kare Kare Buntot Ng Baka","category":"Meat","prep_time_text":"15 minutes","cook_time_text":"4 hours 30 minutes","yield_type":"serves","yield_text":"4","ingredients":[{"source_text":"2 pounds beef oxtail, cut into serving size","source_pdf_page":120,"section":"FOR THE OXTAIL STOCK","position":1,"match_options":["beef oxtail"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 pounds","related_recipe_id":null},{"source_text":"1 onion, halved","source_pdf_page":120,"section":"FOR THE OXTAIL STOCK","position":2,"match_options":["onion"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"3 tablespoons canola oil or vegetable oil","source_pdf_page":120,"section":"FOR THE STEW","position":3,"match_options":["canola oil","vegetable oil"],"match_rule":"any_of","role":"main","required_for_matching":true,"quantity_prefix_text":"3 tablespoons","related_recipe_id":null},{"source_text":"1 onion, thinly sliced","source_pdf_page":120,"section":"FOR THE STEW","position":4,"match_options":["onion"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"5 garlic cloves, minced","source_pdf_page":120,"section":"FOR THE STEW","position":5,"match_options":["garlic"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"5","related_recipe_id":null},{"source_text":"2 cups toasted ground peanuts (see tip)","source_pdf_page":120,"section":"FOR THE STEW","position":6,"match_options":["peanut"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 cups","related_recipe_id":null},{"source_text":"1 tablespoon paprika","source_pdf_page":120,"section":"FOR THE STEW","position":7,"match_options":["paprika"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 tablespoon","related_recipe_id":null},{"source_text":"2 Filipino eggplant, cut into 1/2-inch-thick slices","source_pdf_page":120,"section":"FOR THE STEW","position":8,"match_options":["eggplant"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2","related_recipe_id":null},{"source_text":"1 1/2 cups long beans or green beans, cut into 3-inch pieces","source_pdf_page":120,"section":"FOR THE STEW","position":9,"match_options":["long bean","green bean"],"match_rule":"any_of","role":"main","required_for_matching":true,"quantity_prefix_text":"1 1/2 cups","quantity_note":"Display source_text to preserve compound quantities and/or alternative amounts; quantity_prefix_text is only the leading amount.","related_recipe_id":null},{"source_text":"1/2 cup toasted ground rice (see tip)","source_pdf_page":120,"section":"FOR THE STEW","position":10,"match_options":["toasted ground rice"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2 cup","related_recipe_id":null},{"source_text":"1 teaspoon salt","source_pdf_page":120,"section":"FOR THE STEW","position":11,"match_options":["salt"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 teaspoon","related_recipe_id":null},{"source_text":"5 bok choy, cut in half lengthwise","source_pdf_page":120,"section":"FOR THE STEW","position":12,"match_options":["bok choy"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"5","related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":"TO MAKE THE OXTAIL STOCK","text":"In a deep pot, place the oxtail and onion. Cover with water and bring to a boil, skimming the foam off the surface as it cooks. Reduce the heat and simmer for 3 1/2 to 4 hours, or until the meat is tender. Continue to skim the surface as needed."},{"step":2,"source_step":2,"section":"TO MAKE THE OXTAIL STOCK","text":"Remove the onion pieces and discard. Strain the stock, reserving both the stock and the oxtail in separate bowls."},{"step":3,"source_step":1,"section":"TO MAKE THE STEW","text":"In a separate pot, heat the oil over medium-high heat and sauté the onion and garlic for 3 to 5 minutes, or until translucent and fragrant."},{"step":4,"source_step":2,"section":"TO MAKE THE STEW","text":"Add the peanuts and continue to stir to prevent lumps. Add 3 cups of the reserved stock and the paprika. Stir and let simmer for 1 minute."},{"step":5,"source_step":3,"section":"TO MAKE THE STEW","text":"Add the eggplant and cook for an additional minute. Add the long beans and blanch about 1 minute more."},{"step":6,"source_step":4,"section":"TO MAKE THE STEW","text":"In a separate bowl, mix the toasted ground rice with about a cup of stock until it forms a paste, and add to the pot. Continue to stir, being careful of lumps. If the liquid is too thick, add more stock."},{"step":7,"source_step":5,"section":"TO MAKE THE STEW","text":"Add the reserved oxtail and bring back to a boil, then reduce the heat to medium and let it simmer for 5 minutes. Season with salt."},{"step":8,"source_step":6,"section":"TO MAKE THE STEW","text":"Add the bok choy and stir to combine. Simmer for 2 to 3 minutes, until the bok choy is tender but still crisp."}],"source_tips":["INGREDIENT TIP: For toasted rice and toasted peanuts, toast each individually in a dry skillet for 5 minutes, then process in a food processor, spice grinder, or coffee grinder. If desired, you can also substitute 1 cup peanut butter in place of the peanuts and rice.","SUBSTITUTION TIP: Japanese or Chinese eggplant can be used in place of Filipino eggplant."],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[120,121],"printed_pages":[112,113]},"review_flags":["Multi-component recipe: preserve ingredient sections and instruction sections.","Instructions mention water outside the ingredient list; source list retained. Review cooking/soaking water handling in the app."],"prep_minutes":15,"cook_minutes":270,"additional_time_text":null,"default_image":null,"slug":"oxtail-kare-kare"},
{"id":70,"name":"Cured Milkfish","filipino_name":"Daing Na Bangus","category":"Fish and Seafood","prep_time_text":"5 minutes, plus 4 hours (or overnight) to marinate","cook_time_text":"10 minutes","yield_type":"serves","yield_text":"2 to 4","ingredients":[{"source_text":"1 1/2 cups vinegar","source_pdf_page":124,"section":null,"position":1,"match_options":["vinegar"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 1/2 cups","related_recipe_id":null},{"source_text":"1 tablespoon finely chopped garlic","source_pdf_page":124,"section":null,"position":2,"match_options":["garlic"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 tablespoon","related_recipe_id":null},{"source_text":"1 tablespoon salt","source_pdf_page":124,"section":null,"position":3,"match_options":["salt"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 tablespoon","related_recipe_id":null},{"source_text":"1/4 teaspoon freshly ground black pepper","source_pdf_page":124,"section":null,"position":4,"match_options":["black pepper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/4 teaspoon","related_recipe_id":null},{"source_text":"1 bay leaf","source_pdf_page":124,"section":null,"position":5,"match_options":["bay leaf"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"2 whole milkfish, split lengthwise (see tip)","source_pdf_page":124,"section":null,"position":6,"match_options":["milkfish"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2","related_recipe_id":null},{"source_text":"1 cup vegetable oil, for frying","source_pdf_page":124,"section":null,"position":7,"match_options":["vegetable oil"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 cup","related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"In a bowl, combine the vinegar, garlic, salt, pepper, and bay leaf."},{"step":2,"source_step":2,"section":null,"text":"In a nonreactive dish, place the fish and pour the vinegar mixture over the whole fish. Cover and refrigerate for at least 4 hours, or overnight."},{"step":3,"source_step":3,"section":null,"text":"Remove from refrigerator and pat the fish dry before cooking."},{"step":4,"source_step":4,"section":null,"text":"In a large sauté pan or pot, heat the oil over medium-high heat until shimmering, or the end of a wooden spoon dipped into it produces bubbles. Fry the fish skin-side down, about 5 minutes per side. Spoon the hot oil over the fish for faster cooking."},{"step":5,"source_step":5,"section":null,"text":"Transfer fish onto a paper-towel-lined platter to drain before serving."}],"source_tips":["SUBSTITUTION TIP: While milkfish is a popular choice in this preparation, try this with tilapia, pompano, or sole."],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[124],"printed_pages":[116]},"review_flags":["Additional waiting time is retained as text; do not display prep + cook as total elapsed time."],"prep_minutes":5,"cook_minutes":10,"additional_time_text":"4 hours (or overnight) to marinate","default_image":null,"slug":"cured-milkfish"},
{"id":71,"name":"Salmon In Sour Miso Soup","filipino_name":"Sinigang Sa Miso","category":"Fish and Seafood","prep_time_text":"10 minutes","cook_time_text":"25 minutes","yield_type":"serves","yield_text":"2 to 4","ingredients":[{"source_text":"2 tablespoons vegetable oil or canola oil","source_pdf_page":125,"section":null,"position":1,"match_options":["vegetable oil","canola oil"],"match_rule":"any_of","role":"main","required_for_matching":true,"quantity_prefix_text":"2 tablespoons","related_recipe_id":null},{"source_text":"1 onion, diced","source_pdf_page":125,"section":null,"position":2,"match_options":["onion"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"1 tablespoon minced garlic","source_pdf_page":125,"section":null,"position":3,"match_options":["garlic"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 tablespoon","related_recipe_id":null},{"source_text":"1 tablespoon minced ginger","source_pdf_page":125,"section":null,"position":4,"match_options":["ginger"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 tablespoon","related_recipe_id":null},{"source_text":"2 tomatoes, diced","source_pdf_page":125,"section":null,"position":5,"match_options":["tomato"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2","related_recipe_id":null},{"source_text":"1 cup miso paste","source_pdf_page":125,"section":null,"position":6,"match_options":["miso paste"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 cup","related_recipe_id":null},{"source_text":"6 cups fish stock or water","source_pdf_page":125,"section":null,"position":7,"match_options":["fish stock","water"],"match_rule":"any_of","role":"main","required_for_matching":true,"quantity_prefix_text":"6 cups","related_recipe_id":null},{"source_text":"1 daikon radish, cut in 1/2-inch-thick slices","source_pdf_page":125,"section":null,"position":8,"match_options":["daikon radish"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"1 cup tamarind juice or lemon juice","source_pdf_page":125,"section":null,"position":9,"match_options":["tamarind juice","lemon"],"match_rule":"any_of","role":"main","required_for_matching":true,"quantity_prefix_text":"1 cup","related_recipe_id":null},{"source_text":"2 pounds salmon fillet, skin removed and cut into 2-inch cubes","source_pdf_page":125,"section":null,"position":10,"match_options":["salmon"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 pounds","related_recipe_id":null},{"source_text":"2 tablespoons fish sauce (optional)","source_pdf_page":125,"section":null,"position":11,"match_options":["fish sauce"],"match_rule":"single","role":"optional","required_for_matching":false,"quantity_prefix_text":"2 tablespoons","related_recipe_id":null},{"source_text":"Salt","source_pdf_page":125,"section":null,"position":12,"match_options":["salt"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":null,"related_recipe_id":null},{"source_text":"2 cups chopped mustard greens, spinach, or kale","source_pdf_page":125,"section":null,"position":13,"match_options":["mustard green","spinach","kale"],"match_rule":"any_of","role":"main","required_for_matching":true,"quantity_prefix_text":"2 cups","related_recipe_id":null},{"source_text":"3 banana peppers","source_pdf_page":125,"section":null,"position":14,"match_options":["banana pepper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3","related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"In a medium pot, heat the oil over medium heat. Add the onion, garlic, and ginger and sauté for 3 to 5 minutes, or until translucent and fragrant. Add the tomatoes and sauté for 2 minutes, or until just soft."},{"step":2,"source_step":2,"section":null,"text":"Add the miso paste and cook for 3 minutes. Pour in the fish stock and bring it to a boil. Add the radish and tamarind juice and cook for 2 minutes."},{"step":3,"source_step":3,"section":null,"text":"Reduce the heat to low and add the salmon and fish sauce (if using). Season with salt and simmer for 8 minutes, or until the salmon is cooked through and flakes with a fork."},{"step":4,"source_step":4,"section":null,"text":"Add the mustard greens and stir. Taste, and adjust the seasoning as desired. Add the banana peppers and cook for 2 minutes until heated through before serving."}],"source_tips":["SUBSTITUTION TIP: Catfish, mahi mahi, and milkfish are all good substitutes for the salmon in the recipe."],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[125],"printed_pages":[117]},"review_flags":[],"prep_minutes":10,"cook_minutes":25,"additional_time_text":null,"default_image":null,"slug":"salmon-in-sour-miso-soup"},
