e salmon or tuna in place of the halibut."],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[127],"printed_pages":[119]},"review_flags":["Additional waiting time is retained as text; do not display prep + cook as total elapsed time."],"prep_minutes":10,"cook_minutes":null,"additional_time_text":"30 minutes to marinate","default_image":null,"slug":"citrus-cooked-halibut"},
{"id":74,"name":"Grilled Tilapia","filipino_name":null,"category":"Fish and Seafood","prep_time_text":"10 minutes","cook_time_text":"20 minutes","yield_type":"serves","yield_text":"2 to 4","ingredients":[{"source_text":"1 whole tilapia, cleaned, gutted, and scaled","source_pdf_page":128,"section":null,"position":1,"match_options":["tilapia"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"1 tablespoon canola oil","source_pdf_page":128,"section":null,"position":2,"match_options":["canola oil"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 tablespoon","related_recipe_id":null},{"source_text":"1 teaspoon plus pinch salt, divided","source_pdf_page":128,"section":null,"position":3,"match_options":["salt"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 teaspoon","quantity_note":"Display source_text to preserve compound quantities and/or alternative amounts; quantity_prefix_text is only the leading amount.","related_recipe_id":null},{"source_text":"Freshly ground black pepper","source_pdf_page":128,"section":null,"position":4,"match_options":["black pepper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":null,"related_recipe_id":null},{"source_text":"1 tomato, diced","source_pdf_page":128,"section":null,"position":5,"match_options":["tomato"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"1/4 cup minced fresh ginger","source_pdf_page":128,"section":null,"position":6,"match_options":["ginger"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/4 cup","related_recipe_id":null},{"source_text":"1 shallot, minced","source_pdf_page":128,"section":null,"position":7,"match_options":["shallot"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"1 tablespoon minced garlic","source_pdf_page":128,"section":null,"position":8,"match_options":["garlic"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 tablespoon","related_recipe_id":null},{"source_text":"2 calamansi or 1 lemon, sliced, divided","source_pdf_page":128,"section":null,"position":9,"match_options":["calamansi","lemon"],"match_rule":"any_of","role":"main","required_for_matching":true,"quantity_prefix_text":"2","quantity_note":"Display source_text to preserve compound quantities and/or alternative amounts; quantity_prefix_text is only the leading amount.","related_recipe_id":null},{"source_text":"1 banana leaf","source_pdf_page":128,"section":null,"position":10,"match_options":["banana leaf"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"Preheat the grill to medium, or see the Cooking Tip for oven instructions."},{"step":2,"source_step":2,"section":null,"text":"Rub the fish with the canola oil, then season it inside and out with salt and pepper."},{"step":3,"source_step":3,"section":null,"text":"In a medium nonreactive bowl, combine the tomato, ginger, shallot, garlic, and 1 teaspoon salt. Fill the cavities of the fish with the mixture and calamansi slices."},{"step":4,"source_step":4,"section":null,"text":"Tightly wrap the fish in a banana leaf."},{"step":5,"source_step":5,"section":null,"text":"Grill the fish for 10 minutes on each side, flipping once. Remove from the heat and let rest for 5 minutes."},{"step":6,"source_step":6,"section":null,"text":"Unwrap the fish and place it on a serving platter. Garnish with calamansi slices and serve."}],"source_tips":["SUBSTITUTION TIP: Replace the tilapia with whole sea bass, pompano, or milkfish.","COOKING TIP: If a grill is unavailable, bake in a 400°F oven for 20 to 25 minutes until the fish flakes when pierced with a fork and the flesh turns white."],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[128],"printed_pages":[120]},"review_flags":[],"prep_minutes":10,"cook_minutes":20,"additional_time_text":null,"default_image":null,"slug":"grilled-tilapia"},
{"id":75,"name":"Sweet-And-Sour Fish","filipino_name":"Escabeche","category":"Fish and Seafood","prep_time_text":"10 minutes","cook_time_text":"20 minutes","yield_type":"serves","yield_text":"2","ingredients":[{"source_text":"2 pounds whole red snapper, tilapia, or sea bass","source_pdf_page":129,"section":null,"position":1,"match_options":["red snapper","tilapia","sea bass"],"match_rule":"any_of","role":"main","required_for_matching":true,"quantity_prefix_text":"2 pounds","related_recipe_id":null},{"source_text":"1 teaspoon plus pinch salt, divided","source_pdf_page":129,"section":null,"position":2,"match_options":["salt"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 teaspoon","quantity_note":"Display source_text to preserve compound quantities and/or alternative amounts; quantity_prefix_text is only the leading amount.","related_recipe_id":null},{"source_text":"1/4 teaspoon plus pinch freshly ground black pepper, divided","source_pdf_page":129,"section":null,"position":3,"match_options":["black pepper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/4 teaspoon","quantity_note":"Display source_text to preserve compound quantities and/or alternative amounts; quantity_prefix_text is only the leading amount.","related_recipe_id":null},{"source_text":"1/2 cup, plus 3 tablespoons canola oil, divided","source_pdf_page":129,"section":null,"position":4,"match_options":["canola oil"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2 cup","quantity_note":"Display source_text to preserve compound quantities and/or alternative amounts; quantity_prefix_text is only the leading amount.","related_recipe_id":null},{"source_text":"4 cups water, plus 4 tablespoons water, divided","source_pdf_page":129,"section":null,"position":5,"match_options":["water"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"4 cups","quantity_note":"Display source_text to preserve compound quantities and/or alternative amounts; quantity_prefix_text is only the leading amount.","related_recipe_id":null},{"source_text":"1 cup sugar","source_pdf_page":129,"section":null,"position":6,"match_options":["sugar"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 cup","related_recipe_id":null},{"source_text":"1/4 cup white vinegar","source_pdf_page":129,"section":null,"position":7,"match_options":["white vinegar"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/4 cup","related_recipe_id":null},{"source_text":"1 teaspoon paprika","source_pdf_page":129,"section":null,"position":8,"match_options":["paprika"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 teaspoon","related_recipe_id":null},{"source_text":"1/2 cup julienned ginger","source_pdf_page":129,"section":null,"position":9,"match_options":["ginger"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2 cup","related_recipe_id":null},{"source_text":"1 shallot, julienned","source_pdf_page":129,"section":null,"position":10,"match_options":["shallot"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"1 teaspoon thinly sliced garlic","source_pdf_page":129,"section":null,"position":11,"match_options":["garlic"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 teaspoon","related_recipe_id":null},{"source_text":"1/2 cup scallions, both white and green parts, finely chopped, plus 2 scallions, green parts only, chopped, for garnish (optional)","source_pdf_page":129,"section":null,"position":12,"match_options":["scallion"],"match_rule":"single","role":"main_with_optional_garnish","required_for_matching":true,"quantity_prefix_text":"1/2 cup","quantity_note":"Display source_text to preserve compound quantities and/or alternative amounts; quantity_prefix_text is only the leading amount.","related_recipe_id":null},{"source_text":"2 heaping tablespoons cornstarch","source_pdf_page":129,"section":null,"position":13,"match_options":["cornstarch"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 heaping tablespoons","related_recipe_id":null},{"source_text":"1/2 red bell pepper, julienned","source_pdf_page":129,"section":null,"position":14,"match_options":["red bell pepper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2","related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"Season the fish with salt and pepper."},{"step":2,"source_step":2,"section":null,"text":"In a large skillet, heat the 1/2 cup of oil over medium heat. Fry the fish for 2 minutes on each side, carefully spooning the oil over the fish, until cooked through and crispy."},{"step":3,"source_step":3,"section":null,"text":"Remove the fish from the oil and set aside on a paper-towel-lined plate."},{"step":4,"source_step":4,"section":null,"text":"In a bowl, combine the 4 cups of water, sugar, vinegar, and paprika and set aside."},{"step":5,"source_step":5,"section":null,"text":"In a clean pan, heat the remaining 3 tablespoons of oil over medium heat. Add the ginger, shallot, garlic, and 1/2 cup of scallions, and sauté for 3 to 5 minutes, or until translucent and fragrant. Add the water-and-sugar mixture to the pan and bring to a boil. Lower the heat to medium and simmer for 5 minutes."},{"step":6,"source_step":6,"section":null,"text":"In a small bowl, combine the 4 tablespoons of water and the cornstarch and mix well. Pour in the pan, add the bell pepper, and simmer for 2 minutes, or until the liquid reduces to a light sauce."},{"step":7,"source_step":7,"section":null,"text":"Season with salt and pepper. Taste and adjust the seasoning as desired. Turn off the heat and garnish with the scallions (if using) before serving."}],"source_tips":[],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[129],"printed_pages":[121]},"review_flags":["Scallions include a required base amount and optional extra garnish in the same source line."],"prep_minutes":10,"cook_minutes":20,"additional_time_text":null,"default_image":null,"slug":"sweet-and-sour-fish"},
{"id":76,"name":"Fish With Eggs","filipino_name":"Sarciado","category":"Fish and Seafood","prep_time_text":"10 minutes","cook_time_text":"30 minutes","yield_type":"serves","yield_text":"4 to 6","ingredients":[{"source_text":"2 whole sea bass, tilapia, or pompano","source_pdf_page":130,"section":null,"position":1,"match_options":["sea bass","tilapia","pompano"],"match_rule":"any_of","role":"main","required_for_matching":true,"quantity_prefix_text":"2","related_recipe_id":null},{"source_text":"Salt","source_pdf_page":130,"section":null,"position":2,"match_options":["salt"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":null,"related_recipe_id":null},{"source_text":"Freshly ground black pepper","source_pdf_page":130,"section":null,"position":3,"match_options":["black pepper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":null,"related_recipe_id":null},{"source_text":"1 1/2 cups, plus 3 tablespoons canola oil","source_pdf_page":130,"section":null,"position":4,"match_options":["canola oil"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 1/2 cups","quantity_note":"Display source_text to preserve compound quantities and/or alternative amounts; quantity_prefix_text is only the leading amount.","related_recipe_id":null},{"source_text":"1 onion, diced","source_pdf_page":130,"section":null,"position":5,"match_options":["onion"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"3 garlic cloves, crushed","source_pdf_page":130,"section":null,"position":6,"match_options":["garlic"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3","related_recipe_id":null},{"source_text":"4 tomatoes, diced","source_pdf_page":130,"section":null,"position":7,"match_options":["tomato"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"4","related_recipe_id":null},{"source_text":"3 large eggs, beaten","source_pdf_page":130,"section":null,"position":8,"match_options":["egg"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3","related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"Season the fish with salt and pepper and set aside."},{"step":2,"source_step":2,"section":null,"text":"In a large sauté pan or skillet, heat the 1 1/2 cups of oil over medium heat until it reaches 350°F, or until the end of a wooden spoon dipped in the oil produces bubbles."},{"step":3,"source_step":3,"section":null,"text":"Add the fish and cook for 2 minutes on each side. You can spoon the hot oil over the fish to decrease the cooking time. Remove the fish from the pan and set aside on a paper-towel-lined plate."},{"step":4,"source_step":4,"section":null,"text":"In a clean pan, heat the remaining 3 tablespoons of oil over medium heat. Add the onion and garlic and sauté for 3 to 5 minutes, or until translucent and fragrant."},{"step":5,"source_step":5,"section":null,"text":"Add the tomatoes and sauté for 2 minutes, until just soft. Add the eggs and stir constantly for 30 seconds, to prevent large pieces of cooked egg from forming."},{"step":6,"source_step":6,"section":null,"text":"Once the eggs are cooked, return the fish to the pan and spoon the sauce over it."},{"step":7,"source_step":7,"section":null,"text":"Simmer and stir occasionally for 5 minutes and serve."}],"source_tips":[],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[130],"printed_pages":[122]},"review_flags":[],"prep_minutes":10,"cook_minutes":30,"additional_time_text":null,"default_image":null,"slug":"fish-with-eggs"},
{"id":77,"name":"Ginger Mussel Soup","filipino_name":"Tinola Tahong","category":"Fish and Seafood","prep_time_text":"10 minutes","cook_time_text":"10 minutes","yield_type":"serves","yield_text":"2 to 4","ingredients":[{"source_text":"2 tablespoons canola oil","source_pdf_page":131,"section":null,"position":1,"match_options":["canola oil"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 tablespoons","related_recipe_id":null},{"source_text":"1/2 cup julienned ginger","source_pdf_page":131,"section":null,"position":2,"match_options":["ginger"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2 cup","related_recipe_id":null},{"source_text":"6 garlic cloves, crushed","source_pdf_page":131,"section":null,"position":3,"match_options":["garlic"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"6","related_recipe_id":null},{"source_text":"1 shallot, julienned","source_pdf_page":131,"section":null,"position":4,"match_options":["shallot"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"1 pound mussels, washed and soaked in water","source_pdf_page":131,"section":null,"position":5,"match_options":["mussel"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 pound","related_recipe_id":null},{"source_text":"3 cups water","source_pdf_page":131,"section":null,"position":6,"match_options":["water"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3 cups","related_recipe_id":null},{"source_text":"2 teaspoons salt","source_pdf_page":131,"section":null,"position":7,"match_options":["salt"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 teaspoons","related_recipe_id":null},{"source_text":"1 teaspoon freshly ground black pepper","source_pdf_page":131,"section":null,"position":8,"match_options":["black pepper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 teaspoon","related_recipe_id":null},{"source_text":"2 cups spinach","source_pdf_page":131,"section":null,"position":9,"match_options":["spinach"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 cups","related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"In a medium pot, heat the oil over medium heat. Add the ginger, garlic, and shallot and sauté for about 3 minutes, or until fragrant and translucent."},{"step":2,"source_step":2,"section":null,"text":"Add the mussels and toss well. Add the water, bring it to a boil, and then lower the heat to medium and simmer for 5 minutes."},{"step":3,"source_step":3,"section":null,"text":"Season with salt and pepper. Add spinach, and stir until just wilted before serving."}],"source_tips":["SUBSTITUTION TIP: This recipe works with clams and shrimp as substitutes for mussels."],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[131],"printed_pages":[123]},"review_flags":[],"prep_minutes":10,"cook_minutes":10,"additional_time_text":null,"default_image":null,"slug":"ginger-mussel-soup"},
{"id":78,"name":"Clam And Corn Soup","filipino_name":"Halaan At Mais","category":"Fish and Seafood","prep_time_text":"10 minutes","cook_time_text":"10 minutes","yield_type":"serves","yield_text":"2 to 4","ingredients":[{"source_text":"3 tablespoons canola oil","source_pdf_page":132,"section":null,"position":1,"match_options":["canola oil"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3 tablespoons","related_recipe_id":null},{"source_text":"1 shallot, minced","source_pdf_page":132,"section":null,"position":2,"match_options":["shallot"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"3 garlic cloves, minced","source_pdf_page":132,"section":null,"position":3,"match_options":["garlic"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3","related_recipe_id":null},{"source_text":"1/4 teaspoon grated fresh ginger","source_pdf_page":132,"section":null,"position":4,"match_options":["ginger"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/4 teaspoon","related_recipe_id":null},{"source_text":"1 pound clams, washed and soaked in water","source_pdf_page":132,"section":null,"position":5,"match_options":["clam"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 pound","related_recipe_id":null},{"source_text":"2 cups water","source_pdf_page":132,"section":null,"position":6,"match_options":["water"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 cups","related_recipe_id":null},{"source_text":"1 cup clam juice","source_pdf_page":132,"section":null,"position":7,"match_options":["clam juice"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 cup","related_recipe_id":null},{"source_text":"1 cup corn","source_pdf_page":132,"section":null,"position":8,"match_options":["corn"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 cup","related_recipe_id":null},{"source_text":"Salt","source_pdf_page":132,"section":null,"position":9,"match_options":["salt"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":null,"related_recipe_id":null},{"source_text":"Freshly ground black pepper","source_pdf_page":132,"section":null,"position":10,"match_options":["black pepper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":null,"related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"In a medium pan, heat the oil over medium heat. Add the shallot, garlic, and ginger and sauté for 3 to 5 minutes, or until translucent and fragrant."},{"step":2,"source_step":2,"section":null,"text":"Add the clams, water, clam juice, and corn. Bring to a boil, then reduce the heat to low, and simmer for 5 minutes."},{"step":3,"source_step":3,"section":null,"text":"Season with salt and pepper. Raise the heat to medium and cook to reduce the liquid for 3 minutes. Turn off the heat and discard any unopened clams before serving."}],"source_tips":["SUBSTITUTION TIP: If you prefer a creamier soup, you can add a 1/4 cup of heavy whipping cream or coconut milk at the end of cooking."],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[132],"printed_pages":[124]},"review_flags":[],"prep_minutes":10,"cook_minutes":10,"additional_time_text":null,"default_image":null,"slug":"clam-and-corn-soup"},
{"id":79,"name":"Shrimp Sour Soup","filipino_name":"Sinigang Na Hipon","category":"Fish and Seafood","prep_time_text":"10 minutes","cook_time_text":"15 minutes","yield_type":"serves","yield_text":"2 to 4","ingredients":[{"source_text":"6 to 8 cups water","source_pdf_page":133,"section":null,"position":1,"match_options":["water"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"6 to 8 cups","related_recipe_id":null},{"source_text":"2 tomatoes, quartered","source_pdf_page":133,"section":null,"position":2,"match_options":["tomato"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2","related_recipe_id":null},{"source_text":"1 onion, quartered","source_pdf_page":133,"section":null,"position":3,"match_options":["onion"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"1 Filipino or Chinese or Japanese eggplant, cut in 1/4-inch-thick slices","source_pdf_page":133,"section":null,"position":4,"match_options":["eggplant"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"1 cup green beans","source_pdf_page":133,"section":null,"position":5,"match_options":["green bean"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 cup","related_recipe_id":null},{"source_text":"1 cup tamarind juice or lemon juice","source_pdf_page":133,"section":null,"position":6,"match_options":["tamarind juice","lemon"],"match_rule":"any_of","role":"main","required_for_matching":true,"quantity_prefix_text":"1 cup","related_recipe_id":null},{"source_text":"1 daikon radish, cut into 1/4-inch-thick slices (optional)","source_pdf_page":133,"section":null,"position":7,"match_options":["daikon radish"],"match_rule":"single","role":"optional","required_for_matching":false,"quantity_prefix_text":"1","related_recipe_id":null},{