{"id":82,"name":"Shrimp In Coconut Sauce","filipino_name":"Ginataang Hipon","category":"Fish and Seafood","prep_time_text":"10 minutes","cook_time_text":"20 minutes","yield_type":"serves","yield_text":"2 to 4","ingredients":[{"source_text":"3 tablespoons canola oil","source_pdf_page":136,"section":null,"position":1,"match_options":["canola oil"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3 tablespoons","related_recipe_id":null},{"source_text":"1 onion, julienned","source_pdf_page":136,"section":null,"position":2,"match_options":["onion"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"1/4 cup julienned ginger","source_pdf_page":136,"section":null,"position":3,"match_options":["ginger"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/4 cup","related_recipe_id":null},{"source_text":"3 garlic cloves, crushed","source_pdf_page":136,"section":null,"position":4,"match_options":["garlic"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3","related_recipe_id":null},{"source_text":"2 cups coconut milk","source_pdf_page":136,"section":null,"position":5,"match_options":["coconut milk"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 cups","related_recipe_id":null},{"source_text":"1 pound whole shrimp, with heads on","source_pdf_page":136,"section":null,"position":6,"match_options":["shrimp"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 pound","related_recipe_id":null},{"source_text":"3 Thai chiles or serrano peppers","source_pdf_page":136,"section":null,"position":7,"match_options":["thai chili","serrano pepper"],"match_rule":"any_of","role":"main","required_for_matching":true,"quantity_prefix_text":"3","related_recipe_id":null},{"source_text":"Salt","source_pdf_page":136,"sect