{"id":83,"name":"Crab In Coconut Sauce","filipino_name":"Ginataang Alimango","category":"Fish and Seafood","prep_time_text":"10 minutes","cook_time_text":"30 minutes","yield_type":"serves","yield_text":"2 to 4","ingredients":[{"source_text":"2 Dungeness crabs or 4 blue crabs (see tip)","source_pdf_page":137,"section":null,"position":1,"match_options":["dungeness crab","blue crab"],"match_rule":"any_of","role":"main","required_for_matching":true,"quantity_prefix_text":"2","quantity_note":"Display source_text to preserve compound quantities and/or alternative amounts; quantity_prefix_text is only the leading amount.","related_recipe_id":null},{"source_text":"3 tablespoons canola oil","source_pdf_page":137,"section":null,"position":2,"match_options":["canola oil"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3 tablespoons","related_recipe_id":null},{"source_text":"1/4 cup grated ginger","source_pdf_page":137,"section":null,"position":3,"match_options":["ginger"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/4 cup","related_recipe_id":null},{"source_text":"1 shallot, minced","source_pdf_page":137,"section":null,"position":4,"match_options":["shallot"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"3 garlic cloves, crushed","source_pdf_page":137,"section":null,"position":5,"match_options":["garlic"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3","related_recipe_id":null},{"source_text":"4 cups coconut milk","source_pdf_page":137,"section":null,"position":6,"match_options":["coconut milk"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"4 cups","related_recipe_id":null},{"source_text":"Salt","source_pdf_page":137,"section":null,"position":7,"match_options":["salt"],"match_rule":"single","role":"main","required_for_