{"id":85,"name":"Chicken Empanadas","filipino_name":null,"category":"Snacks and Desserts","prep_time_text":"20 minutes, plus 1 hour (or overnight) to chill","cook_time_text":"25 minutes","yield_type":"serves","yield_text":"8","ingredients":[{"source_text":"3 cups flour","source_pdf_page":142,"section":"FOR THE DOUGH","position":1,"match_options":["flour"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3 cups","related_recipe_id":null},{"source_text":"4 tablespoons sugar","source_pdf_page":142,"section":"FOR THE DOUGH","position":2,"match_options":["sugar"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"4 tablespoons","related_recipe_id":null},{"source_text":"1 teaspoon baking powder","source_pdf_page":142,"section":"FOR THE DOUGH","position":3,"match_options":["baking powder"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 teaspoon","related_recipe_id":null},{"source_text":"1 teaspoon salt","source_pdf_page":142,"section":"FOR THE DOUGH","position":4,"match_options":["salt"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 teaspoon","related_recipe_id":null},{"source_text":"1 cup cold butter, cut into 1/2-inch cubes","source_pdf_page":142,"section":"FOR THE DOUGH","position":5,"match_options":["butter"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 cup","related_recipe_id":null},{"source_text":"1/2 cup ice-cold water","source_pdf_page":142,"section":"FOR THE DOUGH","position":6,"match_options":["water"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2 cup","related_recipe_id":null},{"source_text":"2 tablespoons canola oil","source_pdf_page":142,"section":"FOR THE EMPANADAS","position":7,"match_options":["canola oil"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 tablespoons","related_recipe_id":null},{"source_text":"1 onion, minced","source_pdf_page":142,"section":"FOR THE EMPANADAS","position":8,"match_options":["onion"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"3 garlic cloves, minced","source_pdf_page":142,"section":"FOR THE EMPANADAS","position":9,"match_options":["garlic"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3","related_recipe_id":null},{"source_text":"1 pound ground chicken","source_pdf_page":142,"section":"FOR THE EMPANADAS","position":10,"match_options":["ground chicken"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 pound","related_recipe_id":null},{"source_text":"2 cups water","source_pdf_page":142,"section":"FOR THE EMPANADAS","position":11,"match_options":["water"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 cups","related_recipe_id":null},{"source_text":"1/2 cup finely chopped potato","source_pdf_page":142,"section":"FOR THE EMPANADAS","position":12,"match_options":["potato"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2 cup","related_recipe_id":null},{"source_text":"1/2 cup finely chopped carrot","source_pdf_page":142,"section":"FOR THE EMPANADAS","position":13,"match_options":["carrot"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2 cup","related_recipe_id":null},{"source_text":"1/2 cup green peas","source_pdf_page":142,"section":"FOR THE EMPANADAS","position":14,"match_options":["green pea"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2 cup","related_recipe_id":null},{"source_text":"1/4 cup raisins","source_pdf_page":142,"section":"FOR THE EMPANADAS","position":15,"match_options":["raisin"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/4 cup","related_recipe_id":null},{"source_text":"1 tablespoon sugar","source_pdf_page":142,"section":"FOR THE EMPANADAS","position":16,"match_options":["sugar"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 tablespoon","related_recipe_id":null},{"source_text":"Salt","source_pdf_page":142,"section":"FOR THE EMPANADAS","position":17,"match_options":["salt"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":null,"related_recipe_id":null},{"source_text":"Freshly ground black pepper","source_pdf_page":142,"section":"FOR THE EMPANADAS","position":18,"match_options":["black pepper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":null,"related_recipe_id":null},{"source_text":"1 large egg","source_pdf_page":142,"section":"FOR THE EMPANADAS","position":19,"match_options":["egg"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":"TO MAKE THE DOUGH","text":"Sift the flour, sugar, baking powder, and salt into a pile on a clean countertop."},{"step":2,"source_step":2,"section":"TO MAKE THE DOUGH","text":"On top of the dry ingredients, place the cold butter. Using the back of two forks or a pastry cutter, cut the butter with the dry ingredients until the pieces of butter are the size of peas."},{"step":3,"source_step":3,"section":"TO MAKE THE DOUGH","text":"Create a well in the center of the dough, pour the ice water into the well, and move your fingers in a circular motion to incorporate everything smoothly."},{"step":4,"source_step":4,"section":"TO MAKE THE DOUGH","text":"Roll dough into a ball, divide into two pieces, and form both into flat disks."},{"step":5,"source_step":5,"section":"TO MAKE THE DOUGH","text":"Cover in plastic wrap and refrigerate for at least 1 hour or overnight for the best results."},{"step":6,"source_step":1,"section":"TO MAKE THE EMPANADAS","text":"In a large skillet, heat the oil over medium-high heat. Sauté the onion and garlic for 3 to 5 minutes, or until translucent and fragrant."},{"step":7,"source_step":2,"section":"TO MAKE THE EMPANADAS","text":"Add the chicken and cook for 5 to 6 minutes, stirring regularly, until no longer pink and cooked through."},{"step":8,"source_step":3,"section":"TO MAKE THE EMPANADAS","text":"Add the water, potato, and carrot and simmer, stirring occasionally, until the carrot and potato are tender, about 5 minutes."},{"step":9,"source_step":4,"section":"TO MAKE THE EMPANADAS","text":"Add the peas, raisins, and sugar, and season with salt and pepper. Continue to cook until most of the liquid evaporates. Turn off the heat, transfer to a colander, and let drain over a bowl or the sink."},{"step":10,"source_step":5,"section":"TO MAKE THE EMPANADAS","text":"Preheat the oven to 350°F. Line a baking sheet with parchment paper or a silicone baking mat."},{"step":11,"source_step":6,"section":"TO MAKE THE EMPANADAS","text":"Remove the dough from the refrigerator, unwrap, and immediately roll into a flat sheet about 1/8-inch thick."},{"step":12,"source_step":7,"section":"TO MAKE THE EMPANADAS","text":"Using a 3-inch circle cookie cutter, cut the dough into 8 pieces. Fill each piece with 1 heaping tablespoon of meat filling."},{"step":13,"source_step":8,"section":"TO MAKE THE EMPANADAS","text":"Using a pastry brush, dab the outermost edge of each circle of dough with water. Fold the dough over the filling, creating a half-moon shape. Press the edges together with your fingers or a fork to seal. Once sealed, place the empanadas on the baking sheet."},{"step":14,"source_step":9,"section":"TO MAKE THE EMPANADAS","text":"In a small bowl, beat the egg and then brush the tops of the empanadas with the egg wash. Repeat steps 6 through 10 with the second disc of dough."},{"step":15,"source_step":10,"section":"TO MAKE THE EMPANADAS","text":"Bake for 20 to 25 minutes, or until golden brown."}],"source_tips":["PREP TIP: Make the filling a day or two in advance and store in an airtight container in the refrigerator. When you are ready to make the empanadas, increase the cooking time by 2 to 3 minutes to account for the chilled filling."],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[142,143],"printed_pages":[134,135]},"review_flags":["Additional waiting time is retained as text; do not display prep + cook as total elapsed time.","Multi-component recipe: preserve ingredient sections and instruction sections."],"prep_minutes":20,"cook_minutes":25,"additional_time_text":"1 hour (or overnight) to chill","default_image":null,"slug":"chicken-empanadas"},
{"id":86,"name":"Bread Rolls","filipino_name":"Pandesal","category":"Snacks and Desserts","prep_time_text":"25 minutes, plus 1 hour 30 minutes for rising","cook_time_text":"20 minutes","yield_type":"makes","yield_text":"30 to 32 rolls","ingredients":[{"source_text":"2 cups milk","source_pdf_page":144,"section":null,"position":1,"match_options":["milk"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 cups","related_recipe_id":null},{"source_text":"2 teaspoons active dry yeast","source_pdf_page":144,"section":null,"position":2,"match_options":["active dry yeast"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 teaspoons","related_recipe_id":null},{"source_text":"1/2 cup sugar, divided","source_pdf_page":144,"section":null,"position":3,"match_options":["sugar"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2 cup","related_recipe_id":null},{"source_text":"1/4 cup plus 1 tablespoon canola oil, divided","source_pdf_page":144,"section":null,"position":4,"match_options":["canola oil"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/4 cup","quantity_note":"Display source_text to preserve compound quantities and/or alternative amounts; quantity_prefix_text is only the leading amount.","related_recipe_id":null},{"source_text":"5 cups all-purpose flour, divided","source_pdf_page":144,"section":null,"position":5,"match_options":["flour"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"5 cups","related_recipe_id":null},{"source_text":"1 1/2 teaspoons salt","source_pdf_page":144,"section":null,"position":6,"match_options":["salt"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 1/2 teaspoons","related_recipe_id":null},{"source_text":"1 cup bread crumbs","source_pdf_page":144,"section":null,"position":7,"match_options":["bread crumb"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 cup","related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"In a saucepan, heat the milk to 110°F."},{"step":2,"source_step":2,"section":null,"text":"In a stand mixer or medium bowl, combine the milk, yeast, and 1 teaspoon of sugar. Stir until the sugar is dissolved. Let it stand until bubbles appear, 10 to 15 minutes."},{"step":3,"source_step":3,"section":null,"text":"When the yeast is bubbly, add the remaining sugar, 1/4 cup of canola oil, 1 cup of flour, and salt. Add 3 1/2 cups of flour, a 1/2 cup at a time, stirring with a spatula or wooden spoon after each addition."},{"step":4,"source_step":4,"section":null,"text":"Using the dough hook, mix the dough at medium speed until it pulls together and creates a ball, about 7 to 8 minutes."},{"step":5,"source_step":5,"section":null,"text":"Oil a large bowl with the remaining 1 tablespoon of oil. Gather the ball and transfer it to the bowl. Turn the dough to coat well with the oil. Cover the bowl with a damp cloth and let the dough rise in a warm place for an hour, or until it has doubled in size."},{"step":6,"source_step":6,"section":null,"text":"Preheat the oven to 350°F. Line two baking sheets with parchment paper or silicone baking mats."},{"step":7,"source_step":7,"section":null,"text":"Use the remaining 1/2 cup of flour to lightly flour a clean work surface. In a small bowl, place the bread crumbs."},{"step":8,"source_step":8,"section":null,"text":"When the dough has risen, punch it down in the middle with a closed fist to remove excess air bubbles and turn out the dough onto the floured work surface."},{"step":9,"source_step":9,"section":null,"text":"Divide the dough into 30 to 32 equal parts. Shape the pieces into ovals or rough balls and roll each one in the bread crumbs."},{"step":10,"source_step":10,"section":null,"text":"Place the pieces of dough on the baking sheets about 1 inch apart. Cover the dough on each baking sheet with a damp cloth and let it rise a second time for 20 to 30 minutes."},{"step":11,"source_step":11,"section":null,"text":"Bake for 20 minutes, rotating the sheet pans after 10 minutes to ensure even baking. Serve warm."}],"source_tips":["PREP TIP: Eggs can also be added into the dough to give it a softer texture. Add 2 lightly beaten eggs after the yeast becomes foamy in step 1, then continue with the recipe as directed."],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[144,145],"printed_pages":[136,137]},"review_flags":["Additional waiting time is retained as text; do not display prep + cook as total elapsed time."],"prep_minutes":25,"cook_minutes":20,"additional_time_text":"1 hour 30 minutes for rising","default_image":null,"slug":"bread-rolls"},
{"id":87,"name":"Leche Flan","filipino_name":null,"category":"Snacks and Desserts","prep_time_text":"10 minutes","cook_time_text":"1 hour","yield_type":"serves","yield_text":"6","ingredients":[{"source_text":"1 cup sugar","source_pdf_page":146,"section":"FOR THE CARAMEL","position":1,"match_options":["sugar"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 cup","related_recipe_id":null},{"source_text":"1/4 cup water","source_pdf_page":146,"section":"FOR THE CARAMEL","position":2,"match_options":["water"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/4 cup","related_recipe_id":null},{"source_text":"12 large egg yolks","source_pdf_page":146,"section":"FOR THE LECHE FLAN","position":3,"match_options":["egg yolk"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"12","related_recipe_id":null},{"source_text":"1 (14-ounce) can condensed milk","source_pdf_page":146,"section":"FOR THE LECHE FLAN","position":4,"match_options":["condensed milk"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 (14-ounce) can","related_recipe_id":null},{"source_text":"1 (12-ounce) can evaporated milk","source_pdf_page":146,"section":"FOR THE LECHE FLAN","position":5,"match_options":["evaporated milk"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 (12-ounce) can","related_recipe_id":null},{"source_text":"1 cup sugar","source_pdf_page":146,"section":"FOR THE LECHE FLAN","position":6,"match_options":["sugar"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 cup","related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":"TO MAKE THE CARAMEL","text":"Take out 6 (6-ounce) ramekins."},{"step":2,"source_step":2,"section":"TO MAKE THE CARAMEL","text":"In a heavy-bottomed saucepan, combine the sugar and water over medium heat and let it melt. You can swirl the pan to move it around, but do not stir. Cook for 8 to 10 minutes."},{"step":3,"source_step":3,"section":"TO MAKE THE CARAMEL","text":"While hot, pour the caramel into ramekin molds, making sure the bottoms are covered. Set aside."},{"step":4,"source_step":1,"section":"TO MAKE THE LECHE FLAN","text":"Preheat the oven to 450°F."},{"step":5,"source_step":2,"section":"TO MAKE THE LECHE FLAN","text":"In a bowl, combine the egg yolks, condensed milk, evaporated milk, and sugar."},{"step":6,"source_step":3,"section":"TO MAKE THE LECHE FLAN","text":"Using a fine-mesh strainer, strain the batter into a bowl."},{"step":7,"source_step":4,"section":"TO MAKE THE LECHE FLAN","text":"Scoop 1/2 cup of batter into each caramel-lined ramekin and cover each with a square of aluminum foil."},{"step":8,"source_step":5,"section":"TO MAKE THE LECHE FLAN","text":"Place the ramekins into a baking pan with a high rim and fill with water to reach halfway up the side of the ramekins."},{"step":9,"source_step":6,"section":"TO MAKE THE LECHE FLAN","text":"Bake for 1 hour, or until a toothpick inserted into the center of the flan comes out clean. Take the pan out of the oven. Remove ramekins from the water and let them cool for 5 minutes."},{"step":10,"source_step":7,"section":"TO MAKE THE LECHE FLAN","text":"With a knife, cut around the edge of each ramekin. Then invert the ramekin onto a dessert plate to release flan. Serve cold or warm."}],"source_tips":["VARIATION TIP: Try adding 1 tablespoon of calamansi or lime zest to the batter after you strain it in step 3 for a citrus twist."],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[146,147],"printed_pages":[138,139]},"review_flags":["Multi-component recipe: preserve ingredient sections and instruction sections."],"prep_minutes":10,"cook_minutes":60,"additional_time_text":null,"default_image":null,"slug":"leche-flan"},
{"id":88,"name":"Cassava Cake","filipino_name":null,"category":"Snacks and Desserts","prep_time_text":"15 minutes","cook_time_text":"1 hour, plus 30 minutes to cool","yield_type":"serves","yield_text":"8","ingredients":[{"source_text":"1 1/2 pounds grated cassava","source_pdf_page":148,"section":"FOR THE CAKE","position":1,"match_options":["cassava"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 1/2 pounds","related_recipe_id":null},{"source_text":"2 cups coconut milk","source_pdf_page":148,"section":"FOR THE CAKE","position":2,"match_options":["coconut milk"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 cups","related_recipe_id":null},{"source_text":"2 cups frozen coconut strings (see tip)","source_pdf_page":148,"section":"FOR THE CAKE","position":3,"match_options":["coconut strings"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 cups","related_recipe_id":null},{"source_text":"1/2 cup sugar","source_pdf_page":148,"section":"FOR THE CAKE","position":4,"match_options":["sugar"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2 cup","related_recipe_id":null},{"source_text":"4 large egg yolks","source_pdf_page":148,"section":"FOR THE CUSTARD","position":5,"match_options":["egg yolk"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"4","related_recipe_id":null},{"source_text":"1/2 cup evaporated milk","source_pdf_page":148,"section":"FOR THE CUSTARD","position":6,"match_options":["evaporated milk"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2 cup","related_recipe_id":null},{"source_text":"1/2 cup condensed milk","source_pdf_page":148,"section":"FOR THE CUSTARD","position":7,"match_options":["condensed milk"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2 cup","related_recipe_id":null},{"source_text":"1/4 cup sugar","source_pdf_page":148,"section":"FOR THE CUSTARD","position":8,"match_options":["sugar"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/4 cup","related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":"TO MAKE THE CAKE","text":"Preheat the oven to 350°F."},{"step":2,"source_step":2,"section":"TO MAKE THE CAKE","text":"In a bowl, combine the grated cassava, coconut milk, coconut strings, and sugar."},{"step":3,"source_step":3,"section":"TO MAKE THE CAKE","text":"Pour the mixture into an 8-by-13-inch cake pan and bake for 30 minutes."},{"step":4,"source_step":1,"section":"TO MAKE THE CUSTARD","text":"While the cake is cooking, combine the egg yolks, evaporated milk, condensed milk, and sugar in a medium bowl."},{"step":5,"source_step":2,"section":"TO MAKE THE CUSTARD","text":"Once the cake has baked for 30 minutes, pour the custard batter over the cake and bake for another 30 minutes."},{"step":6,"source_step":3,"section":"TO MAKE THE CUSTARD","text":"Remove the cake from the oven and let it cool to room temperature, 15 to 30 minutes, before serving."}],"source_tips":["INGREDIENT TIP: Look for coconut strings in the freezer section of an Asian specialty market. If coconut strings are not available, fragrant fruits like fresh mango and pineapple make a great alternative."],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[148],"printed_pages":[140]},"review_flags":["Multi-component recipe: preserve ingredient sections and instruction sections."],"prep_minutes":15,"cook_minutes":60,"additional_time_text":null,"default_image":null,"slug":"cassava-cake"},
{"id":89,"name":"Chocolate Rice Porridge","filipino_name":"Champorado","category":"Snacks and Desserts","prep_time_text":"5 minutes","cook_time_text":"30 minutes","yield_type":"serves","yield_text":"4","ingredients":[{"source_text":"1 cup sweet rice","source_pdf_page":149,"section":null,"position":1,"match_options":["sweet rice"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 cup","related_recipe_id":null},{"source_text":"8 ounces semisweet chocolate","source_pdf_page":149,"section":null,"position":2,"match_options":["semisweet chocolate"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"8 ounces","related_recipe_id":null},{"source_text":"1 cup sugar","source_pdf_page":149,"section":null,"position":3,"match_options":["sugar"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 cup","related_recipe_id":null},{"source_text":"Coconut milk, for serving","source_pdf_page":149,"section":null,"position":4,"match_options":["coconut milk"],"match_rule":"single","role":"serving","required_for_matching":false,"quantity_prefix_text":null,"related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"In a medium pot, cover the rice in water by several inches. Heat over medium-high heat until it boils, then stir in the chocolate and sugar until the sugar dissolves and the chocolate melts."},{"step":2,"source_step":2,"section":null,"text":"Continue to boil for about 20 minutes, stirring constantly to prevent sticking, until a porridge-like consistency is achieved and the rice is completely soft."},{"step":3,"source_step":3,"section":null,"text":"Scoop the porridge into bowls, drizzle with coconut milk, and serve."}],"source_tips":[],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[149],"printed_pages":[141]},"review_flags":["Instructions mention water outside the ingredient list; source list retained. Review cooking/soaking water handling in the app."],"prep_minutes":5,"cook_minutes":30,"additional_time_text":null,"default_image":null,"slug":"chocolate-rice-porridge"},
{"id":90,"name":"Rice Cake With Coconut Curds","filipino_name":"Biko","category":"Snacks and Desserts","prep_time_text":"10 minutes","cook_time_text":"1 hour 25 minutes","yield_type":"serves","yield_text":"8","ingredients":[{"source_text":"1 1/2 cups coconut cream","source_pdf_page":150,"section":null,"position":1,"match_options":["coconut cream"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 1/2 cups","related_recipe_id":null},{"source_text":"2 cups sweet rice, rinsed 3 times","source_pdf_page":150,"section":null,"position":2,"match_options":["sweet rice"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 cups","related_recipe_id":null},{"source_text":"2 cups water","source_pdf_page":150,"section":null,"position":3,"match_options":["water"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 cups","related_recipe_id":null},{"source_text":"4 cups coconut milk","source_pdf_page":150,"section":null,"position":4,"match_options":["coconut milk"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"4 cups","related_recipe_id":null},{"source_text":"2 cups brown sugar","source_pdf_page":150,"section":null,"position":5,"match_options":["brown sugar"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 cups","related_recipe_id":null},{"source_text":"1/2 cup granulated sugar","source_pdf_page":150,"section":null,"position":6,"match_options":["sugar"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2 cup","related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"In a saucepan, pour the coconut cream. Place the pan over medium heat and continuously stir the coconut cream until the oil separates from the curds, about 20 minutes."},{"step":2,"source_step":2,"section":null,"text":"With a handheld strainer or skimmer, collect the curds and place them on a paper-towel-lined plate. Set aside. Reserve the remaining coconut oil in an airtight container for another use (see tip)."},{"step":3,"source_step":3,"section":null,"text":"Add the rice and water to a rice cooker. Cook for 30 minutes and then let it rest for 10 minutes with the lid still on."},{"step":4,"source_step":4,"section":null,"text":"In a medium saucepan, combine the coconut milk, brown sugar, and granulated sugar. Stir to dissolve and bring to a boil over medium-high heat."},{"step":5,"source_step":5,"section":null,"text":"Add the cooked rice to the saucepan, constantly stirring until the mixture thickens and pulls away from the pot, 20 to 25 minutes."},{"step":6,"source_step":6,"section":null,"text":"Divide the rice mixture into bowls and top with the coconut curds before serving."}],"source_tips":["INGREDIENT TIP: You can use coconut oil as a replacement for canola or olive oil in cooking. Coconut oil is also great when used in Party Paella (page 28)."],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[150],"printed_pages":[142]},"review_flags":[],"prep_minutes":10,"cook_minutes":85,"additional_time_text":null,"default_image":null,"slug":"rice-cake-with-coconut-curds"},
{"id":91,"name":"Rice Balls In Sweet Coconut Milk","filipino_name":"Ginataang Bilo Bilo","category":"Snacks and Desserts","prep_time_text":"15 minutes","cook_time_text":"45 minutes","yield_type":"serves","yield_text":"8","ingredients":[{"source_text":"2 cups sweet rice flour","source_pdf_page":151,"section":null,"position":1,"match_options":["rice flour"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 cups","related_recipe_id":null},{"source_text":"5 cups water, divided","source_pdf_page":151,"section":null,"position":2,"match_options":["water"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"5 cups","related_recipe_id":null},{"source_text":"1/4 cup mini tapioca pearls (optional)","source_pdf_page":151,"section":null,"position":3,"match_options":["tapioca pearl"],"match_rule":"single","role":"optional","required_for_matching":false,"quantity_prefix_text":"1/4 cup","related_recipe_id":null},{"source_text":"1 cup cubed sweet potato","source_pdf_page":151,"section":null,"position":4,"match_options":["sweet potato"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 cup","related_recipe_id":null},{"source_text":"1/2 cup cubed purple yam","source_pdf_page":151,"section":null,"position":5,"match_options":["purple yam"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2 cup","related_recipe_id":null},{"source_text":"1 cup saba banana or plantain, sliced into 1/4-inch medallions","source_pdf_page":151,"section":null,"position":6,"match_options":["saba banana","plantain"],"match_rule":"any_of","role":"main","required_for_matching":true,"quantity_prefix_text":"1 cup","related_recipe_id":null},{"source_text":"1/2 cup jackfruit, cut into strips","source_pdf_page":151,"section":null,"position":7,"match_options":["jackfruit"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2 cup","related_recipe_id":null},{"source_text":"4 cups coconut milk","source_pdf_page":151,"section":null,"position":8,"match_options":["coconut milk"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"4 cups","related_recipe_id":null},{"source_text":"3 cups sugar","source_pdf_page":151,"section":null,"position":9,"match_options":["sugar"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3 cups","related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"In a bowl, combine the flour and 1 cup of water and work into a smooth dough to make sticky rice balls."},{"step":2,"source_step":2,"section":null,"text":"Using the palms of your hands, roll pieces of the dough in a circular motion into about 30 marble-sized balls. Set aside."},{"step":3,"source_step":3,"section":null,"text":"In a deep pot, pour the remaining 4 cups water and bring to a boil. Add the tapioca (if using) and cook for 20 minutes."},{"step":4,"source_step":4,"section":null,"text":"Once the tapioca is cooked, add the rice balls. Continuously stir to prevent the rice balls from sticking. After about 10 minutes, when rice balls begin to float, add the sweet potato and yam. After a few minutes, add the banana and jackfruit."},{"step":5,"source_step":5,"section":null,"text":"Add the coconut milk and sugar. Stir to combine and cook for 10 minutes, stirring regularly to prevent sticking, until the liquid reduces to the consistency of a thick stew."}],"source_tips":[],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[151],"printed_pages":[143]},"review_flags":[],"prep_minutes":15,"cook_minutes":45,"additional_time_text":null,"default_image":null,"slug":"rice-balls-in-sweet-coconut-milk"},
{"id":92,"name":"Banana And Jackfruit Lumpia","filipino_name":"Turon","category":"Snacks and Desserts","prep_time_text":"15 minutes","cook_time_text":"10 minutes","yield_type":"serves","yield_text":"2","ingredients":[{"source_text":"4 lumpia wrappers","source_pdf_page":152,"section":null,"position":1,"match_options":["lumpia wrapper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"4","related_recipe_id":null},{"source_text":"2 saba bananas or 1 plantain, peeled and cut in half lengthwise","source_pdf_page":152,"section":null,"position":2,"match_options":["saba banana","plantain"],"match_rule":"any_of","role":"main","required_for_matching":true,"quantity_prefix_text":"2","quantity_note":"Display source_text to preserve compound quantities and/or alternative amounts; quantity_prefix_text is only the leading amount.","related_recipe_id":null},{"source_text":"1/4 cup thinly sliced jackfruit","source_pdf_page":152,"section":null,"position":3,"match_options":["jackfruit"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/4 cup","related_recipe_id":null},{"source_text":"1/4 cup sugar","source_pdf_page":152,"section":null,"position":4,"match_options":["sugar"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/4 cup","related_recipe_id":null},{"source_text":"1 egg, beaten","source_pdf_page":152,"section":null,"position":5,"match_options":["egg"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"3 cups canola oil","source_pdf_page":152,"section":null,"position":6,"match_options":["canola oil"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3 cups","related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"Separate the lumpia sheets and arrange them on a large, clean work surface. Cover the wrappers with a damp cloth to prevent drying as you work."},{"step":2,"source_step":2,"section":null,"text":"Place a wrapper diagonally in front of you, so it looks like a diamond. Place a piece of banana on the lumpia wrapper about 1 inch inside the corner closest to you."},{"step":3,"source_step":3,"section":null,"text":"Place pieces of jackfruit on top of the banana and then sprinkle with about 1 tablespoon sugar."},{"step":4,"source_step":4,"section":null,"text":"Flip the corner closest to you over the fruit, and then fold the left and right sides toward the center. Finish by firmly rolling the banana away from you, toward the top corner of the diamond."},{"step":5,"source_step":5,"section":null,"text":"Using a pastry brush, brush the edges of the lumpia with the egg to seal. Repeat until all wrappers are full."},{"step":6,"source_step":6,"section":null,"text":"In a large sauté pan or skillet, heat the oil over medium heat. Fry the lumpia for 5 to 7 minutes, or until golden brown."}],"source_tips":["SUBSTITUTION TIP: Use brown sugar instead of white sugar for added flavor.","PREP TIP: You can freeze the unfried lumpia for up to 3 months. To cook from frozen, increase cooking time to 10 to 12 minutes."],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[152],"printed_pages":[144]},"review_flags":[],"prep_minutes":15,"cook_minutes":10,"additional_time_text":null,"default_image":null,"slug":"banana-and-jackfruit-lumpia"},
{"id":93,"name":"Soy Sauce And Calamansi Dipping Sauce","filipino_name":"Toyomansi","category":"Staples","prep_time_text":"5 minutes","cook_time_text":"5 minutes","yield_type":"makes","yield_text":"2 1/2 cups","ingredients":[{"source_text":"1 cup soy sauce","source_pdf_page":156,"section":null,"position":1,"match_options":["soy sauce"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 cup","related_recipe_id":null},{"source_text":"1 cup freshly squeezed calamansi juice or lemon juice","source_pdf_page":156,"section":null,"position":2,"match_options":["calamansi","lemon"],"match_rule":"any_of","role":"main","required_for_matching":true,"quantity_prefix_text":"1 cup","related_recipe_id":null},{"source_text":"2 tablespoons minced garlic","source_pdf_page":156,"section":null,"position":3,"match_options":["garlic"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 tablespoons","related_recipe_id":null},{"source_text":"2 Thai chiles or jalapeño peppers, chopped with seeds","source_pdf_page":156,"section":null,"position":4,"match_options":["thai chili","jalapeno"],"match_rule":"any_of","role":"main","required_for_matching":true,"quantity_prefix_text":"2","related_recipe_id":null}],"instructions":[{"step":1,"source_step":null,"section":null,"text":"In a small bowl, mix the soy sauce and calamansi juice and garlic. Add the chiles and stir. Let the sauce sit for 5 minutes to incorporate the flavor."}],"source_tips":["VARIATION TIP: Sometimes it is nice to add a little sweetness to this dipping sauce. To do so, you can add up to 1/2 cup of sugar."],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[156],"printed_pages":[148]},"review_flags":[],"prep_minutes":5,"cook_minutes":5,"additional_time_text":null,"default_image":null,"slug":"soy-sauce-and-calamansi-dipping-sauce"},
{"id":94,"name":"Fresh Lumpia Sauce","filipino_name":"Lumpia Sariwa Sauce","category":"Staples","prep_time_text":"5 minutes","cook_time_text":"10 minutes","yield_type":"makes","yield_text":"2 cups","ingredients":[{"source_text":"2 cups plus 2 tablespoons water, divided","source_pdf_page":157,"section":null,"position":1,"match_options":["water"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 cups","quantity_note":"Display source_text to preserve compound quantities and/or alternative amounts; quantity_prefix_text is only the leading amount.","related_recipe_id":null},{"source_text":"1/2 cup sugar","source_pdf_page":157,"section":null,"position":2,"match_options":["sugar"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2 cup","related_recipe_id":null},{"source_text":"1 tablespoon soy sauce","source_pdf_page":157,"section":null,"position":3,"match_options":["soy sauce"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 tablespoon","related_recipe_id":null},{"source_text":"1 tablespoon minced garlic","source_pdf_page":157,"section":null,"position":4,"match_options":["garlic"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 tablespoon","related_recipe_id":null},{"source_text":"1/2 teaspoon salt","source_pdf_page":157,"section":null,"position":5,"match_options":["salt"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2 teaspoon","related_recipe_id":null},{"source_text":"2 tablespoons cornstarch","source_pdf_page":157,"section":null,"position":6,"match_options":["cornstarch"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 tablespoons","related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"In a medium saucepan, heat 2 cups of water, the sugar, soy sauce, garlic, and salt over medium heat. Boil for 3 minutes, or until the sugar dissolves."},{"step":2,"source_step":2,"section":null,"text":"In a small bowl, combine the cornstarch and remaining 2 tablespoons of water and mix well."},{"step":3,"source_step":3,"section":null,"text":"Add the cornstarch slurry to the sauce and simmer until the consistency is between honey and maple syrup. Taste and adjust the seasoning as desired. Transfer to a small serving bowl."}],"source_tips":[],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[157],"printed_pages":[149]},"review_flags":[],"prep_minutes":5,"cook_minutes":10,"additional_time_text":null,"default_image":null,"slug":"fresh-lumpia-sauce"},
{"id":95,"name":"Spiced Vinegar","filipino_name":"Sukang Maanghang","category":"Staples","prep_time_text":"15 minutes","cook_time_text":"5 minutes","yield_type":"makes","yield_text":"2 1/2 cups","ingredients":[{"source_text":"12 Thai chiles or 2 jalapeño peppers, minced","source_pdf_page":158,"section":null,"position":1,"match_options":["thai chili","jalapeno"],"match_rule":"any_of","role":"main","required_for_matching":true,"quantity_prefix_text":"12","quantity_note":"Display source_text to preserve compound quantities and/or alternative amounts; quantity_prefix_text is only the leading amount.","related_recipe_id":null},{"source_text":"5 garlic cloves, minced","source_pdf_page":158,"section":null,"position":2,"match_options":["garlic"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"5","related_recipe_id":null},{"source_text":"1 tablespoon peeled minced ginger","source_pdf_page":158,"section":null,"position":3,"match_options":["ginger"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 tablespoon","related_recipe_id":null},{"source_text":"1 teaspoon freshly ground black pepper","source_pdf_page":158,"section":null,"position":4,"match_options":["black pepper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 teaspoon","related_recipe_id":null},{"source_text":"2 cups vinegar","source_pdf_page":158,"section":null,"position":5,"match_options":["vinegar"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 cups","related_recipe_id":null},{"source_text":"2 tablespoons sugar","source_pdf_page":158,"section":null,"position":6,"match_options":["sugar"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 tablespoons","related_recipe_id":null},{"source_text":"1 teaspoon salt","source_pdf_page":158,"section":null,"position":7,"match_options":["salt"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 teaspoon","related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"In a 12-ounce glass jar or nonreactive container, combine the chiles, garlic, ginger, and pepper and set aside."},{"step":2,"source_step":2,"section":null,"text":"In a medium saucepan, whisk the vinegar, sugar, and salt and bring to a boil over medium heat for about 3 minutes."},{"step":3,"source_step":3,"section":null,"text":"Let the mixture cool for about 10 minutes, then pour into the jar over the chiles, ginger, garlic, and pepper mixture. LEFTOVERS TIP: Store leftover vinegar in an airtight container in the refrigerator for up to 1 year."}],"source_tips":[],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[158],"printed_pages":[150]},"review_flags":[],"prep_minutes":15,"cook_minutes":5,"additional_time_text":null,"default_image":null,"slug":"spiced-vinegar"},
{"id":96,"name":"Lechon Sauce","filipino_name":null,"category":"Staples","prep_time_text":"10 minutes","cook_time_text":"10 minutes","yield_type":"makes","yield_text":"4 1/2 cups","ingredients":[{"source_text":"3 1/2 cups water","source_pdf_page":159,"section":null,"position":1,"match_options":["water"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3 1/2 cups","related_recipe_id":null},{"source_text":"2 cups brown sugar","source_pdf_page":159,"section":null,"position":2,"match_options":["brown sugar"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 cups","related_recipe_id":null},{"source_text":"1/2 cup vinegar","source_pdf_page":159,"section":null,"position":3,"match_options":["vinegar"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2 cup","related_recipe_id":null},{"source_text":"2 tablespoons salt","source_pdf_page":159,"section":null,"position":4,"match_options":["salt"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 tablespoons","related_recipe_id":null},{"source_text":"1 tablespoon garlic powder","source_pdf_page":159,"section":null,"position":5,"match_options":["garlic powder"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 tablespoon","related_recipe_id":null},{"source_text":"1 tablespoon onion powder","source_pdf_page":159,"section":null,"position":6,"match_options":["onion powder"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 tablespoon","related_recipe_id":null},{"source_text":"1 teaspoon freshly ground black pepper","source_pdf_page":159,"section":null,"position":7,"match_options":["black pepper"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 teaspoon","related_recipe_id":null},{"source_text":"2 cups bread crumbs or panko","source_pdf_page":159,"section":null,"position":8,"match_options":["bread crumb","panko"],"match_rule":"any_of","role":"main","required_for_matching":true,"quantity_prefix_text":"2 cups","related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"In a medium saucepan, whisk together the water, brown sugar, vinegar, salt, garlic powder, onion powder, and pepper and bring to a boil over medium heat for 3 minutes, until the sugar dissolves."},{"step":2,"source_step":2,"section":null,"text":"Add the bread crumbs and stir until incorporated and then cook for about 2 minutes, until the sauce thickens to the consistency of ketchup or barbecue sauce. Taste and adjust the seasoning as desired. Serve immediately or store in the refrigerator for up to 3 months."}],"source_tips":["SUBSTITUTION TIP: For a more traditional take, you can substitute 1 cup of liver pâté or ground pork liver for 1 cup of bread crumbs."],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[159],"printed_pages":[151]},"review_flags":[],"prep_minutes":10,"cook_minutes":10,"additional_time_text":null,"default_image":null,"slug":"lechon-sauce"},
{"id":97,"name":"Sweet-And-Sour Lumpia Sauce","filipino_name":null,"category":"Staples","prep_time_text":"10 minutes","cook_time_text":"10 minutes","yield_type":"makes","yield_text":"1 1/2 cups","ingredients":[{"source_text":"1 cup water plus 1/2 teaspoon water, divided","source_pdf_page":160,"section":null,"position":1,"match_options":["water"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 cup","quantity_note":"Display source_text to preserve compound quantities and/or alternative amounts; quantity_prefix_text is only the leading amount.","related_recipe_id":null},{"source_text":"1 cup sugar","source_pdf_page":160,"section":null,"position":2,"match_options":["sugar"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 cup","related_recipe_id":null},{"source_text":"3 tablespoons vinegar","source_pdf_page":160,"section":null,"position":3,"match_options":["vinegar"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"3 tablespoons","related_recipe_id":null},{"source_text":"1 Thai chile or 1/2 jalapeño pepper, seeded and minced","source_pdf_page":160,"section":null,"position":4,"match_options":["thai chili","jalapeno"],"match_rule":"any_of","role":"main","required_for_matching":true,"quantity_prefix_text":"1","quantity_note":"Display source_text to preserve compound quantities and/or alternative amounts; quantity_prefix_text is only the leading amount.","related_recipe_id":null},{"source_text":"1 teaspoon minced garlic","source_pdf_page":160,"section":null,"position":5,"match_options":["garlic"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 teaspoon","related_recipe_id":null},{"source_text":"1/4 teaspoon paprika","source_pdf_page":160,"section":null,"position":6,"match_options":["paprika"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/4 teaspoon","related_recipe_id":null},{"source_text":"1/4 teaspoon salt","source_pdf_page":160,"section":null,"position":7,"match_options":["salt"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/4 teaspoon","related_recipe_id":null},{"source_text":"1 1/2 teaspoons cornstarch","source_pdf_page":160,"section":null,"position":8,"match_options":["cornstarch"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1 1/2 teaspoons","related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":null,"text":"In a medium saucepan, whisk together 1 cup of water, sugar, vinegar, chile, garlic, paprika, and salt. Heat over medium heat and let the vinegar mixture boil for 3 minutes, until the sugar dissolves."},{"step":2,"source_step":2,"section":null,"text":"In a small bowl, combine the cornstarch and remaining 1/2 teaspoon of water, mix well, and pour into the pan. Simmer for 3 minutes, until the sauce has consistency of light honey."},{"step":3,"source_step":3,"section":null,"text":"Transfer to a small dipping sauce bowl and serve with fried lumpia. LEFTOVERS TIP: Store leftovers refrigerated in an airtight container for up to 1 month."}],"source_tips":[],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[160],"printed_pages":[152]},"review_flags":[],"prep_minutes":10,"cook_minutes":10,"additional_time_text":null,"default_image":null,"slug":"sweet-and-sour-lumpia-sauce"},
