{"id":100,"name":"Tomato, Onion, And Salted Egg Salad","filipino_name":"Itlog Na Maalat At Kamatis","category":"Staples","prep_time_text":"5 minutes, plus 21 days to brine","cook_time_text":"5 minutes","yield_type":"serves","yield_text":"2 to 4","ingredients":[{"source_text":"12 large eggs, rinsed and patted dry","source_pdf_page":163,"section":"FOR THE SALTED EGGS","position":1,"match_options":["egg"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"12","related_recipe_id":null},{"source_text":"4 cups water","source_pdf_page":163,"section":"FOR THE SALTED EGGS","position":2,"match_options":["water"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"4 cups","related_recipe_id":null},{"source_text":"2 cups salt","source_pdf_page":163,"section":"FOR THE SALTED EGGS","position":3,"match_options":["salt"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2 cups","related_recipe_id":null},{"source_text":"2 salted hardboiled eggs, halved","source_pdf_page":163,"section":"FOR THE SALAD","position":4,"match_options":["salted egg"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"2","related_recipe_id":null},{"source_text":"1 tomato, cut into 1/4-inch cubes","source_pdf_page":163,"section":"FOR THE SALAD","position":5,"match_options":["tomato"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1","related_recipe_id":null},{"source_text":"1/2 onion, cut into 1/4-inch cubes","source_pdf_page":163,"section":"FOR THE SALAD","position":6,"match_options":["onion"],"match_rule":"single","role":"main","required_for_matching":true,"quantity_prefix_text":"1/2","related_recipe_id":null}],"instructions":[{"step":1,"source_step":1,"section":"TO MAKE THE SALTED EGGS","text":"Carefully arrange the eggs inside a wide-mouthed, lidded 1-quart jar."},{"step":2,"source_step":2,"section":"TO MAKE THE SALTED EGGS","text":"Boil the water and salt, stirring until the salt dissolves, about 2 to 3 minutes. Turn the heat off and let cool to room temperature (72°F or below)."},{"step":3,"source_step":3,"section":"TO MAKE THE SALTED EGGS","text":"Pour the brine into the jar, covering all the eggs. Ensure the eggs remain submerged by filling the jar with crumpled parchment paper or a resealable bag with water. Cover and store it in a cool place for 21 days."},{"step":4,"source_step":4,"section":"TO MAKE THE SALTED EGGS","text":"Test by boiling one egg for 8 minutes, then crack it open and taste. The egg white should be salty, and the yolk less salty. If satisfied, boil the remaining eggs, cool, and refrigerate for up to one month, or let brine."},{"step":5,"source_step":null,"section":"TO MAKE THE SALAD","text":"In a small bowl, mix the eggs with the tomato and onions."}],"source_tips":[],"source":{"title":"The Easy Filipino Cookbook","file_name":"easyfilipinocookbook_cropped.pdf","pdf_pages":[163],"printed_pages":[155]},"review_flags":["Additional waiting time is retained as text; do not display prep + cook as total elapsed time.","Multi-component recipe: preserve ingredient sections and instruction sections.","Salted eggs are made as a subrecipe over 21 days; pre-made salted eggs can bypass that component. Do not require both raw and salted eggs for the shortcut."],"prep_minutes":5,"cook_minutes":5,"additional_time_text":"21 days to brine","default_image":null,"slug":"tomato-onion-and-salted-egg-salad"}
